INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1009, 'es-ES', 'Garantizar las rutas de evacuación, establecer una red de contactos de emergencia y realizar formación sobre los escenarios de respuesta a incidentes según el Plan de Autoprotección.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1009, 'ru-RU', 'Обеспечение путей эвакуации, создание системы экстренной связи и проведение обучения по сценариям реагирования на аварии в соответствии с Планом ликвидации аварий (ПЛА).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1010, 'es-ES', 'Realizar inspecciones periódicas para asegurar la disponibilidad de las rutas de evacuación y el estado operativo de la red de contactos de emergencia para cada escenario de incidente.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1010, 'ru-RU', 'Регулярная проверка проходимости путей эвакуации и работоспособности системы экстренной связи согласно сценариям возможных аварий.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1017, 'es-ES', 'Instalar señalización de advertencia clara en las zonas de acceso restringido y designar a un responsable de control de accesos para una vigilancia permanente.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1017, 'ru-RU', 'Установка четких предупреждающих знаков в зонах с ограниченным доступом и назначение ответственного за контроль доступа для постоянного наблюдения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1018, 'es-ES', 'Instalar un doble sistema de barreras en zonas de trabajos simultáneos o de alto riesgo y detener inmediatamente los trabajos si accede personal no autorizado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1018, 'ru-RU', 'Установка двойного ограждения в зонах пересекающихся или особо опасных работ и немедленное прекращение работ при доступе посторонних лиц.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1019, 'es-ES', 'Antes de iniciar los trabajos, delimitar la zona con cinta de seguridad, conos y barreras, estableciendo un doble perímetro de seguridad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1019, 'ru-RU', 'Перед началом работ установить оградительную ленту, конусы, барьеры и обеспечить двойное ограждение рабочей зоны.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1020, 'es-ES', 'Establecer líneas de control de acceso y colocar señalización de advertencia (prohibido el paso, trabajos en altura, etc.), designando a un responsable de control de accesos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1020, 'ru-RU', 'Установка линии контроля доступа и размещение предупреждающих знаков (''Вход воспрещен'', ''Работа на высоте''), с назначением ответственного за контроль доступа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1003, 'es-ES', 'Realizar una charla de seguridad (Toolbox Meeting) antes del inicio de los trabajos para instruir sobre el contenido de la tarea, los riesgos identificados y las medidas preventivas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1003, 'ru-RU', 'Проведение целевого инструктажа (TBM) перед началом работ для разъяснения содержания работ, опасных факторов и правил техники безопасности.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1004, 'es-ES', 'Verificar la entrega de los Equipos de Protección Individual (EPI) necesarios para cada tarea y supervisar regularmente su correcto uso por parte del responsable de obra.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1004, 'ru-RU', 'Проверка ведомости выдачи необходимых средств индивидуальной защиты (СИЗ) для каждого вида работ и регулярный контроль их правильного применения руководителем работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1005, 'es-ES', 'Impartir formación periódica sobre las directrices de uso de EPI y realizar demostraciones prácticas sobre su correcta colocación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1005, 'ru-RU', 'Проведение регулярного обучения по правилам использования СИЗ и организация практических демонстраций по их правильному применению.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1006, 'es-ES', 'Gestionar un punto de sustitución de EPI en la obra para el reemplazo inmediato de equipos desgastados o dañados, y controlar el stock disponible.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1006, 'ru-RU', 'Организация на объекте пункта для немедленной замены изношенных или поврежденных СИЗ и ведение учета их количества.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1007, 'es-ES', 'Realizar formación sobre las directrices de uso de EPI y mantener un registro firmado de la asistencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1007, 'ru-RU', 'Проведение инструктажа по правилам ношения СИЗ и ведение журнала учета с подписями работников.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1008, 'es-ES', 'Durante la charla de seguridad (TBM), informar sobre los EPI obligatorios para cada tarea y demostrar su correcta colocación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1008, 'ru-RU', 'Во время целевого инструктажа (TBM) информировать о необходимых для конкретной работы СИЗ и демонстрировать правильные способы их применения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1011, 'es-ES', 'Tras ponerse el traje de protección contra el polvo, realizar una comprobación mutua para verificar posibles daños y el correcto sellado (verificación visual por pares).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1011, 'ru-RU', 'После надевания пылезащитного костюма провести взаимную проверку на наличие повреждений и герметичность (визуальный осмотр в парах).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1021, 'es-ES', 'Establecer rutas de tránsito diferenciadas para los trabajadores y comunicar las zonas de riesgo durante la charla de seguridad (TBM) previa al trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1021, 'ru-RU', 'Разделение маршрутов передвижения работников и информирование об опасных зонах во время целевого инструктажа (TBM) перед началом работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1022, 'es-ES', 'En trabajos nocturnos, utilizar balizas luminosas y señalización reflectante para garantizar la visibilidad de la posición de los trabajadores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1022, 'ru-RU', 'При работе в ночное время использовать проблесковые маячки и светоотражающие знаки для обеспечения видимости местоположения работников.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1023, 'es-ES', 'Emitir y verificar la correcta colocación del permiso de trabajo y de las etiquetas de consignación (p. ej., en válvulas de gas o interruptores eléctricos).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1023, 'ru-RU', 'Оформление наряда-допуска и проверка правильности вывешивания бирок (на электрических рубильниках, газовых вентилях).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1024, 'es-ES', 'Asegurar la visibilidad de la señalización de rutas de evacuación de emergencia y consultar los planos correspondientes al área de trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1024, 'ru-RU', 'Обеспечение видимости знаков эвакуационных выходов и сверка с рабочими чертежами в случае аварии.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1025, 'es-ES', 'Realizar una inspección previa del estado del suelo para eliminar cualquier residuo de aceite o agua.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1025, 'ru-RU', 'Проведение предварительной проверки состояния пола для удаления масляных и водных пятен.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1026, 'es-ES', 'Instalar alfombras antideslizantes y utilizar cubiertas impermeables o agentes antideslizantes (arena, etc.).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1026, 'ru-RU', 'Установка противоскользящих ковриков и использование водонепроницаемых покрытий или противоскользящих материалов (песок и т.д.).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1027, 'es-ES', 'Prohibir el almacenamiento de materiales y herramientas en las vías de acceso y retirarlos de inmediato.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1027, 'ru-RU', 'Информирование о запрете складирования материалов и инструментов на проходах и их немедленное удаление.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1028, 'es-ES', 'Inspeccionar constantemente el estado de las rutas de evacuación y las vías de tránsito para garantizar que estén despejadas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1028, 'ru-RU', 'Постоянная проверка состояния путей эвакуации и проходов на предмет отсутствия препятствий.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1029, 'es-ES', 'Antes de realizar trabajos eléctricos, estudiar el esquema del circuito, desconectar el interruptor y medir la tensión residual.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1029, 'ru-RU', 'Перед электромонтажными работами изучить схему цепи, отключить питание и измерить остаточное напряжение.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1030, 'es-ES', 'En caso de energía residual, descargarla utilizando una pértiga de puesta a tierra o un dispositivo de descarga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1030, 'ru-RU', 'При наличии остаточной энергии выполнить разрядку с помощью заземляющей штанги или разрядного устройства (заземление остаточного заряда).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1031, 'es-ES', 'En equipos con elementos giratorios o accionados por motor, aislar la energía mecánica utilizando pasadores de bloqueo (Lock-pins) u otros dispositivos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1031, 'ru-RU', 'В случае вращающихся частей или электроприводов, изолировать механическую энергию с помощью стопорных штифтов (Lock-pin).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1032, 'es-ES', 'Utilizar dispositivos de bloqueo en válvulas y actuadores para prevenir su accionamiento accidental, estableciendo un protocolo de desbloqueo solo por personal autorizado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1032, 'ru-RU', 'Применение блокировочных устройств на клапанах и приводах для предотвращения самопроизвольного срабатывания и соблюдение принципа снятия блокировки только уполномоченным работником.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1033, 'es-ES', 'Tras la desconexión, instalar dispositivos de consignación (Lock-out) y colocar etiquetas de ''No operar'' (Tag-out), gestionando la identificación de los trabajadores autorizados.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1033, 'ru-RU', 'После отключения питания установить блокирующие устройства (Lock-out), вывесить запрещающую табличку ''Не включать!'' и вести учет допущенных к работе лиц.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1034, 'es-ES', 'Antes de restablecer la energía, verificar la evacuación de todo el personal del área y realizar una inspección final de anomalías.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1034, 'ru-RU', 'Перед восстановлением питания убедиться в отсутствии персонала на всем участке, провести окончательную проверку на наличие неисправностей и только после этого подавать напряжение.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1035, 'es-ES', 'Para la protección contra contactos eléctricos, es obligatorio el uso de EPI específicos para alta tensión, como guantes dieléctricos, pantallas faciales y herramientas aislantes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1035, 'ru-RU', 'Для защиты от поражения электрическим током обязательно использовать специальные СИЗ для работы с высоким напряжением: диэлектрические перчатки, защитные лицевые щитки, изолированный инструмент.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1036, 'es-ES', 'En trabajos con múltiples personas, instalar señalización clara en todos los puntos de desconexión de energía e indicar los nombres de los trabajadores implicados.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1036, 'ru-RU', 'При выполнении работ несколькими бригадами установить четкие таблички на всех точках отключения питания с указанием ФИО работников.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1037, 'es-ES', 'El responsable de la consignación (LOTO) debe comunicar claramente durante la charla de seguridad (TBM) el tipo de energía, los puntos de bloqueo y los equipos a inspeccionar.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1037, 'ru-RU', 'Ответственный за выполнение LOTO должен четко сообщить на целевом инструктаже (TBM) тип энергии, точки отключения и объекты проверки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1050, 'es-ES', 'Delimitar claramente las zonas de generación de llamas/chispas y restringir el paso y acceso con cinta de seguridad y barreras.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1050, 'ru-RU', 'Четко определить зоны образования пламени/искр и ограничить проход и доступ с помощью оградительной ленты и барьеров.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1049, 'es-ES', 'Tras purgar tuberías y depósitos con contenido residual, medir la concentración de oxígeno/gas y detener el trabajo inmediatamente si se superan los límites permitidos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1049, 'ru-RU', 'После продувки трубопроводов и резервуаров с остаточным содержимым измерить концентрацию кислорода/газа и немедленно прекратить работу при превышении допустимых значений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1051, 'es-ES', 'Durante la charla de seguridad (TBM), instruir a todo el personal sobre los riesgos de la zona, los métodos de evacuación y los procedimientos de respuesta a incendios, y obtener una firma de confirmación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1051, 'ru-RU', 'На целевом инструктаже (TBM) провести обучение всего персонала по опасным факторам, способам эвакуации и действиям при пожаре с обязательной подписью в журнале.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1052, 'es-ES', 'El vigilante de incendios debe permanecer en el lugar desde antes del inicio hasta la finalización de los trabajos, y mantener equipos de extinción de emergencia (extintores, mantas ignífugas) a mano.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1052, 'ru-RU', 'Наблюдающий за огневыми работами должен присутствовать на месте с начала до окончания работ и иметь в непосредственной близости первичные средства пожаротушения (огнетушители, противопожарное полотно).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1053, 'es-ES', 'Asignar un vigilante de incendios dedicado y establecer un sistema de monitorización continua para la detección de fuentes de ignición en la zona de trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1053, 'ru-RU', 'Назначение ответственного наблюдающего за огневыми работами и создание системы постоянного мониторинга источников зажигания в рабочей зоне.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1054, 'es-ES', 'El vigilante de incendios debe llevar un equipo de comunicación de emergencia (radio, etc.) y conocer el procedimiento para guiar la evacuación de los trabajadores cercanos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1054, 'ru-RU', 'Наблюдающий за огневыми работами должен иметь при себе средства экстренной связи (рацию и т.п.) и знать порядок эвакуации работников, находящихся поблизости.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1056, 'es-ES', 'Al interrumpir o finalizar el trabajo, verificar que las válvulas del soplete están cerradas y la máquina de soldar desconectada de la corriente.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1056, 'ru-RU', 'При перерыве или завершении работы проверить перекрытие вентилей горелки и отключение сварочного аппарата от источника питания.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1057, 'es-ES', 'Verificar el estado de la puesta a tierra de la carcasa del soldador y el estado de los cables, y reforzar las medidas de aislamiento si se trabaja en lugares húmedos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1057, 'ru-RU', 'Проверить заземление корпуса сварочного аппарата и целостность кабелей, при работе во влажных местах усилить меры по изоляции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1061, 'es-ES', 'Antes de empezar a trabajar, retirar y limpiar cualquier material combustible (residuos, aceites, papel, etc.) en un radio de 10 metros.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1061, 'ru-RU', 'Перед началом работ убрать и очистить территорию в радиусе 10 метров от горючих материалов (отходов, масел, бумаги и т.д.).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1062, 'es-ES', 'Comprobar si hay fugas en las conexiones de las mangueras de gas (con agua jabonosa, etc.) y verificar la instalación del dispositivo antirretorno de llama.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1062, 'ru-RU', 'Проверить герметичность соединений газовых шлангов (мыльным раствором и т.п.) и исправность установки огнепреградительного клапана.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1063, 'es-ES', 'Cubrir los equipos combustibles que no se puedan mover con lonas ignífugas o mantas resistentes al fuego.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1063, 'ru-RU', 'Неперемещаемое горючее оборудование укрыть негорючими листами или огнезащитным полотном.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1067, 'es-ES', 'Exigir que todo el personal en la zona de trabajos en caliente vista ropa de trabajo y EPI de material ignífugo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1067, 'ru-RU', 'Обязать весь персонал в зоне проведения огневых работ носить спецодежду и СИЗ из огнестойких материалов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1076, 'es-ES', 'Fijar firmemente las plataformas de trabajo para evitar desplazamientos o desprendimientos y, si es necesario, instalar redes de seguridad contra caídas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1076, 'ru-RU', 'Рабочий настил должен быть надежно закреплен для предотвращения смещения и срыва, при необходимости установить защитно-улавливающие сетки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1077, 'es-ES', 'Instalar la plataforma de trabajo con una anchura suficiente para que el trabajador pueda moverse de forma segura.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1077, 'ru-RU', 'Рабочая площадка должна быть достаточной ширины для обеспечения безопасного передвижения работника.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1078, 'es-ES', 'Prohibir el almacenamiento directo de materiales sobre la plataforma y verificar antes del trabajo que las herramientas se guardan en bolsas o cajas específicas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1078, 'ru-RU', 'Запретить прямое складирование материалов на настиле и перед работой проверить, что инструменты хранятся в специальных сумках/ящиках.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1079, 'es-ES', 'Los trabajadores en altura deben cumplir el principio de doble anclaje (arnés y línea de vida) y volver a comprobar el estado de sus EPI.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1079, 'ru-RU', 'Соблюдение работниками на высоте принципа двойной страховки (использование двух строп с карабинами) и перепроверка состояния СИЗ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1081, 'es-ES', 'Realizar simulacros de evacuación para situaciones de emergencia y verificar la disponibilidad de la red de contactos de emergencia y los equipos de rescate en la obra.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1081, 'ru-RU', 'Проведение учений по эвакуации в чрезвычайных ситуациях и проверка наличия на объекте средств экстренной связи и спасательного оборудования.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1082, 'es-ES', 'Inspeccionar exhaustivamente el estado de instalación de las barandillas superiores, intermedias y los rodapiés de la plataforma de trabajo antes de su uso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1082, 'ru-RU', 'Перед началом работ провести полную проверку установки верхнего и среднего ограждений, а также бортового ограждения (отбойной доски) рабочей площадки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1083, 'es-ES', 'Prohibir la retirada no autorizada de las barandillas de protección y verificar la fijación de los soportes y la estabilidad de la barandilla.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1083, 'ru-RU', 'Запретить самовольное снятие защитных ограждений и проверять надежность крепления стоек и отсутствие шаткости перил.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1084, 'es-ES', 'Colocar de forma visible señales de advertencia de riesgo de caída de personas y objetos cerca de las zonas con barandillas y aberturas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1084, 'ru-RU', 'Вблизи зон с ограждениями и проемов разместить четкие предупреждающие знаки об опасности падения с высоты и падения предметов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1103, 'es-ES', 'Antes del desmontaje, cerrar la válvula de suministro de gas y purgar completamente el gas residual. Verificar la ausencia de gas con un detector de fugas homologado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1103, 'ru-RU', 'Перед демонтажем перекрыть клапан подачи газа, выполнить полную продувку для удаления остаточного газа и проверить его отсутствие с помощью сертифицированного газоанализатора.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1104, 'es-ES', 'Confirmar mediante manómetro que la presión residual es cero (0) y utilizar obligatoriamente pantalla facial y gafas de seguridad (conforme a UNE-EN 166) durante el desmontaje.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1104, 'ru-RU', 'Окончательно убедиться в отсутствии остаточного давления (показание манометра «0») и при демонтаже обязательно использовать защитный лицевой щиток и защитные очки (согласно ГОСТ 12.4.253-2013).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1105, 'es-ES', 'Consultar la Ficha de Datos de Seguridad (FDS) antes del trabajo y asegurar ventilación forzada mediante un sistema de extracción localizada o ventiladores industriales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1105, 'ru-RU', 'Перед началом работ ознакомиться с информацией в Паспорте безопасности (ПБ) и обеспечить принудительную вентиляцию, включив местную вытяжную систему или промышленный вентилятор.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1106, 'es-ES', 'Verificar que los componentes calientes se hayan enfriado suficientemente antes de su manipulación y usar equipos de protección individual específicos, como guantes de protección térmica (EN 407).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1106, 'ru-RU', 'Перед разборкой убедиться в достаточном охлаждении горячих компонентов и использовать специальные СИЗ, включая термозащитные перчатки (согласно ГОСТ 12.4.252-2013).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1107, 'es-ES', 'Al desmontar componentes en zonas con atmósferas potencialmente explosivas (zonas ATEX), utilizar exclusivamente herramientas antideflagrantes certificadas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1107, 'ru-RU', 'При разборке компонентов в зонах с возможным образованием взрывоопасных сред применять принцип обязательного использования взрывозащищенного инструмента (согласно ГОСТ Р).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1109, 'es-ES', 'Mediante la charla de seguridad (TBM), comprender la estructura del equipo y la secuencia de desmontaje autorizada. Disponer de los planos técnicos en el punto de trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1109, 'ru-RU', 'В ходе целевого инструктажа (TBM) изучить конструкцию оборудования и утвержденную последовательность разборки; перед началом работ обеспечить наличие технических чертежей на рабочем месте.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1110, 'es-ES', 'Utilizar todos los EPI requeridos, como mascarilla autofiltrante y traje de protección. Si es necesario para controlar el polvo, aplicar métodos de trabajo húmedos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1110, 'ru-RU', 'Полностью использовать предписанные СИЗ, включая противопылевой респиратор и защитную одежду. При необходимости применять влажные методы работы для подавления пыли.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1115, 'es-ES', 'Orientar la descarga de venteo hacia una zona segura, lejos de los trabajadores, y delimitar una zona de acceso restringido durante la operación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1115, 'ru-RU', 'Направить сброс вентилируемого газа в безопасную зону, вдали от персонала, и организовать зону с ограниченным доступом на время проведения работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1116, 'es-ES', 'Antes de ventear, verificar la apertura de la línea y el correcto funcionamiento de las válvulas. Monitorizar constantemente la variación de la presión.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1116, 'ru-RU', 'Перед сбросом проверить состояние открытия линии и работоспособность клапанов, осуществлять постоянный мониторинг изменений давления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1117, 'es-ES', 'Instalar medidores de oxígeno y gases en la zona de venteo para vigilar permanentemente que las concentraciones se mantengan dentro de los límites de exposición permitidos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1117, 'ru-RU', 'В зоне вентиляции постоянно использовать газоанализаторы для контроля концентрации кислорода и газов, чтобы обеспечить соблюдение допустимых норм.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1118, 'es-ES', 'Antes de la inyección de nitrógeno, medir la concentración de oxígeno en la línea o espacio confinado y activar el sistema de ventilación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1118, 'ru-RU', 'Перед подачей азота провести замер концентрации кислорода в трубопроводе или замкнутом пространстве и включить систему вентиляции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1120, 'es-ES', 'Ajustar la presión de inyección por debajo del límite máximo permitido e inyectar el gas de forma gradual, controlando con manómetros y caudalímetros.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1120, 'ru-RU', 'Регулировать давление подачи ниже максимально допустимого предела, осуществлять подачу постепенно, контролируя процесс с помощью манометров и расходомеров.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1127, 'es-ES', 'Antes de la intervención, eliminar los gases residuales y verificar el estado interno de la línea conforme al procedimiento de purga aprobado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1127, 'ru-RU', 'Перед началом работ удалить остаточный газ и проверить внутреннее состояние линии в соответствии с утвержденной процедурой продувки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1128, 'es-ES', 'Instalar un medidor de concentración de oxígeno en la zona de purga y mantener una ventilación continua durante todo el proceso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1128, 'ru-RU', 'Установить газоанализатор для измерения концентрации кислорода в зоне продувки и обеспечить непрерывную вентиляцию во время работы.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1129, 'es-ES', 'Tras la purga, tomar muestras en el punto designado para medir la concentración y confirmar que se encuentra dentro del rango de seguridad establecido.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1129, 'ru-RU', 'После завершения продувки произвести замер концентрации в точке отбора проб и убедиться, что она достигла безопасного нормативного значения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1139, 'es-ES', 'Verificar el número de pin y la polaridad correcta según el esquema eléctrico antes de conectar. Realizar una doble comprobación tras finalizar.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1139, 'ru-RU', 'Перед подключением проверить соответствие номеров контактов и полярности согласно электрической схеме. После завершения выполнить перекрестную проверку.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1140, 'es-ES', 'Durante el montaje, comprobar la estanqueidad de los prensaestopas y juntas. Orientar la entrada de cables hacia abajo para prevenir la infiltración de humedad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1140, 'ru-RU', 'При сборке проверить герметичность сальников и уплотнений, а также направить ввод кабеля вниз для предотвращения проникновения влаги.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1141, 'es-ES', 'Eliminar obstáculos y asegurar un radio de trabajo suficiente en la zona. Evitar mantener posturas estáticas prolongadas para prevenir trastornos musculoesqueléticos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1141, 'ru-RU', 'Заранее убрать препятствия в рабочей зоне и обеспечить достаточный радиус для работы. Избегать длительных статических поз для профилактики нарушений опорно-двигательного аппарата.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1145, 'es-ES', 'Colocar una señal de ''No operar'' en el equipo hasta finalizar la instalación. Conectar la alimentación solo tras coordinación con la sala de control.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1145, 'ru-RU', 'До завершения монтажа вывесить на оборудовании табличку «Не включать». Подавать питание только после согласования с диспетчерской.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1146, 'es-ES', 'Verificar si el área es una zona ATEX y asegurar iluminación temporal adecuada, como linternas con certificación antideflagrante.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1146, 'ru-RU', 'Проверить, является ли зона взрывоопасной, и обеспечить достаточное временное освещение, используя взрывозащищенные фонари.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1147, 'es-ES', 'Tras la instalación, realizar pruebas de estanqueidad con agua jabonosa o un detector de fugas portátil, y efectuar una prueba de funcionamiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1147, 'ru-RU', 'После монтажа выполнить проверку герметичности с помощью мыльного раствора или портативного детектора утечек, а также провести функциональное испытание.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1148, 'es-ES', 'Antes del reemplazo, cotejar las especificaciones (modelo, valores nominales, etc.) de la pieza nueva y la antigua con los planos técnicos para una verificación final.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1148, 'ru-RU', 'Перед заменой провести финальную сверку спецификаций (модель, номинальные параметры и т.д.) старой и новой детали с техническими чертежами.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1149, 'es-ES', 'Durante el cableado, aislar temporalmente las partes expuestas y usar equipos de protección contra descargas electrostáticas (ESD), como una pulsera antiestática.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1149, 'ru-RU', 'Во время электромонтажных работ временно изолировать оголенные участки и использовать средства защиты от статического электричества, такие как антистатический браслет.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1150, 'es-ES', 'Al finalizar, limpiar y ordenar la zona de trabajo. Realizar un inventario de piezas y herramientas antes de retirarse.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1150, 'ru-RU', 'По окончании работ выполнить уборку на рабочем месте, сверить количество деталей и инструментов перед уходом.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1157, 'es-ES', 'Antes de la manipulación, usar traje, mascarilla, gafas y guantes de protección. Al cortar, aplicar humidificación o supresores de polvo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1157, 'ru-RU', 'Перед началом работ надеть защитный костюм, респиратор, очки и перчатки. При резке применять увлажнение или средства для подавления пыли.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1158, 'es-ES', 'Medir la temperatura de la superficie. En zonas calientes, instalar almohadillas de aislamiento térmico o suspender el trabajo hasta que se enfríe.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1158, 'ru-RU', 'Измерить температуру поверхности. На горячих участках установить теплоизоляционные накладки или приостановить работы до остывания.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1159, 'es-ES', 'Informar sobre los riesgos de las altas temperaturas en la charla de seguridad (TBM). Programar descansos periódicos y verificar el uso correcto de los EPI.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1159, 'ru-RU', 'Провести инструктаж (TBM) о рисках высоких температур, обеспечить периодические перерывы и проконтролировать правильное использование СИЗ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1160, 'es-ES', 'En espacios confinados, medir la concentración de oxígeno, activar la ventilación, trabajar en equipos de dos personas, y asignar un vigilante con equipo de comunicación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1160, 'ru-RU', 'В замкнутых пространствах измерить концентрацию кислорода, включить вентиляцию, работать в паре (2 человека) и обеспечить наличие наблюдателя со средствами связи.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1161, 'es-ES', 'Prohibido apilar herramientas y materiales directamente sobre la superficie de trabajo; utilizar siempre cajas o soportes específicos para herramientas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1161, 'ru-RU', 'Запрещается складировать инструменты и материалы непосредственно на рабочей поверхности; всегда использовать специальные ящики (инструментальные ящики).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1162, 'es-ES', 'Verificar el estado de salud antes de empezar. Suspender los trabajos en el exterior en caso de condiciones meteorológicas adversas y priorizar las tareas a nivel del suelo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1162, 'ru-RU', 'Проверить состояние здоровья перед работой, приостановить работы на открытом воздухе при неблагоприятных погодных условиях и отдавать приоритет работам на уровне земли.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1169, 'es-ES', 'Asignar roles y definir la secuencia de trabajo en la TBM. Utilizar soportes para evitar el vuelco de materiales y organizadores para herramientas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1169, 'ru-RU', 'На инструктаже (TBM) распределить роли и изучить последовательность работ. Использовать опоры для предотвращения опрокидывания материалов и органайзеры для инструментов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1170, 'es-ES', 'Instalar pantallas de protección contra proyecciones y utilizar obligatoriamente los EPI pertinentes, como gafas de seguridad, mascarilla y guantes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1170, 'ru-RU', 'Установить защитные экраны от разлетающихся частиц и обязательно использовать средства индивидуальной защиты: защитные очки, респиратор, перчатки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1171, 'es-ES', 'Antes del montaje, asegurarse de que el interior y exterior de la carcasa estén libres de objetos extraños y de que no haya presión residual.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1171, 'ru-RU', 'Перед сборкой убедиться в полном отсутствии посторонних предметов внутри и снаружи корпуса, а также остаточного давления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1172, 'es-ES', 'Asegurar el par de apriete normalizado con una llave dinamométrica y, en entornos con vibraciones, aplicar un sistema de doble fijación (p. ej., tuercas autoblocantes).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1172, 'ru-RU', 'Обеспечить нормативное усилие затяжки с помощью динамометрического ключа и, с учетом вибрационной среды, применить двойное крепление (например, контргайки).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1173, 'es-ES', 'Cumplir el principio de trabajo en equipo (mínimo 2 personas), asignar un vigilante en espacios reducidos y asegurar la disponibilidad de medios de comunicación para emergencias.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1173, 'ru-RU', 'Соблюдать принцип работы в паре (2 человека), назначать наблюдателя при работе в стесненных условиях и постоянно иметь при себе средства аварийной связи.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1174, 'es-ES', 'Antes de trabajar, verificar la ubicación de la tubería, su eje central y las dimensiones detalladas, cotejándolas con los planos para una alineación precisa.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1174, 'ru-RU', 'Перед началом работ сверить расположение, осевую линию и детальные размеры трубопровода с чертежами для обеспечения точного выравнивания.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1175, 'es-ES', 'Utilizar herramientas con aislamiento nominal y, en zonas ATEX, herramientas antideflagrantes. Comprobar periódicamente el estado de la tensión.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1175, 'ru-RU', 'Использовать инструмент с соответствующей изоляцией и взрывозащищенный инструмент во взрывоопасных зонах, регулярно проверять наличие напряжения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1176, 'es-ES', 'Instalar cubiertas protectoras o mantas dieléctricas para proteger los equipos adyacentes. Tomar medidas de protección antes de trabajar en zonas de interferencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1176, 'ru-RU', 'Установить защитные кожухи или диэлектрические коврики для защиты смежного оборудования, перед работой в зонах пересечения принять защитные меры.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1177, 'es-ES', 'Eliminar salientes en la superficie de trabajo, usar EPI (calzado de seguridad, guantes antiexplosión) y mantener las herramientas ordenadas en su caja.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1177, 'ru-RU', 'Устранить выступы на рабочей поверхности, использовать СИЗ (спецобувь, взрывозащищенные перчатки) и хранить инструменты в специальном ящике.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1178, 'es-ES', 'Al finalizar el trabajo, realizar una inspección completa basada en una lista de verificación (checklist) y registrar los detalles en el parte de trabajo para su revisión por el supervisor.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1178, 'ru-RU', 'После завершения работ провести полную проверку по чек-листу, зафиксировать результаты в рабочем журнале и предоставить на проверку руководителю.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1240, 'es-ES', 'Asegurar la carga pesada según su peso y forma, alineándola con el centro de gravedad. Prohibidas las maniobras bruscas como paradas o giros repentinos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1240, 'ru-RU', 'Строповку тяжеловесного груза производить с учетом его массы и формы, совмещая с центром тяжести. Запрещаются резкие маневры, такие как внезапная остановка или поворот.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1241, 'es-ES', 'Delimitar la zona de trabajo con cinta de balizamiento o vallas de seguridad para impedir el acceso y colocar señales de advertencia de riesgo de caída de objetos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1241, 'ru-RU', 'Оградить рабочую зону сигнальной лентой или защитными ограждениями для запрета доступа и установить предупреждающие знаки об опасности падения предметов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1246, 'es-ES', 'Evitar el contacto corporal con el cable de acero mientras está en tensión y usar guantes de seguridad ajustados en lugar de guantes de tela para prevenir atrapamientos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1246, 'ru-RU', 'Не прикасаться к натянутому тросу и использовать плотно прилегающие защитные перчатки вместо хлопчатобумажных для предотвращения защемления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1247, 'es-ES', 'Verificar el certificado de inspección de la grúa (conforme a UNE-EN 13000) y comprobar el funcionamiento de dispositivos de seguridad como el limitador de carga y el freno de emergencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1247, 'ru-RU', 'Проверить наличие акта технического освидетельствования крана и исправность приборов безопасности, таких как ограничитель грузоподъемности и аварийный тормоз.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1248, 'es-ES', 'Comprobar la cualificación del operador y la vigencia del seguro. Realizar una charla de seguridad (TBM) basada en el plan de trabajo antes de empezar.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1248, 'ru-RU', 'Проверить наличие у оператора удостоверения и страхового полиса, перед началом работ провести целевой инструктаж (TBM) в соответствии с планом производства работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1250, 'es-ES', 'Al terminar, asegurar el gancho de la grúa, destensar el cable y limpiar el área del equipo, verificando de nuevo su estado de conservación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1250, 'ru-RU', 'По окончании работ закрепить крюк крана, ослабить натяжение троса, очистить зону вокруг оборудования и повторно проверить его состояние.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1251, 'es-ES', 'Verificar el peso, el centro de gravedad y el estado del palé antes de la manipulación. Ajustar la distancia entre las horquillas y comprobar la estabilidad de la carga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1251, 'ru-RU', 'Предварительно проверить вес и центр тяжести груза, состояние палеты. Отрегулировать ширину вил и проверить надежность фиксации груза.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1253, 'es-ES', 'Si la visibilidad es limitada, es obligatorio contar con un señalista. Acordar previamente el código de señales con el señalista antes de iniciar la maniobra.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1253, 'ru-RU', 'При ограниченной видимост иобязательно привлекать сигнальщика. Предварительно согласовать с сигнальщиком систему сигналов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1254, 'es-ES', 'Verificar el radio de giro de la carretilla en el área de trabajo. Reducir la velocidad y usar la bocina antes de entrar en curvas para advertir a los demás.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1254, 'ru-RU', 'Проверить радиус поворота погрузчика в рабочей зоне, перед входом в поворот снизить скорость и использовать звуковой сигнал для предупреждения окружающих.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1255, 'es-ES', 'Comprobar regularmente el funcionamiento de la alarma de marcha atrás y la luz estroboscópica. Moverse siguiendo las indicaciones del señalista para cubrir los puntos ciegos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1255, 'ru-RU', 'Постоянно проверять исправность звукового сигнала заднего хода и проблескового маячка, для контроля слепых зон передвигаться по указаниям сигнальщика.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1283, 'es-ES', 'Antes de finalizar la jornada, realizar una inspección final de la operatividad de las vías de evacuación y mantenerlas permanentemente despejadas y accesibles.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1283, 'ru-RU', 'Перед окончанием работ провести итоговую проверку работоспособности эвакуационных путей и обеспечить их постоянную доступность и свободное состояние.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1256, 'es-ES', 'Verificar la ausencia de interferencias en la parte superior antes de elevar el mástil y señalizar y restringir el acceso de peatones a la zona de riesgo por caída de objetos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1256, 'ru-RU', 'Перед подъемом мачты повторно проверить наличие препятствий сверху и принять меры по запрещению доступа пешеходов в зону возможного падения предметов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1258, 'es-ES', 'Ajustar las horquillas manualmente con el motor parado. Utilizar guantes de seguridad ajustados y antideslizantes para prevenir riesgos de atrapamiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1258, 'ru-RU', 'Регулировку вил производить вручную после остановки двигателя. Для предотвращения защемления использовать плотно прилегающие противоскользящие защитные перчатки (СИЗ).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1259, 'es-ES', 'Al acceder a rampas, circular con la carga orientada hacia la parte superior de la pendiente, respetando la dirección de avance/retroceso, y reducir la velocidad en zonas húmedas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1259, 'ru-RU', 'При движении по наклонной плоскости (рампе) располагать груз со стороны подъема, соблюдая правильное направление движения вперед/назад, и снижать скорость на влажных участках.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1260, 'es-ES', 'Antes de iniciar la operativa, comprobar el correcto funcionamiento de los dispositivos principales (frenos, claxon, sistema de iluminación) conforme al listado de verificación diario.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1260, 'ru-RU', 'Перед началом работы проверить исправность основных устройств (тормозная система, звуковой сигнал, осветительные приборы) в соответствии с ежедневным контрольным листом осмотра.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1261, 'es-ES', 'La carretilla elevadora solo será operada por personal cualificado y autorizado. Prohibir aceleraciones y frenadas bruscas, y mantener las horquillas a baja altura durante el desplazamiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1261, 'ru-RU', 'Управлять погрузчиком разрешается только лицам, имеющим соответствующее удостоверение. Запрещаются резкое ускорение и торможение; при движении вилы должны находиться на минимальной высоте от земли.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1262, 'es-ES', 'Al finalizar el trabajo, bajar completamente las horquillas hasta el suelo, accionar el freno de estacionamiento, parar el motor y retirar la llave de contacto para su custodia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1262, 'ru-RU', 'После окончания работы полностью опустить вилы на землю, включить стояночный тормоз, заглушить двигатель и извлечь ключ из замка зажигания для надлежащего хранения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1263, 'es-ES', 'En caso de derrame de combustible o productos químicos, utilizar material absorbente o neutralizador, limpiar la zona afectada y eliminar completamente el residuo generado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1263, 'ru-RU', 'При утечке топлива или химических веществ использовать абсорбирующие материалы или нейтрализаторы, после чего очистить пораженный участок и полностью удалить все остатки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1264, 'es-ES', 'Inmediatamente después de finalizar los trabajos, retirar los residuos del suelo y de la plataforma de trabajo, y utilizar un soplador para eliminar las partículas residuales en suspensión.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1264, 'ru-RU', 'Сразу после окончания работ убрать мусор с пола и рабочего места, а также использовать воздуходувку для удаления остаточных частиц из воздуха.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1265, 'es-ES', 'El polvo y los fragmentos de corte deben ser aspirados con un aspirador industrial. Activar el sistema de ventilación para purificar el ambiente interior.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1265, 'ru-RU', 'Пыль и стружку убирать с помощью промышленного пылесоса. Включить систему вентиляции для очистки воздуха в помещении.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1266, 'es-ES', 'Las herramientas, cables y mangueras utilizadas deben ser guardados inmediatamente en su lugar designado, como soportes o armarios de almacenamiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1266, 'ru-RU', 'Использованные инструменты, кабели и шланги немедленно убирать на отведенные для них места на стеллажах или в ящиках для хранения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1267, 'es-ES', 'Tras finalizar la tarea, realizar el traspaso de información sobre el estado de orden y limpieza al siguiente turno para permitir un inicio inmediato del trabajo, documentándolo en la charla de seguridad (TBM).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1267, 'ru-RU', 'После завершения работ передать сменщику информацию о состоянии порядка на рабочем месте для обеспечения немедленного начала следующей смены и провести целевой инструктаж (TBM).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1268, 'es-ES', 'Eliminar prioritariamente los obstáculos alrededor de las salidas de emergencia y escaleras para garantizar que las vías de evacuación estén siempre despejadas y verificar su estado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1268, 'ru-RU', 'В первую очередь устранять препятствия вблизи аварийных выходов и на лестницах, чтобы обеспечить постоянную готовность эвакуационных путей и контролировать их состояние.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1269, 'es-ES', 'Clasificar los residuos según su naturaleza (peligrosos, no peligrosos, reciclables), etiquetarlos y depositarlos en los contenedores de recogida selectiva correspondientes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1269, 'ru-RU', 'Отходы классифицировать по свойствам на опасные, бытовые и вторсырье, маркировать и хранить в соответствующих контейнерах для раздельного сбора.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1270, 'es-ES', 'Los residuos cortantes o punzantes deben recogerse en contenedores específicos y adecuados. Es obligatorio el uso de guantes de protección anti-corte durante su manipulación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1270, 'ru-RU', 'Острые отходы собирать в специальные контейнеры. При обращении с ними обязательно использовать защитные перчатки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1271, 'es-ES', 'Durante el transporte, asegurar el cierre hermético de las tapas, respetar los límites de peso y verificar previamente la planitud del suelo y los posibles riesgos de colisión.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1271, 'ru-RU', 'При транспортировке обеспечить герметичность крышек, соблюдать нормы веса, а также предварительно проверять ровность поверхности и наличие рисков столкновения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1272, 'es-ES', 'Instalar cubetos de retención y cubiertas impermeables en la zona de almacenamiento temporal de residuos, e inspeccionar periódicamente para detectar posibles fugas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1272, 'ru-RU', 'В местах временного хранения отходов установить водонепроницаемое покрытие и защитные бортики (поддоны), а также периодически проверять на предмет утечек.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1273, 'es-ES', 'Limpiar el área de trabajo inmediatamente después de manipular sustancias peligrosas. El personal debe utilizar los EPIs requeridos, como gafas de seguridad y mascarilla de protección.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1273, 'ru-RU', 'Немедленно очищать рабочее место после работы с вредными веществами. Работники обязаны использовать средства индивидуальной защиты (СИЗ), включая защитные очки и респиратор.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1274, 'es-ES', 'Después de trabajos que generen sólidos o polvo, utilizar un aspirador industrial para realizar una limpieza completa, asegurando que no queden residuos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1274, 'ru-RU', 'После работ с твердыми и пылевидными материалами провести полную уборку с помощью промышленного пылесоса, не оставляя загрязнений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1276, 'es-ES', 'Tras las tareas de orden y limpieza, el supervisor final debe realizar una inspección basada en una lista de verificación y firmar el registro de conformidad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1276, 'ru-RU', 'После завершения уборки ответственное лицо проводит проверку по контрольному листу, фиксируя результаты подписью.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1277, 'es-ES', 'Documentar el historial de gestión externa de residuos y establecer un sistema de verificación final por parte de un responsable.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1277, 'ru-RU', 'Документировать историю передачи отходов сторонним организациям и обеспечить систему окончательного контроля со стороны руководителя.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1278, 'es-ES', 'Inmediatamente después de finalizar los trabajos, clasificar los materiales sobrantes por su naturaleza, transportarlos a la zona de acopio designada y despejar las vías de paso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1278, 'ru-RU', 'Сразу после окончания работ рассортировать остаточные материалы по их свойствам, переместить в назначенное место сбора и освободить проходы.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1279, 'es-ES', 'Antes de reportar la finalización del trabajo, recoger todas las herramientas utilizadas, guardarlas en su lugar de almacenamiento designado y realizar un recuento de inventario.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1279, 'ru-RU', 'Перед докладом о завершении работ собрать все использованные инструменты, поместить их в установленное место хранения и проверить количество.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1280, 'es-ES', 'Los residuos con componentes a alta temperatura deben enfriarse completamente antes de su gestión. Mantener extintores de incendios disponibles en todo momento en la zona de tratamiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1280, 'ru-RU', 'Отходы с высокотемпературными компонентами утилизировать только после их полного остывания. В зоне обработки постоянно иметь в наличии огнетушители.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1281, 'es-ES', 'Registrar y comunicar claramente el estado de seguridad y limpieza del área de trabajo a través de la charla de seguridad (TBM) o el informe de fin de jornada.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1281, 'ru-RU', 'Четко документировать и передавать информацию о состоянии безопасности и порядка на рабочем месте посредством инструктажа (TBM) или отчета о завершении работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1282, 'es-ES', 'La gestión de residuos debe realizarse estrictamente según los procedimientos aprobados. El área de almacenamiento debe estar claramente señalizada con la cartelería designada.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1282, 'ru-RU', 'Утилизация отходов должна производиться в строгом соответствии с утвержденными процедурами. Места хранения должны быть обозначены соответствующими знаками.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1284, 'es-ES', 'Durante la puesta en marcha de cada unidad de equipo, utilizar vibrómetros y termómetros para medir, diagnosticar y registrar cualquier signo de anomalía.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1284, 'ru-RU', 'При пусконаладочных работах на каждой единице оборудования использовать виброметры и термометры для измерения, диагностики и регистрации аномальных признаков.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1285, 'es-ES', 'Antes de la puesta en marcha, revisar los diagramas de circuitos y de flujo. Verificar la totalidad de las operaciones de señalización y la correspondencia con los valores de consigna.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1285, 'ru-RU', 'Перед вводом в эксплуатацию изучить электрические и гидравлические/пневматические схемы, а также провести полную проверку срабатывания сигналов и их соответствия заданным значениям.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1286, 'es-ES', 'Verificar que todos los instrumentos de medida, detectores y registradores han sido calibrados previamente. En caso de anomalía, sustituirlos de inmediato.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1286, 'ru-RU', 'Убедиться, что все измерительные приборы, датчики и регистрирующие устройства прошли предварительную поверку/калибровку. При неисправности немедленно заменить.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1287, 'es-ES', 'Cumplir con el procedimiento de aumento de carga por etapas. Si se detecta una anomalía durante la puesta en marcha, detener el proceso, corregir el problema y volver a verificar.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1287, 'ru-RU', 'Соблюдать процедуру поэтапного наращивания нагрузки. При возникновении неисправностей в ходе испытаний немедленно приостановить процесс, устранить причину и провести повторную проверку.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1288, 'es-ES', 'Realizar una formación previa sobre el procedimiento de parada de emergencia y el plan de respuesta mediante una charla de seguridad (TBM). Comprobar prioritariamente el funcionamiento del pulsador de parada de emergencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1288, 'ru-RU', 'Провести предварительный инструктаж (TBM) по процедурам аварийной остановки и планам реагирования. В первую очередь проверить работоспособность кнопки аварийного останова.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1289, 'es-ES', 'Todos los puntos de la lista de verificación deben ser inspeccionados por un equipo de dos personas mediante un sistema de doble chequeo. El equipo se pondrá en servicio solo tras la aprobación final.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1289, 'ru-RU', 'Все пункты контрольного листа должны проверяться перекрестно бригадой из двух человек. Ввод оборудования в эксплуатацию осуществляется только после окончательного утверждения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1290, 'es-ES', 'Además de la inspección visual, utilizar equipos como cámaras termográficas para verificar con precisión el estado de desgaste y corrosión del equipo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1290, 'ru-RU', 'Помимо визуального осмотра, использовать тепловизионные камеры для точной проверки состояния износа и коррозии оборудования.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1291, 'es-ES', 'Instalar una delimitación de seguridad en la zona de puesta en marcha y asignar un vigilante para restringir estrictamente el acceso a personal no autorizado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1291, 'ru-RU', 'Установить ограждение зоны пусконаладочных работ и выставить наблюдателя для строгого ограничения доступа посторонних лиц.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1292, 'es-ES', 'Estudiar detenidamente la estructura del equipo y los diagramas de sistema. La operación debe ser realizada por el personal designado siguiendo la secuencia de puesta en marcha por etapas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1292, 'ru-RU', 'Тщательно изучить конструкцию оборудования и схемы систем. Операции должен выполнять назначенный персонал в соответствии с поэтапной последовательностью пусконаладки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1293, 'es-ES', 'Inmediatamente después de finalizar la puesta en marcha, proceder a la consignación de la fuente de energía y a la eliminación de la presión residual, devolviendo el equipo a un estado seguro.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1293, 'ru-RU', 'Сразу после окончания пусконаладочных работ изолировать источники энергии, сбросить остаточное давление и привести оборудование в безопасное исходное состояние.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1294, 'es-ES', 'Inspeccionar todas las bridas de conexión y juntas de tuberías. Utilizar una llave dinamométrica para verificar que se aplica el par de apriete estándar.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1294, 'ru-RU', 'Проверить все фланцевые и трубные соединения. Использовать динамометрический ключ для контроля нормативного момента затяжки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1295, 'es-ES', 'Purgar el interior del equipo con un gas inerte como el nitrógeno y, a continuación, realizar una prueba de estanqueidad utilizando un detector de fugas y agua jabonosa.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1295, 'ru-RU', 'Продуть внутреннюю часть оборудования инертным газом (например, азотом), после чего провести проверку на герметичность с помощью детектора утечек и мыльного раствора.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1296, 'es-ES', 'Solo después de confirmar que los resultados de la prueba de estanqueidad son satisfactorios, introducir el fluido de proceso real y monitorizar en busca de fugas iniciales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1296, 'ru-RU', 'Подавать рабочую среду в систему только после окончательного подтверждения положительных результатов испытаний на герметичность и вести первоначальный контроль утечек.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1297, 'es-ES', 'Antes de iniciar los trabajos, medir las concentraciones de oxígeno y gases tóxicos, y mantener en funcionamiento constante el sistema de ventilación (extracción localizada o ventilador).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1297, 'ru-RU', 'Перед началом работ измерить концентрацию кислорода и вредных газов. Обеспечить постоянную работу вентиляционной системы (местная вытяжная или приточная).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1298, 'es-ES', 'Antes de los trabajos, medir la concentración de gases inflamables y utilizar equipos y herramientas con protección antideflagrante (ATEX) en zonas con riesgo de explosión.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1298, 'ru-RU', 'Перед началом работ измерить концентрацию горючих газов. Во взрывоопасных зонах использовать освещение и инструменты во взрывозащищенном исполнении.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1299, 'es-ES', 'Asegurar un nivel de iluminación suficiente. Mantener el orden y limpieza en el suelo del área de trabajo, retirando escombros y aplicando medidas antideslizantes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1299, 'ru-RU', 'Обеспечить достаточный уровень освещенности. Поддерживать порядок на полу рабочей зоны, убирать обломки и принимать меры против скольжения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1300, 'es-ES', 'Al utilizar compuestos orgánicos, activar el sistema de extracción localizada para asegurar la ventilación y usar EPIs como máscaras de protección respiratoria con filtros adecuados.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1300, 'ru-RU', 'При использовании органических соединений включить местную вытяжную вентиляцию для обеспечения воздухообмена и использовать СИЗ, такие как противогазы.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1301, 'es-ES', 'Informar sobre las rutas de evacuación mediante una charla de seguridad (TBM) previa. Despejar los obstáculos alrededor del área de trabajo para asegurar una vía de salida.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1301, 'ru-RU', 'Провести предварительный инструктаж (TBM) по путям эвакуации. Убрать препятствия вблизи рабочей зоны для обеспечения свободного выхода.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1302, 'es-ES', 'Medir la temperatura de la tubería a aislar. Si hay riesgo de quemaduras, aplicar medidas de enfriamiento. Realizar pausas con estiramientos para mitigar la fatiga física.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1302, 'ru-RU', 'Измерить температуру изолируемого трубопровода. При риске ожогов принять меры по охлаждению. Делать перерывы для растяжки, чтобы снизить физическую нагрузку.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1303, 'es-ES', 'Humedecer la fibra cerámica antes de cortarla y utilizar todos los EPIs requeridos, como mascarilla de protección contra el polvo y gafas de seguridad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1303, 'ru-RU', 'Перед резкой керамического волокна провести его увлажнение. В обязательном порядке использовать полный комплект СИЗ, включая респиратор и защитные очки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1304, 'es-ES', 'Trabajar siempre en equipos de al menos dos personas. Asignar un vigilante externo que mantenga comunicación constante mediante radio u otro medio.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1304, 'ru-RU', 'Работы выполнять бригадой не менее чем из двух человек. Назначить наблюдающего снаружи для поддержания постоянной связи по рации или другим средствам.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1305, 'es-ES', 'El material de aislamiento retirado debe ser introducido inmediatamente en bolsas de plástico selladas, con doble embolsado, y transportado a la zona de residuos designada.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1305, 'ru-RU', 'Демонтированный изоляционный материал немедленно помещать в герметичные пластиковые мешки (двойная упаковка) и транспортировать в назначенную зону для отходов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1306, 'es-ES', 'Continuar con la ventilación incluso después de finalizar el trabajo. Volver a medir las concentraciones para confirmar que el ambiente es seguro antes de la entrega del área.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1306, 'ru-RU', 'Продолжать вентиляцию после окончания работ. Провести повторные замеры концентраций для подтверждения безопасности перед сдачей рабочего места.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1307, 'es-ES', 'Fijar las puertas de acceso en posición abierta o asignar un vigilante para evitar su cierre accidental durante los trabajos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1307, 'ru-RU', 'Зафиксировать входные двери в открытом положении или выставить наблюдателя для предотвращения их случайного закрытия во время работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1308, 'es-ES', 'Antes de entrar en espacios confinados, verificar la presencia de fugas utilizando un detector de gases y comunicar los riesgos durante la reunión de seguridad previa al trabajo (Toolbox Meeting).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1308, 'ru-RU', 'Перед входом в замкнутое пространство с помощью газоанализатора проверить наличие утечек и обсудить риски с бригадой в ходе целевого инструктажа перед началом работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1309, 'es-ES', 'Medir la concentración de oxígeno antes de entrar, asegurando que sea superior al 18%. Si es insuficiente, realizar ventilación forzada con un ventilador de impulsión.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1309, 'ru-RU', 'Перед входом измерить концентрацию кислорода и убедиться, что она превышает 18%. В случае недостатка обеспечить принудительную вентиляцию с помощью приточного вентилятора.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1310, 'es-ES', 'Durante el trabajo, portar en todo momento un medidor de oxígeno portátil. En caso de que se active la alarma por baja concentración, evacuar la zona de inmediato.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1310, 'ru-RU', 'Во время работы постоянно носить портативный измеритель концентрации кислорода. При срабатывании сигнала тревоги о снижении концентрации немедленно эвакуироваться.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1311, 'es-ES', 'Antes de usar el medidor de concentración de oxígeno, verificar su calibración y comprobar el correcto funcionamiento del sensor con gas patrón.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1311, 'ru-RU', 'Перед использованием измерителя концентрации кислорода проверить его поверку/калибровку и исправность сенсора с помощью поверочной газовой смеси.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1312, 'es-ES', 'Considerando las características de los gases (más o menos densos que el aire), medir con precisión la concentración en los niveles superior, medio e inferior, así como en esquinas y zonas de difícil acceso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1312, 'ru-RU', 'Учитывая свойства газов (тяжелее или легче воздуха), проводить точные замеры концентрации на верхнем, среднем и нижнем уровнях, а также в углах и труднодоступных местах.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1313, 'es-ES', 'Inspeccionar la estructura del muro y su estado de fisuración antes del trabajo. Instalar puntales en la dirección de riesgo de colapso y tomar medidas antivuelco.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1313, 'ru-RU', 'Перед началом работ проверить конструкцию и наличие трещин в ограждении. Установить опоры и принять меры по предотвращению обрушения в направлении вероятного падения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1314, 'es-ES', 'Durante las operaciones de corte y demolición, utilizar equipos de protección individual (EPI) como gafas de seguridad y mascarilla antipolvo, e instalar redes o pantallas de protección contra proyecciones.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1314, 'ru-RU', 'При выполнении работ по резке и дроблению использовать СИЗ, такие как защитные очки и противопылевой респиратор, а также установить защитную сетку или экран от разлетающихся частиц.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1315, 'es-ES', 'Instalar cinta de balizamiento y postes de delimitación en el perímetro de trabajo para controlar el acceso y operar la maquinaria siguiendo las indicaciones del señalista.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1315, 'ru-RU', 'Установить сигнальную ленту и оградительные столбики по периметру рабочей зоны для контроля доступа и управлять техникой по указаниям сигнальщика.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1316, 'es-ES', 'Prohibir estrictamente los trabajos simultáneos a diferentes niveles y mantener un sistema de comunicación eficaz entre los trabajadores mediante radios u otros medios.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1316, 'ru-RU', 'Строго запретить одновременное выполнение работ на разных уровнях по вертикали и поддерживать надежную систему связи между работниками с помощью раций.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1317, 'es-ES', 'Retirar inmediatamente los escombros generados para asegurar rutas de paso seguras y eliminar polvo y derrames de aceite del suelo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1317, 'ru-RU', 'Незамедлительно убирать образующиеся отходы демонтажа для обеспечения безопасных проходов и устранять пыль и масляные пятна с пола.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1318, 'es-ES', 'Cortar o cubrir la ferralla expuesta con capuchones de protección de inmediato y utilizar guantes de protección mecánica y anticorte.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1318, 'ru-RU', 'Немедленно обрезать или закрывать защитными колпачками выступающие концы арматуры, а работникам использовать перчатки с защитой от порезов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1319, 'es-ES', 'Colocar señales de advertencia claras de "Prohibido el paso" y "Atención, caída de objetos" en el perímetro de la zona de trabajo y asignar personal de control.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1319, 'ru-RU', 'Разместить на видном месте по периметру рабочей зоны предупреждающие знаки "Проход запрещен" и "Осторожно, падение предметов" и выставить персонал для контроля.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1320, 'es-ES', 'Cumplir la secuencia de demolición especificada en el permiso de trabajo e instruir a todo el personal sobre los procedimientos de demolición por fases durante la charla de seguridad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1320, 'ru-RU', 'Соблюдать последовательность сноса, указанную в наряде-допуске, и обучить весь персонал поэтапным процедурам демонтажа во время целевого инструктажа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1321, 'es-ES', 'Asegurar la visibilidad instalando suficientes equipos de iluminación y colocando señalización reflectante en los trabajadores y en las instalaciones clave.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1321, 'ru-RU', 'Обеспечить достаточную видимость, установив необходимое количество осветительных приборов и разместив светоотражающие элементы на работниках и ключевых объектах.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1322, 'es-ES', 'Revisar el aislamiento de los equipos antes de su uso, proteger los cables con cubiertas adecuadas y verificar el correcto funcionamiento de todos los interruptores diferenciales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1322, 'ru-RU', 'Перед использованием проверить состояние изоляции оборудования, применить защитные короба для проводов и убедиться в работоспособности всех устройств защитного отключения (УЗО).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1341, 'es-ES', 'Antes de los trabajos, verificar la nivelación y compactación del terreno y, si es necesario, tomar medidas antivuelco como el refuerzo con planchas de acero.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1341, 'ru-RU', 'Перед началом работ проверить выравнивание и уплотнение грунта, при необходимости принять меры по предотвращению опрокидывания, например, укрепив площадку стальными листами.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1342, 'es-ES', 'Al estacionar la maquinaria, mantener una distancia de seguridad con las excavaciones. Estacionar en terreno llano y apoyar siempre la cuchara o la hoja en el suelo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1342, 'ru-RU', 'При парковке техники соблюдать безопасное расстояние от выемок, парковаться на ровной поверхности и всегда опускать ковш или отвал на землю.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1343, 'es-ES', 'Verificar el funcionamiento de las luces giratorias y las alarmas de marcha atrás de la maquinaria pesada y asignar un señalista para cubrir los puntos ciegos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1343, 'ru-RU', 'Проверить исправность проблесковых маячков и звуковых сигналов заднего хода тяжелой техники и назначить сигнальщика для контроля слепых зон.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1344, 'es-ES', 'Instalar señales de "Maquinaria pesada en operación" y "Prohibido el paso" en el perímetro de la zona de trabajo y asignar personal de control.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1344, 'ru-RU', 'Установить по периметру рабочей зоны знаки "Работает тяжелая техника" и "Проход запрещен" и выставить персонал для контроля.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1345, 'es-ES', 'Antes de iniciar los trabajos, verificar toda la documentación de la maquinaria: permiso de circulación, póliza de seguro y certificado de inspección de seguridad, comprobando su vigencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1345, 'ru-RU', 'Перед началом работ проверить всю документацию на технику: регистрационное свидетельство, страховой полис, свидетельство о прохождении проверки безопасности, а также срок их действия.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1346, 'es-ES', 'Verificar que el operador posee la cualificación requerida y compartir previamente el estado de salud y el plan de trabajo durante la charla de seguridad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1346, 'ru-RU', 'Проверить наличие у машиниста соответствующего удостоверения, а также в ходе целевого инструктажа обсудить его состояние здоровья и план работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1347, 'es-ES', 'Realizar una inspección previa de los dispositivos principales utilizando una lista de verificación diaria y detener el trabajo inmediatamente si se detecta alguna anomalía.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1347, 'ru-RU', 'Проводить предварительную проверку основных узлов на основе ежедневного чек-листа и немедленно прекращать работу при обнаружении неисправностей.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1348, 'es-ES', 'Asegurar una iluminación suficiente en la zona de trabajo con proyectores y exigir que los trabajadores lleven chalecos de alta visibilidad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1348, 'ru-RU', 'Обеспечить достаточное освещение рабочей зоны с помощью прожекторов и обязать работников носить сигнальные жилеты.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1349, 'es-ES', 'Mantener una distancia de seguridad con las líneas eléctricas aéreas o instalar protectores aislantes, y designar un observador dedicado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1349, 'ru-RU', 'Обеспечить безопасное расстояние до воздушных линий электропередачи или установить изолирующие защитные покрытия и назначить специального наблюдателя.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1350, 'es-ES', 'Al finalizar el trabajo, bajar la cuchara, apagar el motor y retirar la llave para guardarla en el lugar designado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1350, 'ru-RU', 'По окончании работы опустить ковш, выключить двигатель, извлечь ключ из замка зажигания и хранить его в специально отведенном месте.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1351, 'es-ES', 'Asignar un señalista dedicado y establecer un sistema de señales unificado (por radio o gestual) entre el operador y el señalista.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1351, 'ru-RU', 'Назначить ответственного сигнальщика и установить единую систему связи между машинистом и сигнальщиком (радиосвязь или стандартизированные знаки).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1352, 'es-ES', 'El señalista debe emitir las señales siempre desde una posición visible para el operador y confirmar constantemente que mantiene el contacto visual.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1352, 'ru-RU', 'Сигнальщик должен всегда подавать сигналы из места, видимого машинисту, и постоянно проверять наличие визуального контакта.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1353, 'es-ES', 'Asignar señalistas dedicados por tarea y separar los canales de radio para evitar interferencias entre señales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1353, 'ru-RU', 'Назначать отдельных сигнальщиков для каждого вида работ и использовать разные каналы радиосвязи для исключения помех.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1354, 'es-ES', 'Establecer el radio de giro máximo para cada equipo y restringir estrictamente el acceso de personal mediante cinta de balizamiento y conos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1354, 'ru-RU', 'Определить максимальный радиус поворота для каждой единицы техники и строго ограничить доступ персонала с помощью сигнальной ленты и конусов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1355, 'es-ES', 'Antes de trabajar, detectar la ubicación de servicios enterrados, señalizar las zonas de riesgo y hacer que un guía dirija la maquinaria antes de entrar.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1355, 'ru-RU', 'Перед началом работ определить местоположение подземных коммуникаций, обозначить опасные зоны и обеспечить сопровождение техники сигнальщиком при въезде.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1356, 'es-ES', 'Antes de comenzar a trabajar, despejar materiales innecesarios y obstáculos del radio de trabajo para asegurar un espacio suficiente.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1356, 'ru-RU', 'Перед началом работ убрать из радиуса действия техники ненужные материалы и препятствия, чтобы обеспечить достаточное пространство.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1358, 'es-ES', 'Instalar obligatoriamente una cubierta en la caja de carga y hacer que un guía de carga verifique el cumplimiento del peso adecuado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1358, 'ru-RU', 'Обязательно установить тент на грузовую платформу, а соблюдение допустимой массы груза должен проверять ответственный за погрузку.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1359, 'es-ES', 'Instalar calzos o topes en el punto de descarga y aproximarse lentamente siguiendo las señales del guía.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1359, 'ru-RU', 'В месте разгрузки установить колесные упоры или барьеры и приближаться медленно, следуя сигналам ответственного лица.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1360, 'es-ES', 'Medir la tasa de dosis de radiación para delimitar la zona controlada e instalar señalización específica y luces intermitentes para restringir estrictamente el acceso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1360, 'ru-RU', 'Измерить мощность дозы излучения для определения границ контролируемой зоны, установить специальные знаки и световые сигналы для строгого ограничения доступа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1361, 'es-ES', 'Calcular y minimizar el tiempo de exposición a la radiación antes del trabajo y usar obligatoriamente dosímetros personales (TLD) y de lectura directa.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1361, 'ru-RU', 'Перед работой рассчитать и минимизировать время радиационного воздействия, а также в обязательном порядке использовать индивидуальные (ТЛД) и прямопоказывающие дозиметры.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1362, 'es-ES', 'Mantener una distancia suficiente con la fuente de radiación y realizar la inspección por transmisión utilizando un tubo guía de control remoto.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1362, 'ru-RU', 'Соблюдать достаточное расстояние от источника излучения и проводить радиографический контроль с использованием направляющего шланга для дистанционного управления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1363, 'es-ES', 'Instalar blindajes adecuados al tipo e intensidad de la radiación y reforzar con pantallas de plomo para prevenir la radiación dispersa.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1363, 'ru-RU', 'Установить защитные экраны, соответствующие типу и интенсивности излучения, и усилить их свинцовыми барьерами для предотвращения рассеянного излучения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1364, 'es-ES', 'Inmediatamente después de finalizar la inspección, verificar con un medidor de radiación si la fuente ha regresado a su contenedor y almacenarlo de forma segura.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1364, 'ru-RU', 'Сразу после окончания контроля с помощью дозиметра-радиометра убедиться в возвращении источника в защитный контейнер и обеспечить его безопасное хранение.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1365, 'es-ES', 'Utilizar contenedores de transporte específicos y homologados, asegurando los cierres, y colocar las etiquetas de material radiactivo en el vehículo de transporte.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1365, 'ru-RU', 'Использовать утвержденные транспортные контейнеры, надежно запирать их и наносить на транспортное средство знаки радиационной опасности.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1366, 'es-ES', 'Asignar un vigilante exclusivo para la zona de trabajo y comunicar continuamente el estado de los trabajos mediante un megáfono o radio.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1366, 'ru-RU', 'Назначить специального наблюдателя для рабочей зоны и постоянно информировать о ходе работ по громкоговорителю или рации.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1367, 'es-ES', 'Solo el personal con licencia legal y formación en seguridad puede realizar el trabajo. El procedimiento del día se compartirá en detalle durante la charla de seguridad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1367, 'ru-RU', 'К работе допускается только персонал, имеющий соответствующую лицензию и прошедший обучение по безопасности. Порядок выполнения работ подробно обсуждается на целевом инструктаже.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1368, 'es-ES', 'Conocer los escenarios de respuesta a emergencias y mantener siempre disponible en el lugar el equipo de rescate de emergencia (contenedores de plomo, pinzas, etc.).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1368, 'ru-RU', 'Знать сценарии действий в аварийных ситуациях и всегда иметь на месте аварийно-спасательное оборудование (свинцовый контейнер, щипцы и т.д.).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1369, 'es-ES', 'Antes del trabajo, revisar la batería y la fecha de calibración del medidor, y verificar su correcto funcionamiento con una fuente de calibración.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1369, 'ru-RU', 'Перед работой проверить заряд батареи и срок поверки измерительного прибора, а также его исправность с помощью контрольного источника.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1380, 'es-ES', 'Antes del trabajo, realizar una inspección completa del funcionamiento de los dispositivos de seguridad, como el limitador de fin de carrera de elevación y el limitador de carga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1380, 'ru-RU', 'Перед началом работ провести полную проверку работоспособности приборов безопасности, таких как ограничитель высоты подъема крюка и ограничитель грузоподъемности.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1382, 'es-ES', 'Establecer un sistema de comunicación por radio o un código de señales gestuales unificado. Detener el trabajo si el señalista no está visible.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1382, 'ru-RU', 'Установить систему связи по рации или единую систему знаковой сигнализации. Прекратить работу, если сигнальщик находится вне зоны видимости.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1383, 'es-ES', 'Antes de su uso, inspeccionar todos los accesorios de elevación para detectar deformaciones o corrosión y utilizar únicamente productos que cumplan con las especificaciones.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1383, 'ru-RU', 'Перед использованием проверить все грузозахватные приспособления на предмет деформации и коррозии, использовать только изделия, соответствующие нормам.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1385, 'es-ES', 'Colocar los cables o eslingas correctamente, sin torceduras, y ajustarlos para que la carga se distribuya de manera uniforme.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1385, 'ru-RU', 'Правильно и без перекручивания закреплять канаты, обеспечивая равномерное распределение нагрузки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1388, 'es-ES', 'Mantener una separación uniforme entre las cargas apiladas y asegurar espacio suficiente para la entrada y salida de las horquillas o eslingas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1388, 'ru-RU', 'Соблюдать одинаковое расстояние между складируемыми грузами и обеспечивать достаточное пространство для свободного ввода вил или строп.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1392, 'es-ES', 'Seleccionar un blindaje con el espesor adecuado para la intensidad de la energía de la radiación e instalarlo solapando las juntas para evitar fugas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1392, 'ru-RU', 'Выбирать защитный экран толщиной, соответствующей интенсивности энергии излучения, и устанавливать его с перекрытием стыков для предотвращения утечек.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1393, 'es-ES', 'Instalar colimadores y pantallas de blindaje específicas alrededor del objeto a inspeccionar para bloquear la emisión de radiación dispersa innecesaria.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1393, 'ru-RU', 'Установить коллиматоры и специальные защитные экраны вокруг объекта контроля для блокирования нежелательного рассеянного излучения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1395, 'es-ES', 'Antes de iniciar el trabajo, verificar el estado y la correcta colocación de todos los dosímetros termoluminiscentes (TLD) y de lectura directa, asegurando que se lleven en la posición reglamentaria (p. ej., a la altura del pecho).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1395, 'ru-RU', 'Перед началом работ провести полную проверку состояния и ношения термолюминесцентных дозиметров (ТЛД) и дозиметров прямого считывания, убедившись в их правильном закреплении в установленном месте (например, на груди).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1396, 'es-ES', 'Monitorizar en tiempo real la dosis recibida por cada trabajador y, al alcanzar la dosis planificada, detener inmediatamente el trabajo y proceder al relevo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1396, 'ru-RU', 'Осуществлять мониторинг индивидуальной дозы облучения каждого работника в режиме реального времени и при достижении запланированной дозы немедленно прекращать работу и производить смену.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1397, 'es-ES', 'Mantener un registro digital actualizado del dosimétrico diario y excluir inmediatamente del trabajo a cualquier operario en riesgo de superar los límites de dosis legales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1397, 'ru-RU', 'Вести постоянный компьютеризированный учёт ежедневных доз облучения и при риске превышения установленных законом пределов дозы немедленно отстранять соответствующего работника от работы.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1398, 'es-ES', 'Antes de iniciar los trabajos, utilizar una fuente de calibración para comprobar la respuesta del detector de radiación y verificar el nivel de la batería.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1398, 'ru-RU', 'Перед началом работ проверить реакцию детектора с помощью контрольного источника и убедиться в достаточном уровне заряда батареи.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1399, 'es-ES', 'Tras finalizar cada ensayo radiográfico, confirmar obligatoriamente con el detector que la fuente radiactiva se ha replegado de forma segura a su contenedor blindado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1399, 'ru-RU', 'После завершения каждого сеанса радиографического контроля обязательно использовать детектор для окончательного подтверждения возврата источника в защитный контейнер.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1400, 'es-ES', 'Medir periódicamente la tasa de dosis en los límites de la zona controlada para reevaluar la idoneidad de la señalización de advertencia y el balizamiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1400, 'ru-RU', 'Регулярно измерять мощность дозы на границах зоны работ для перепроверки правильности расположения предупреждающих знаков и ограждений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1012, 'es-ES', 'Realizar una prueba de ajuste de la mascarilla (ajuste nasal, bandas) y verificar el sellado de las gafas de seguridad (uso obligatorio de mascarillas tipo FFP2 o superior).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1012, 'ru-RU', 'Проверить герметичность прилегания маски (носовой зажим, лямки) и плотность прилегания защитных очков (обязательное использование респираторов класса не ниже FFP2).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1013, 'es-ES', 'Tras ponerse el traje de protección, realizar una verificación cruzada por parejas (Buddy System) para comprobar la ausencia de aberturas y el correcto sellado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1013, 'ru-RU', 'После надевания пылезащитного костюма провести взаимную проверку в парах (система напарничества) для контроля отсутствия зазоров и герметичности.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1014, 'es-ES', 'Suministrar el conjunto completo de Equipos de Protección Individual (EPI), incluyendo traje, mascarilla, gafas y guantes de protección, antes de iniciar la tarea.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1014, 'ru-RU', 'Перед началом работ обеспечить полную выдачу средств индивидуальной защиты (СИЗ): пылезащитный костюм, респиратор, защитные очки, перчатки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1015, 'es-ES', 'Realizar una evaluación de compatibilidad y ajuste antes del trabajo para proporcionar EPIs adecuados a la talla del trabajador y aprobar su correcta colocación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1015, 'ru-RU', 'Перед работой провести оценку антропометрических данных для подбора СИЗ соответствующего размера и получить окончательное подтверждение правильности их надевания.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1016, 'es-ES', 'Implementar medidas de restricción de acceso físico mediante la instalación de cinta de balizamiento, conos y postes delimitadores en el perímetro del área de trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1016, 'ru-RU', 'Принять меры по физическому ограничению доступа путем установки сигнальной ленты, дорожных конусов и оградительных столбиков по периметру рабочей зоны.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1068, 'es-ES', 'Revisar la ropa ignífuga y los guantes de cuero en busca de contaminación (aceite, etc.) o daños, y sustituir inmediatamente cualquier artículo defectuoso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1068, 'ru-RU', 'Проверить огнестойкую одежду и кожаные перчатки на предмет загрязнений (масло и т.п.) и повреждений, немедленно заменяя неисправные изделия.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1069, 'es-ES', 'Asegurar el uso correcto de la ropa ignífuga, abrochando completamente los botones/cremalleras y metiendo los guantes por dentro de las mangas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1069, 'ru-RU', 'Проверить правильность ношения огнестойкой одежды: пуговицы/молнии застегнуты до конца, перчатки заправлены под рукава.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1070, 'es-ES', 'Detener los trabajos en altura si se detecta cualquier anomalía en el estado de salud del trabajador y verificar su condición física mediante la charla de seguridad (Toolbox Talk) antes de comenzar.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1070, 'ru-RU', 'При ухудшении состояния здоровья работника на высоте немедленно прекратить работы. Перед началом работ проводить проверку самочувствия в ходе целевого инструктажа (TBM).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1071, 'es-ES', 'En caso de condiciones meteorológicas adversas, suspender inmediatamente los trabajos y modificar la planificación para realizar desde el suelo las tareas que sean posibles.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1071, 'ru-RU', 'При неблагоприятных погодных условиях немедленно прекратить работы и внести изменения в план, перенеся выполнение возможных задач на землю.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1072, 'es-ES', 'Antes de empezar, delimitar la zona de acceso restringido bajo el área de trabajo en altura, instalar señalización de advertencia y activar un sistema de vigilancia por parejas (2 personas).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1072, 'ru-RU', 'Перед началом работ установить ограждение запретной зоны под местом работ на высоте, вывесить предупреждающие знаки и организовать систему наблюдения в составе бригады из 2 человек.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1073, 'es-ES', 'Al usar una escalera de mano, mantener un ángulo de inclinación seguro de 75 grados y comprobar previamente el estado de las zapatas antideslizantes de la base.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1073, 'ru-RU', 'При использовании приставной лестницы соблюдать безопасный угол наклона 75 градусов и предварительно проверять состояние противоскользящих башмаков.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1074, 'es-ES', 'Prohibido trabajar desde el último peldaño de la escalera. Al usar escaleras móviles, verificar que los estabilizadores (outriggers) estén correctamente desplegados.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1074, 'ru-RU', 'Запрещается работать с верхней ступеньки лестницы. При использовании передвижных лестниц убедиться в установке выносных опор (аутригеров).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1075, 'es-ES', 'Antes del uso, reinspeccionar la escalera en busca de deformaciones o fisuras y permitir en la obra únicamente equipos homologados que cumplan la normativa.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1075, 'ru-RU', 'Перед началом работ повторно проверить лестницу на наличие деформаций/трещин и допускать на объект только сертифицированные изделия, соответствующие стандартам.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1080, 'es-ES', 'Prohibir el uso de calzado resbaladizo para trabajos en altura y comprobar el estado de desgaste del calzado de seguridad antes de comenzar.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1080, 'ru-RU', 'Запретить работникам на высоте носить скользкую обувь и проверять степень износа защитной обуви перед началом работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1163, 'es-ES', 'La plataforma de trabajo (andamio) debe instalarse de forma segura para evitar su desplazamiento, comprobando el estado de las barandillas y la fijación de las plataformas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1163, 'ru-RU', 'Рабочий настил (помост) должен быть прочно установлен для предотвращения смещения; проверить состояние защитных ограждений и крепления настила.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1164, 'es-ES', 'El trabajador en altura debe llevar puesto el arnés de seguridad en todo momento y cumplir estrictamente el principio de doble anclaje (100% anclado).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1164, 'ru-RU', 'Работник на высоте должен постоянно использовать предохранительный пояс (страховочную привязь) и неукоснительно соблюдать принцип двойного крепления стропа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1165, 'es-ES', 'Mantener la escalera a 75º, asegurar que dispone de zapatas antideslizantes y asignar a un compañero en la base para su estabilización (sistema de 2 personas).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1165, 'ru-RU', 'Поддерживать угол наклона лестницы 75°, убедиться в наличии противоскользящих башмаков и назначить второго работника для фиксации основания лестницы.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1166, 'es-ES', 'Delimitar la zona de acceso restringido bajo el área de trabajo, colocar señales de advertencia de riesgo de caída de objetos y revisar las redes de protección.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1166, 'ru-RU', 'Установить ограждение зоны ограниченного доступа под местом работ, разместить предупреждающие знаки о риске падения предметов и проверить защитно-улавливающие сетки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1167, 'es-ES', 'Prohibido el uso de calzado resbaladizo o que se salga con facilidad y mantener la plataforma de trabajo libre de cualquier sustancia contaminante.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1167, 'ru-RU', 'Запретить ношение скользкой или легкоснимаемой обуви и удалять загрязняющие вещества с поверхности рабочего настила.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1168, 'es-ES', 'Utilizar componentes homologados para el montaje de la plataforma de trabajo y aplicar medidas para prevenir su vuelco o desplazamiento (refuerzo de fijaciones).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1168, 'ru-RU', 'При монтаже рабочего настила использовать сертифицированные компоненты и принять меры против опрокидывания и смещения (усиление креплений).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1214, 'es-ES', 'Detener inmediatamente el trabajo si el operario en altura presenta alguna indisposición y verificar su estado físico en la charla de seguridad (TBM) previa al inicio.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1214, 'ru-RU', 'При любом недомогании у работника на высоте немедленно прекратить работу; перед началом работ проверять самочувствие в ходе целевого инструктажа (TBM).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1215, 'es-ES', 'Suspender completamente los trabajos en altura en el exterior en caso de condiciones meteorológicas adversas y reajustar el plan de trabajo según los procedimientos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1215, 'ru-RU', 'При неблагоприятных погодных условиях полностью прекратить наружные работы на высоте и провести корректировку плана работ в соответствии с инструкциями.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1216, 'es-ES', 'Planificar la ejecución de tareas a nivel del suelo siempre que sea posible y gestionar la segregación de rutas de tránsito verticales y horizontales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1216, 'ru-RU', 'Разработать план приоритетного выполнения работ на земле, если это возможно, и обеспечить разделение вертикальных и горизонтальных маршрутов передвижения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1217, 'es-ES', 'Instalar una línea de prohibición de acceso bajo la zona de trabajo en altura y colocar señalización de advertencia de riesgo de caída y de objetos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1217, 'ru-RU', 'Установить ограждение запретной зоны под местом работ на высоте и вывесить предупреждающие знаки о риске падения людей и предметов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1218, 'es-ES', 'Prohibir el uso de calzado con suela resbaladiza o suelto y comprobar que se lleva puesto el calzado de seguridad específico para trabajos en altura.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1218, 'ru-RU', 'Запретить ношение обуви со скользкой или свободной подошвой и проверять наличие специальной защитной обуви для работ на высоте.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1219, 'es-ES', 'Cumplir el principio de trabajo en parejas (2 personas), asignar un vigilante y asegurar la disponibilidad constante de medios de comunicación como radios.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1219, 'ru-RU', 'Соблюдать принцип работы в паре (бригада из 2 человек), назначать наблюдающего и обеспечивать постоянную доступность средств связи, таких как рации.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1220, 'es-ES', 'Impartir formación previa en la charla de seguridad (TBM) sobre los riesgos de caída, los procedimientos de respuesta y las medidas específicas según las condiciones meteorológicas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1220, 'ru-RU', 'В ходе целевого инструктажа (TBM) провести обучение по рискам падения, мерам реагирования и действиям в зависимости от погодных условий.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1221, 'es-ES', 'Utilizar únicamente las vías de acceso autorizadas, mantener tres puntos de apoyo al moverse y prohibir el ascenso por estructuras improvisadas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1221, 'ru-RU', 'Использовать утвержденные пути доступа, при передвижении соблюдать правило трёх точек опоры, запретить подъём по временным конструкциям.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1222, 'es-ES', 'Instalar proyectores para asegurar una iluminación de trabajo adecuada y retirar previamente cualquier obstáculo de las rutas de tránsito.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1222, 'ru-RU', 'Установить прожекторы для обеспечения достаточной освещенности рабочей зоны и предварительно убрать все препятствия с путей передвижения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1223, 'es-ES', 'Establecer pausas de descanso periódicas y realizar un seguimiento constante del estado de anclaje de los equipos de protección a través del vigilante.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1223, 'ru-RU', 'Обеспечить периодические перерывы для отдыха и постоянный мониторинг состояния крепления страховочных стропов наблюдающим.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1224, 'es-ES', 'Instalar la escalera con un ángulo de 75 grados, asegurar que las zapatas de goma antideslizantes estén en buen estado y fijar la parte superior.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1224, 'ru-RU', 'Устанавливать лестницу под углом 75 градусов, оснащать основание противоскользящими резиновыми накладками и закреплять верхнюю часть.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1225, 'es-ES', 'Prohibido trabajar desde el último peldaño de la escalera. Realizar una comprobación completa del despliegue de los estabilizadores (outriggers) antes de su uso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1225, 'ru-RU', 'Запрещается работать с верхней ступеньки лестницы; перед передвижением провести полную проверку состояния выдвинутых аутригеров.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1226, 'es-ES', 'Inspeccionar la escalera antes del uso en busca de corrosión, fisuras o deformaciones y sustituirla inmediatamente si se detectan daños.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1226, 'ru-RU', 'Перед работой проверить лестницу на наличие коррозии, трещин, деформаций и немедленно произвести замену в случае обнаружения повреждений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1227, 'es-ES', 'Instalar las plataformas del andamio de forma robusta, garantizando la anchura y capacidad de carga adecuadas, y tomar medidas para evitar su desplazamiento o vuelco.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1227, 'ru-RU', 'Настилы лесов устанавливать прочно, обеспечивая достаточную ширину и несущую способность, и принимать меры против смещения и опрокидывания.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1228, 'es-ES', 'Verificar la instalación de barandillas de protección superior e intermedia y rodapiés en el lado exterior del andamio en todos los niveles de trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1228, 'ru-RU', 'Проверить установку верхнего и среднего ограждений, а также бортовых досок по внешнему периметру лесов на всех рабочих ярусах.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1229, 'es-ES', 'Prohibido el desmontaje no autorizado de la estructura del andamio. Cualquier modificación estructural requiere la aprobación del responsable de seguridad para su reinstalación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1229, 'ru-RU', 'Запрещается самовольно разбирать конструкции лесов; при необходимости внесения изменений в конструкцию, производить переустановку только после согласования с ответственным за безопасность.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1230, 'es-ES', 'Prohibido apilar materiales directamente sobre la plataforma de trabajo; los materiales innecesarios deben ser bajados y almacenados ordenadamente de inmediato.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1230, 'ru-RU', 'Запрещается складировать материалы непосредственно на рабочем настиле; ненужные материалы немедленно спускать вниз и убирать.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1231, 'es-ES', 'Instalar las plataformas de manera contigua para eliminar huecos. Si existen desniveles, corregirlos antes de iniciar el trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1231, 'ru-RU', 'Устанавливать щиты настила вплотную друг к другу без зазоров; при возникновении перепадов высот, устранить их перед началом работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1232, 'es-ES', 'Antes de la instalación, evaluar la resistencia de la estructura de soporte considerando la carga de trabajo y verificar que la capacidad de carga es suficiente.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1232, 'ru-RU', 'Перед монтажом провести проверку прочности несущих конструкций с учётом рабочей нагрузки и убедиться в достаточной несущей способности.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1233, 'es-ES', 'Todos los trabajadores en altura deben usar un arnés de seguridad y cumplir con el principio de doble anclaje a una estructura sólida.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1233, 'ru-RU', 'Все работники на высоте должны использовать предохранительный пояс и соблюдать принцип двойного крепления стропа к прочной конструкции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1234, 'es-ES', 'El punto de anclaje del equipo de protección debe estar situado por encima de la cabeza del trabajador para minimizar la distancia de caída.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1234, 'ru-RU', 'Закреплять карабин стропа в точке анкеровки, расположенной выше головы работника, чтобы минимизировать высоту возможного падения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1235, 'es-ES', 'Realizar una inspección completa del arnés de seguridad y de las eslingas antes y después de cada uso para detectar desgaste o cortes, y sustituirlos si están dañados.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1235, 'ru-RU', 'До и после работы проводить полную проверку предохранительного пояса и стропов на предмет износа и порезов, при повреждении производить замену.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1236, 'es-ES', 'Guardar siempre las herramientas y materiales en cajas de herramientas o bolsas portaherramientas de cinturón e impartir formación sobre la prohibición de lanzarlos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1236, 'ru-RU', 'Хранить инструменты и материалы строго в ящиках или поясных сумках и проводить инструктаж о запрете их сбрасывания вниз.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1237, 'es-ES', 'Prohibir la colocación de materiales en los bordes de la plataforma de trabajo y comprobar el estado de instalación de las redes de protección contra caídas y marquesinas de seguridad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1237, 'ru-RU', 'Запретить размещение материалов у края рабочего настила и проверять состояние установки защитно-улавливающих сеток и защитных козырьков.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1238, 'es-ES', 'Inspeccionar el estado de la malla y los soportes de la red de seguridad contra caídas (UNE-EN 1263-1) y retirar periódicamente los objetos acumulados.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1238, 'ru-RU', 'Проверка состояния полотна и опор защитно-улавливающей сетки, регулярное удаление скопившихся на ней предметов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1245, 'es-ES', 'Realizar una coordinación previa para controlar las interferencias con trabajos en altura y mover las cargas pesadas a la menor altura posible.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1245, 'ru-RU', 'Проведение предварительного согласования для контроля совмещения с работами на высоте; перемещение тяжелых грузов на минимально возможной высоте.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1111, 'es-ES', 'Instalar iluminación de trabajo para asegurar una iluminancia suficiente en la zona de trabajo y garantizar previamente rutas de acceso seguras.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1111, 'ru-RU', 'Установка рабочего освещения для обеспечения достаточной освещенности в рабочей зоне и предварительное обеспечение безопасных путей доступа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1112, 'es-ES', 'Antes del desmontaje, cortar los suministros de gas y electricidad y aplicar el procedimiento de consignación (Lock-out) con una etiqueta roja (''No operar'').', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1112, 'ru-RU', 'Перед демонтажом отключить подачу газа и электроэнергии, выполнить блокировку (Lock-out) и вывесить красную бирку (''Не включать! Идут работы'').', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1113, 'es-ES', 'Prohibir estrictamente el acceso de materiales inflamables al área de trabajo y disponer de equipos de extinción de emergencia, como extintores, en las proximidades.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1113, 'ru-RU', 'Строго запретить доступ легковоспламеняющихся материалов в рабочую зону и разместить в непосредственной близости средства пожаротушения (огнетушители).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1114, 'es-ES', 'Mediante charlas de seguridad (TBM), instruir y asegurar que todo el personal conoce los procedimientos de respuesta a emergencias para escenarios como incendios o fugas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1114, 'ru-RU', 'Провести целевой инструктаж (TBM) для ознакомления всего персонала с процедурами действий в аварийных ситуациях по различным сценариям (пожар, утечка и т.д.).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1119, 'es-ES', 'Realizar una inspección previa del estado de las botellas de nitrógeno y las líneas de suministro, y respetar los límites de presión de inyección.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1119, 'ru-RU', 'Провести предварительную проверку исправности баллонов с азотом и линий подачи, а также соблюдать установленные пределы давления впрыска.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1121, 'es-ES', 'Disponer del diagrama de tuberías e instrumentación (P&ID) en el sitio y ejecutar el procedimiento de aislamiento de líneas por etapas tras su revisión en la charla de seguridad (TBM).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1121, 'ru-RU', 'Разместить на месте схему трубопроводов и ознакомиться с поэтапной процедурой их отключения на инструктаже (TBM) перед выполнением работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1122, 'es-ES', 'Antes de desconectar la línea, liberar completamente la presión residual y realizar una verificación final del estado del drenaje interno.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1122, 'ru-RU', 'Перед отсоединением трубопровода полностью сбросить остаточное давление и окончательно проверить состояние внутреннего дренажа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1123, 'es-ES', 'Realizar pruebas de estanqueidad en las conexiones de la línea de suministro y sustituir previamente las tuberías/mangueras deterioradas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1123, 'ru-RU', 'Провести испытания на герметичность соединений линии подачи и заблаговременно заменить изношенные трубы/шланги.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1124, 'es-ES', 'Colocar etiquetas de identificación (ABIERTA/CERRADA) en todas las válvulas y volver a verificar el diagrama de líneas antes de cualquier operación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1124, 'ru-RU', 'Установить на все клапаны идентификационные бирки (ОТКРЫТО/ЗАКРЫТО) и перепроверить схему трубопроводов перед началом манипуляций.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1125, 'es-ES', 'Antes del trabajo, instalar dispositivos de bloqueo de válvulas (Lock-out) y colocar la etiqueta roja específica (etiqueta de bloqueo).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1125, 'ru-RU', 'Перед началом работ установить блокировочные устройства на клапаны (Lock-out) и вывесить специальную красную бирку (блокировочную).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1126, 'es-ES', 'Verificar el estado de estanqueidad de las válvulas de aislamiento principales y realizar una prueba de accionamiento para comprobar si están agarrotadas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1126, 'ru-RU', 'Проверка герметичности основных запорных клапанов и предварительное тестирование работоспособности для выявления заклинивания.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1130, 'es-ES', 'Utilizar la línea específica para la purga de gas residual y controlar el acceso de personal alrededor del punto de venteo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1130, 'ru-RU', 'Использовать выделенную линию для сброса остаточного газа и осуществлять контроль доступа персонала в зоне вокруг точки сброса.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1131, 'es-ES', 'Reforzar la purga por barrido para eliminar el gas residual en codos y puntos ciegos de la línea.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1131, 'ru-RU', 'Усилить продувку для удаления остаточного газа из изгибов и застойных зон трубопровода.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1132, 'es-ES', 'Hacer obligatorio el uso de detectores de gas personales y monitorizar de forma continua el gas residual en la zona de trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1132, 'ru-RU', 'Обязательное ношение индивидуальных газоанализаторов и постоянный мониторинг остаточных газов в рабочей зоне.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1133, 'es-ES', 'Verificar la ausencia de presión residual (cero) en el manómetro antes de proceder a aflojar los pernos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1133, 'ru-RU', 'Убедиться в отсутствии остаточного давления (показание ''0'' на манометре) перед началом ослабления болтов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1134, 'es-ES', 'Abrir la válvula de purga de presión residual lentamente para despresurizar de forma gradual y verificar la dirección de la descarga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1134, 'ru-RU', 'Медленно и плавно открывать клапан сброса остаточного давления для постепенной декомпрессии, контролируя направление сброса.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1135, 'es-ES', 'Comprobar el correcto funcionamiento del manómetro y realizar una verificación cruzada a través de la válvula de drenaje.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1135, 'ru-RU', 'Проверка исправности манометра и проведение перекрестной проверки через дренажный клапан.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1136, 'es-ES', 'Antes del trabajo, eliminar completamente el fluido de la tubería, realizar una purga con nitrógeno y verificar la presión cero en el manómetro.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1136, 'ru-RU', 'Перед работой полностью удалить жидкость из трубопровода, выполнить продувку азотом и убедиться в отсутствии остаточного давления (''0'' на манометре).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1137, 'es-ES', 'Prohibir el uso de herramientas improvisadas; utilizar únicamente herramientas específicas autorizadas y evitar aplicar un par de apriete excesivo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1137, 'ru-RU', 'Запретить использование нештатных инструментов, применять только утвержденный специальный инструмент и избегать приложения чрезмерного крутящего момента.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1138, 'es-ES', 'Antes del trabajo, usar rigurosamente guantes dieléctricos y otros EPI, y tomar medidas de seguridad como colocar capuchones protectores en las partes desconectadas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1138, 'ru-RU', 'Перед работой строго использовать диэлектрические перчатки и СИЗ, применять меры безопасности, такие как установка защитных колпачков на отсоединенные части.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1142, 'es-ES', 'Antes de desconectar, aplicar el procedimiento LOTO para un corte total de energía y verificar la ausencia de corriente residual con un comprobador antes de aislar.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1142, 'ru-RU', 'Перед отсоединением полностью отключить питание (LOTO), проверить тестером отсутствие остаточного напряжения, после чего выполнить изоляцию.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1143, 'es-ES', 'Utilizar cuerdas de seguridad para herramientas (lanyards) y trabajar en equipos de dos para activar un sistema de vigilancia y cooperación en la zona inferior.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1143, 'ru-RU', 'Использовать страховочные стропы для инструмента и работать в паре (2 человека) для обеспечения наблюдения за зоной внизу и взаимодействия.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1144, 'es-ES', 'El trabajo debe realizarse, por principio, en equipos de dos personas, y los contactos de emergencia y las vías de evacuación deben ser conocidos de antemano durante la charla de seguridad (TBM).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1144, 'ru-RU', 'Работы должны выполняться, как правило, в паре (2 человека); каналы экстренной связи и пути эвакуации должны быть изучены заранее на инструктаже (TBM).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1151, 'es-ES', 'Tras cerrar las válvulas de la sección a reemplazar, drenar/ventear completamente el fluido de la tubería antes de trabajar.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1151, 'ru-RU', 'После перекрытия клапанов на заменяемом участке, полностью слить/выпустить (Drain/Vent) рабочую среду из трубопровода перед началом работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1152, 'es-ES', 'Volver a instruir sobre la estructura del equipo y la secuencia de reemplazo en la charla de seguridad (TBM) y disponer de los planos revisados más recientes en el lugar.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1152, 'ru-RU', 'Провести повторный инструктаж по конструкции оборудования и порядку замены на TBM, обеспечить наличие на месте последней ревизии чертежей.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1153, 'es-ES', 'Instalar un dispositivo de bloqueo en el cuadro eléctrico y colocar una etiqueta roja, gestionando que solo el personal designado pueda desbloquearlo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1153, 'ru-RU', 'Установить запирающее устройство на электрический щит и вывесить красную бирку, обеспечив доступ к снятию блокировки только уполномоченному персоналу.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1154, 'es-ES', 'Tras el purgado, medir con precisión el estado interno con un detector de gases para confirmar que se encuentra dentro de los límites de seguridad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1154, 'ru-RU', 'После вытеснения, провести точное измерение внутренней среды газоанализатором и убедиться, что показатели находятся в пределах безопасных норм.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1155, 'es-ES', 'Dirigir la salida de venteo del gas de purga hacia una zona segura e instalar una barrera de control de acceso alrededor.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1155, 'ru-RU', 'Направить выходное отверстие для сброса вытесняющего газа в безопасное место и установить ограждение для контроля доступа в прилегающей зоне.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1156, 'es-ES', 'Al inyectar el gas de purga, aumentar la presión gradualmente y monitorizar las lecturas del manómetro en tiempo real.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1156, 'ru-RU', 'При подаче вытесняющего газа, повышать давление постепенно и отслеживать показания манометра в режиме реального времени.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1195, 'es-ES', 'Antes de desmontar, cerrar tanto la válvula de suministro de gas como la de purga, confirmar su estado de bloqueo y colocar una etiqueta roja.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1195, 'ru-RU', 'Перед разборкой/демонтажом закрыть клапан подачи газа и продувочный клапан, убедиться в их заблокированном состоянии и вывесить красную бирку.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1196, 'es-ES', 'Aplicar el procedimiento LOTO (Bloqueo y Etiquetado) instalando un dispositivo de bloqueo que solo pueda ser retirado por personal autorizado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1196, 'ru-RU', 'Применить процедуру LOTO (Блокировка и маркировка), установив блокировочное устройство, которое может снять только уполномоченный работник.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1197, 'es-ES', 'Tras el cierre de la válvula, colocar una señal de ''No operar'' y compartir la información del punto de aislamiento con todo el personal durante la charla de seguridad (TBM).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1197, 'ru-RU', 'После перекрытия клапана вывесить знак ''Не включать'' и на инструктаже (TBM) довести информацию о точке отключения до всего персонала.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1198, 'es-ES', 'Aislar por duplicado la fuente de alimentación del actuador y el suministro de gas, y confirmar finalmente que el equipo está inoperativo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1198, 'ru-RU', 'Обеспечить двойную изоляцию источника питания привода и подачи газа, и окончательно убедиться в неработоспособности оборудования.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1199, 'es-ES', 'Prohibir estrictamente la retirada del dispositivo LOTO hasta que se realice una verificación cruzada por dos personas basada en una lista de comprobación tras finalizar el trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1199, 'ru-RU', 'Строго запретить снятие устройства LOTO до проведения перекрестной проверки двумя работниками по чек-листу после завершения работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1200, 'es-ES', 'Eliminar completamente el gas interno mediante purga y verificar obligatoriamente la presión cero en el manómetro.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1200, 'ru-RU', 'Полностью удалить внутренний газ путем продувки и обязательно убедиться в отсутствии остаточного давления (''0'' на манометре).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1201, 'es-ES', 'Utilizar un detector de fugas o agua jabonosa para medir con precisión la presencia de gas residual antes de iniciar el trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1201, 'ru-RU', 'Использовать течеискатель или мыльный раствор для точного определения наличия остаточного газа перед началом работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1202, 'es-ES', 'Realizar ciclos repetidos de purga con nitrógeno y barrido, considerando la estructura de la tubería, para asegurar la eliminación completa del gas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1202, 'ru-RU', 'С учетом конструкции трубопровода, выполнить повторные циклы вытеснения азотом и продувки для полного удаления газа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1203, 'es-ES', 'Orientar el venteo hacia una zona segura, controlar el acceso a los alrededores y asegurar las vías de paso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1203, 'ru-RU', 'Направить сброс в безопасную зону, ограничить доступ в прилегающей области и обеспечить безопасность проходов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1204, 'es-ES', 'Abrir la válvula de drenaje lentamente para despresurizar de forma gradual y monitorizar constantemente cualquier vibración en la tubería.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1204, 'ru-RU', 'Медленно открывать дренажный клапан для постепенного сброса давления, постоянно контролируя возможную вибрацию трубопровода.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1205, 'es-ES', 'Todos los equipos y herramientas eléctricas utilizadas en la zona de desmontaje deben ser obligatoriamente de tipo antideflagrante (ATEX).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1205, 'ru-RU', 'Все электрооборудование и инструменты, используемые в зоне демонтажа, должны в обязательном порядке быть во взрывозащищенном исполнении.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1206, 'es-ES', 'Instalar iluminación de trabajo antideflagrante para asegurar la iluminancia en la zona y verificar el estado del aislamiento de las conexiones del cableado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1206, 'ru-RU', 'Для обеспечения освещенности рабочей зоны установить взрывозащищенные светильники и проверить состояние изоляции кабельных соединений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1207, 'es-ES', 'Antes del trabajo, verificar la marca de certificación antideflagrante (Ex) en los equipos portátiles y controlar estrictamente la entrada de equipos no certificados.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1207, 'ru-RU', 'Перед работой проверить наличие маркировки взрывозащиты на переносном оборудовании и строго контролировать пронос несертифицированных устройств.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1208, 'es-ES', 'Antes del trabajo, revisar la Ficha de Datos de Seguridad (FDS) y asegurar una ventilación adecuada activando el sistema de extracción localizada y ventiladores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1208, 'ru-RU', 'Перед работой изучить Паспорт безопасности (MSDS), включить местную вытяжную вентиляцию и вентиляторы для обеспечения достаточного воздухообмена.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1209, 'es-ES', 'Instruir a todo el personal sobre los procedimientos de emergencia basados en la FDS durante la charla TBM y publicar la información de riesgos en el lugar.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1209, 'ru-RU', 'На инструктаже TBM обучить весь персонал мерам экстренного реагирования на основе Паспорта безопасности и разместить информацию о вредных факторах на видном месте.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1210, 'es-ES', 'Utilizar todos los equipos de protección individual (EPI) recomendados en la FDS, como gafas de seguridad, ropa de protección y guantes resistentes a productos químicos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1210, 'ru-RU', 'Полностью использовать средства индивидуальной защиты (СИЗ) согласно рекомендациям Паспорта безопасности: защитные очки, защитную одежду, химстойкие перчатки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1211, 'es-ES', 'Antes de desmontar, identificar la ubicación de los soportes y puntos de fijación, y aplicar un sistema de control de acceso inferior y redes de protección contra caídas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1211, 'ru-RU', 'Перед демонтажом проверить расположение опор и точек крепления, установить ограждение для контроля доступа снизу и применить защитную сетку от падения предметов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1213, 'es-ES', 'Asegurar el uso de arneses con doble gancho de anclaje y cuerdas de seguridad para herramientas, y garantizar rutas de acceso y evacuación seguras.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1213, 'ru-RU', 'Обеспечить использование страховочной привязи с двумя стропами (усами самостраховки) и строп для инструмента, а также обеспечить безопасные пути доступа и эвакуации.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1108, 'es-ES', 'Verificar previamente el estado de los soportes y fijaciones de la estructura a desmontar y aplicar medidas anticaídas (cuerdas, soportes de sujeción).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1108, 'ru-RU', 'Предварительно проверить состояние опор и креплений демонтируемой конструкции и применить меры по предотвращению падения (страховочные канаты, подставки).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1239, 'es-ES', 'Inspeccionar el desgaste y los cortes de las eslingas textiles y cables de acero antes de iniciar el trabajo, y verificar que la carga real se ajusta a las especificaciones del fabricante (carga máxima de utilización - CMU).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1239, 'ru-RU', 'Перед началом работ проверить текстильные и стальные стропы на предмет износа и порезов и убедиться, что фактическая нагрузка соответствует спецификациям производителя (номинальной грузоподъемности).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1242, 'es-ES', 'Tras nivelar el terreno, instalar calzos de apoyo, extender completamente los estabilizadores (outriggers) y verificar la nivelación y verticalidad del equipo utilizando un nivel.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1242, 'ru-RU', 'После выравнивания грунта установить опорные подкладки, максимально выдвинуть аутригеры и проверить вертикальное положение с помощью уровня.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1243, 'es-ES', 'Elaborar un plan de trabajo para evitar interferencias con operaciones simultáneas cercanas y controlar la segregación de las rutas de circulación de otros equipos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1243, 'ru-RU', 'Разработать план производства работ (ППР) для предотвращения помех от смежных процессов и обеспечить разделение маршрутов движения другого оборудования.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1244, 'es-ES', 'Asignar un señalista, un ayudante de maniobra y un supervisor, unificando el sistema de comunicación mediante radios o señales gestuales estandarizadas (según UNE 58141-3).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1244, 'ru-RU', 'Назначить сигнальщика (стропальщика) и ответственного за производство работ, унифицировав систему связи с использованием радиостанций или стандартизированных знаковых сигналов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1249, 'es-ES', 'Interrumpir los trabajos inmediatamente si la velocidad de las ráfagas de viento supera el límite establecido, bajar la carga al suelo y asegurar el gancho de la grúa.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1249, 'ru-RU', 'При превышении предельно допустимой скорости ветра немедленно прекратить работу, опустить груз на землю и закрепить крюк крана.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1252, 'es-ES', 'Respetar la carga nominal de la carretilla elevadora, asegurar que el centro de gravedad de la carga esté centrado y conducir a baja velocidad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1252, 'ru-RU', 'Соблюдать номинальную грузоподъемность вилочного погрузчика, загружать груз так, чтобы его центр тяжести не был смещен, и передвигаться на низкой скорости.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1257, 'es-ES', 'Establecer un plan de segregación de rutas con otros equipos y mantener un sistema de comunicación en tiempo real (p. ej., radios) durante trabajos simultáneos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1257, 'ru-RU', 'Разработать план разделения маршрутов движения с другой техникой и поддерживать систему связи в реальном времени (например, по рации) при одновременной работе.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1323, 'es-ES', 'Controlar estrictamente el acceso de personal al radio de operación de la excavadora y asignar un señalista dedicado para unificar las señales gestuales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1323, 'ru-RU', 'Строго контролировать доступ персонала в рабочий радиус экскаватора и назначить выделенного сигнальщика для унификации ручных сигналов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1324, 'es-ES', 'Prohibir el acceso de trabajadores bajo la trayectoria del cazo (cuchara), colocar señales de advertencia de "Peligro: Caída de objetos" y mantener una distancia de seguridad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1324, 'ru-RU', 'Запретить нахождение работников под траекторией движения ковша, вывесить предупреждающие знаки "Осторожно, падение предметов!" и соблюдать безопасное расстояние.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1325, 'es-ES', 'Delimitar físicamente la zona de trabajo con cinta de balizamiento, conos y barreras para segregar los flujos de circulación de maquinaria y personal.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1325, 'ru-RU', 'Установить в рабочей зоне оградительную ленту, конусы и барьеры для физического разделения маршрутов движения техники и персонала.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1326, 'es-ES', 'Establecer una zona de exclusión cerca del borde de la excavación e inspeccionar previamente el estado del terreno para garantizar la capacidad portante para el equipo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1326, 'ru-RU', 'Установить запретную зону у края выемки и предварительно проверить состояние грунта для обеспечения несущей способности для техники.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1327, 'es-ES', 'Realizar una inspección diaria del equipo, incluyendo el sistema hidráulico, y al detener el trabajo, asegurar que el cazo esté apoyado en el suelo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1327, 'ru-RU', 'Ежедневно проверять состояние техники, включая гидравлическую систему, а при остановке работ обязательно опускать ковш на землю.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1328, 'es-ES', 'Instalar iluminación suficiente y luces estroboscópicas en el equipo, y proporcionar a los trabajadores EPI de alta visibilidad, como chalecos reflectantes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1328, 'ru-RU', 'Обеспечить достаточное освещение и установить на технике проблесковые маячки, а работников обеспечить СИЗ повышенной видимости, например, сигнальными жилетами.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1329, 'es-ES', 'Verificar el funcionamiento de la cámara de visión trasera y los sensores de proximidad, y el señalista debe realizar las señales siempre dentro del campo de visión del operador.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1329, 'ru-RU', 'Проверить исправность камеры заднего вида и датчиков обнаружения препятствий, а сигнальщик должен подавать сигналы, находясь в поле зрения машиниста.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1330, 'es-ES', 'Instruir sobre los procedimientos para trabajos simultáneos con maquinaria pesada mediante charlas de seguridad (Toolbox Talks) y cumplir el principio de operación a baja velocidad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1330, 'ru-RU', 'Проводить целевой инструктаж по процедурам одновременной работы тяжелой техники и соблюдать принцип управления оборудованием на низкой скорости.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1331, 'es-ES', 'Realizar y registrar una inspección diaria de los componentes clave (frenos, dirección, sistema hidráulico) antes de iniciar el trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1331, 'ru-RU', 'Перед началом работы проводить и регистрировать ежедневный осмотр основных узлов: тормозной системы, рулевого управления, гидравлических линий.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1332, 'es-ES', 'Al finalizar el trabajo, apagar el motor y retirar la llave de contacto de forma rigurosa, y reforzar el control de acceso de personal no autorizado a la zona de trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1332, 'ru-RU', 'После окончания работы тщательно выключать зажигание и извлекать ключ, а также усилить контроль доступа посторонних лиц в рабочую зону.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1333, 'es-ES', 'Verificar la nivelación y compactación del terreno en la ruta de desplazamiento y, en caso de terreno blando, reforzar con planchas de reparto de carga u otras medidas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1333, 'ru-RU', 'Проверять состояние выравнивания и уплотнения грунта на пути движения, а при проезде по слабому грунту принимать меры по его усилению (например, дорожными плитами).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1334, 'es-ES', 'Asignar previamente rutas de acceso para cada equipo y establecer un sistema de señales unificado para controlar las interferencias durante trabajos simultáneos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1334, 'ru-RU', 'Заранее определить маршруты подъезда для каждой единицы техники и создать единую систему сигналов для контроля помех при одновременной работе.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1335, 'es-ES', 'Asignar personal de control de acceso en la entrada de la obra e instalar señales de "Maquinaria pesada trabajando" para impedir el acceso de personal ajeno.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1335, 'ru-RU', 'Разместить на въезде на объект персонал для контроля доступа и установить знак "Работает тяжелая техника" для полного исключения доступа посторонних.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1336, 'es-ES', 'Respetar el talud de seguridad según el tipo de terreno y, si es necesario, instalar sistemas de entibación y verificar la estabilidad del talud.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1336, 'ru-RU', 'Соблюдать безопасную крутизну откосов в зависимости от состояния грунта и при необходимости устанавливать крепления стенок выемки и проверять их устойчивость.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1337, 'es-ES', 'Detectar la ubicación de servicios enterrados antes de excavar y, al exponerlos, tomar medidas de protección, combinando con excavación manual.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1337, 'ru-RU', 'Перед началом земляных работ определить местоположение подземных коммуникаций, а при их вскрытии принять меры защиты, в том числе с применением ручной копки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1338, 'es-ES', 'Inspeccionar regularmente el estado del suelo para eliminar aceites y agua, y utilizar bombas de achique para prevenir inundaciones y reblandecimiento del terreno.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1338, 'ru-RU', 'Регулярно проверять состояние пола для удаления масел и влаги и использовать дренажные насосы для предотвращения затопления и размягчения грунта.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1339, 'es-ES', 'Acopiar el material excavado en las zonas designadas para mantener las vías de paso despejadas y minimizar la carga sobre el borde de la excavación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1339, 'ru-RU', 'Складировать извлеченный грунт в отведенном месте для обеспечения свободных проходов и минимизации нагрузки на верхнюю часть откоса выемки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1340, 'es-ES', 'Al combinar con excavación manual, detener temporalmente la operación de la excavadora y realizar el trabajo por turnos bajo las indicaciones del señalista.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1340, 'ru-RU', 'При совмещении с ручной копкой временно остановить работу экскаватора и выполнять работы поочередно по указанию сигнальщика.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1357, 'es-ES', 'Elaborar un plan para segregar físicamente las rutas de circulación de la excavadora y el dumper, asignando vías de acceso específicas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1357, 'ru-RU', 'Разработать план физического разделения маршрутов движения экскаватора и самосвала и назначить конкретные пути подъезда.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1370, 'es-ES', 'Para la manipulación manual de cargas, priorizar el trabajo en equipos de dos personas o el uso de ayudas mecánicas (carretillas, polipastos).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1370, 'ru-RU', 'При ручном перемещении грузов отдавать предпочтение работе вдвоем или использованию механических приспособлений (тележки, тали).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1371, 'es-ES', 'Colocar los objetos más pesados en la parte inferior, verificar la nivelación del suelo e instalar calzos para prevenir el vuelco.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1371, 'ru-RU', 'Размещать тяжелые предметы внизу, проверять горизонтальность поверхности и устанавливать подпорки для предотвращения опрокидывания.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1372, 'es-ES', 'Delimitar la zona de exclusión inferior, colocar señales de advertencia de "Peligro: Caída de objetos" y asignar un señalista de forma permanente.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1372, 'ru-RU', 'Установить ограждение зоны под местом работ, вывесить предупреждающий знак "Осторожно, падение предметов!" и обеспечить постоянное присутствие наблюдающего.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1373, 'es-ES', 'Colocar protectores de goma o cantoneras en las aristas vivas de las cargas pesadas para prevenir daños en las eslingas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1373, 'ru-RU', 'На острые углы тяжелых грузов подкладывать резиновые прокладки или защитные уголки для предотвращения повреждения строп.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1374, 'es-ES', 'Al depositar cargas pesadas, asegurar un espacio para las manos y utilizar soportes (p. ej., palés) para prevenir atrapamientos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1374, 'ru-RU', 'При опускании тяжелых грузов оставлять пространство для рук и использовать опоры (например, паллеты) для предотвращения защемления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1375, 'es-ES', 'Antes del transporte, retirar los obstáculos del pasillo e inspeccionar el estado del suelo para garantizar una ruta de desplazamiento segura.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1375, 'ru-RU', 'Перед транспортировкой убрать препятствия с прохода и проверить состояние пола, чтобы обеспечить безопасный маршрут передвижения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1376, 'es-ES', 'Antes del trabajo, verificar el peso indicado en la carga y compararlo con la carga nominal del equipo de elevación durante la charla de seguridad (TBM).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1376, 'ru-RU', 'Перед началом работ проверить указанный на грузе вес и сопоставить его с номинальной грузоподъемностью подъемного оборудования в ходе инструктажа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1377, 'es-ES', 'Instalar iluminación adecuada y colocar señalización reflectante en las cargas pesadas y en la ruta de trabajo para mejorar la visibilidad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1377, 'ru-RU', 'Установить достаточное освещение и нанести светоотражающую маркировку на тяжелые грузы и маршрут работ для обеспечения видимости.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1378, 'es-ES', 'Si la velocidad de las ráfagas de viento supera el límite, detener inmediatamente el trabajo, depositar la carga en el suelo y asegurarla.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1378, 'ru-RU', 'При превышении предельно допустимой скорости ветра немедленно прекратить работу, опустить тяжелый груз на землю и закрепить его.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1379, 'es-ES', 'Inmediatamente después de finalizar el trabajo, recoger los materiales de sujeción y los calzos utilizados y mantener el orden y la limpieza en el lugar designado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1379, 'ru-RU', 'Сразу после окончания работ собрать использованные крепежные материалы и подпорки и навести порядок на отведенном месте.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1381, 'es-ES', 'Durante la elevación y el giro, operar lentamente y mantener una velocidad constante siguiendo las señales del señalista.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1381, 'ru-RU', 'При подъеме и повороте действовать плавно, поддерживая постоянную скорость в соответствии с сигналами сигнальщика.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1384, 'es-ES', 'Mantener un ángulo de eslingado adecuado para la forma de la carga y asegurarla de manera que el centro de gravedad quede centrado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1384, 'ru-RU', 'Поддерживать оптимальный угол строповки в соответствии с формой груза и закреплять его так, чтобы центр тяжести находился по центру.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1386, 'es-ES', 'Prohibir el apilamiento en terrenos blandos o inclinados; asegurar prioritariamente una superficie plana y firme.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1386, 'ru-RU', 'Запрещается складирование на слабом или наклонном грунте; в первую очередь необходимо обеспечить ровную и твердую поверхность.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1387, 'es-ES', 'Respetar los límites de altura de apilamiento y, si es necesario, sujetar con cuerdas o flejes para prevenir el colapso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1387, 'ru-RU', 'Соблюдать ограничения по высоте штабелирования и при необходимости закреплять груз веревками или лентами для предотвращения обрушения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1389, 'es-ES', 'En pendientes descendentes, controlar siempre la carretilla desde el frente y usar calzos o frenos si es necesario.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1389, 'ru-RU', 'На спуске всегда контролировать тележку спереди и при необходимости использовать тормозные башмаки или тормоз.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1390, 'es-ES', 'Mantener la carga por debajo de la altura de la cintura; si la visibilidad es limitada, asignar obligatoriamente un guía.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1390, 'ru-RU', 'Поддерживать груз на высоте не выше пояса; если видимость ограничена, обязательно назначить сопровождающего.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1391, 'es-ES', 'Antes del trabajo, verificar la anchura y altura de la ruta de transporte y, al pasar por zonas estrechas, proceder lentamente y con un guía.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1391, 'ru-RU', 'Перед началом работы проверить ширину и высоту транспортного пути, а при проезде через узкие места двигаться медленно и под руководством.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1394, 'es-ES', 'Las planchas de plomo para blindaje son cargas de alta densidad; fijarlas firmemente durante la instalación y manipularlas entre dos personas para prevenir su caída.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1394, 'ru-RU', 'Свинцовые пластины для экранирования являются грузом высокой плотности; при монтаже их следует надежно закреплять и перемещать вдвоем для предотвращения падения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1212, 'es-ES', 'Respetar la secuencia de desmontaje de la estructura y utilizar polipastos de cadena o puntales de apoyo para evitar el vuelco de los materiales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1212, 'ru-RU', 'Соблюдать последовательность демонтажа конструкций и использовать цепные тали или опоры для предотвращения опрокидывания материалов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1055, 'es-ES', 'Utilizar únicamente equipos con la inspección periódica vigente (etiqueta de apto/PASS) y verificar el correcto funcionamiento del interruptor diferencial.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1055, 'ru-RU', 'Использовать только оборудование, прошедшее периодическую проверку (с биркой о допуске), и проверять исправность устройства защитного отключения (УЗО).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1058, 'es-ES', 'Asegurar una ventilación adecuada en el lugar de trabajo y, en espacios confinados, utilizar ventilación forzada con equipos de extracción o soplado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1058, 'ru-RU', 'Обеспечить достаточную вентиляцию на рабочем месте, а при работах в замкнутом пространстве применять принудительную вентиляцию с помощью вентиляторов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1059, 'es-ES', 'El personal que realice trabajos en caliente debe usar obligatoriamente los EPI específicos, como ropa ignífuga, guantes de cuero y pantalla facial de protección.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1059, 'ru-RU', 'Работники, выполняющие огневые работы, обязаны использовать специальные СИЗ: огнестойкую одежду, кожаные перчатки, защитный лицевой щиток.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1060, 'es-ES', 'Verificar periódicamente el estado del dispositivo de protección contra contactos eléctricos del equipo de soldadura y confirmar la reducción de tensión en vacío.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1060, 'ru-RU', 'Регулярно проверять исправность устройства защиты от поражения электрическим током сварочного аппарата и убеждаться в снижении напряжения на холостом ходу.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1064, 'es-ES', 'Antes y después del trabajo, instalar mantas ignífugas o lonas incombustibles en un radio de 10 metros para contener las proyecciones de partículas incandescentes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1064, 'ru-RU', 'До и после работы в радиусе 10 метров установить огнезащитное полотно или негорючие экраны для защиты от разлетающихся искр.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1065, 'es-ES', 'Instalar bandejas o mantas ignífugas para la recogida de proyecciones bajo el emparrillado (grating) y controlar el acceso de los trabajadores en los niveles inferiores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1065, 'ru-RU', 'Установка огнезащитных пологов или поддонов для сбора искр под решётчатым настилом и ограничение доступа персонала на нижних ярусах.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1066, 'es-ES', 'Ajustar la altura de las pantallas de protección contra proyecciones según la dirección y velocidad del viento, y ampliar el área de vigilancia de incendios.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1066, 'ru-RU', 'Регулировка высоты защитных экранов от разлетающихся частиц с учётом направления и скорости ветра и расширение зоны контроля пожарной безопасности.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1179, 'es-ES', 'Retirar previamente los materiales inflamables del área de trabajo e instalar cubiertas ignífugas o mantas térmicas en los equipos que no se puedan mover.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1179, 'ru-RU', 'Предварительное удаление легковоспламеняющихся материалов из рабочей зоны и установка огнезащитных чехлов/теплоизоляционных матов на оборудование, которое невозможно переместить.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1180, 'es-ES', 'Cumplir el principio de trabajo en parejas, asignar un vigilante de forma permanente y asegurar los medios de comunicación de emergencia como radios.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1180, 'ru-RU', 'Соблюдение принципа работы в паре (не менее двух человек), постоянное присутствие наблюдающего и обеспечение средствами экстренной связи (например, рациями).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1181, 'es-ES', 'Instalar pantallas o lonas incombustibles en la zona de generación de proyecciones y aislar completamente los equipos adyacentes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1181, 'ru-RU', 'Установка экранов или пологов из негорючих материалов в зоне разлёта искр и полная изоляция смежного оборудования.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1182, 'es-ES', 'Enfriar previamente las zonas con riesgo de contacto con altas temperaturas o utilizar Equipos de Protección Individual (EPI) como ropa ignífuga, guantes de cuero y delantal de protección térmica.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1182, 'ru-RU', 'Предварительное охлаждение участков, где возможен контакт с высокими температурами, или применение СИЗ, таких как огнестойкая спецодежда, кожаные перчатки и термозащитный фартук.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1183, 'es-ES', 'Realizar la medición de la concentración de gases antes de iniciar el trabajo y asegurar una ventilación continua mediante el uso de ventiladores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1183, 'ru-RU', 'Проведение замеров концентрации газов перед началом работ и обеспечение постоянной вентиляции путём включения вентиляторов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1184, 'es-ES', 'Tras finalizar el trabajo, el vigilante de incendios debe permanecer en el puesto durante al menos 30 minutos para verificar la ausencia de brasas o combustión latente.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1184, 'ru-RU', 'После завершения работ наблюдающий за пожарной безопасностью должен оставаться на месте не менее 30 минут для окончательной проверки на наличие остаточных искр и признаков тления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1186, 'es-ES', 'Antes de trabajar, verificar la estanqueidad de las conexiones de las mangueras y el estado de instalación de los dispositivos antirretorno de llama.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1186, 'ru-RU', 'Перед началом работ проверить герметичность соединений шлангов и исправность установки предохранительных затворов (огнепреградителей).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1187, 'es-ES', 'Disponer de al menos dos extintores adecuados en un radio de 5 metros del punto de trabajo y asignar un vigilante de incendios dedicado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1187, 'ru-RU', 'Разместить не менее двух подходящих огнетушителей в радиусе 5 метров от места проведения работ и назначить специального наблюдающего за пожарной безопасностью.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1188, 'es-ES', 'Realizar una charla de seguridad (Toolbox Talk) para informar sobre los riesgos del área de trabajo y mantener en el lugar el Permiso de Trabajo en Caliente (PTC) debidamente autorizado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1188, 'ru-RU', 'Провести инструктаж на рабочем месте (Toolbox Meeting) для разъяснения опасностей в рабочей зоне и обеспечить наличие на месте утверждённого наряда-допуска на проведение огневых работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1189, 'es-ES', 'Utilizar pantalla de soldador y gafas de seguridad, y mantener en funcionamiento continuo el sistema de extracción localizada o ventiladores para evacuar los humos de soldadura.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1189, 'ru-RU', 'Использовать сварочную маску и защитные очки, а также обеспечить постоянную работу местной вытяжной вентиляции/вентиляторов для удаления сварочных дымов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1190, 'es-ES', 'Verificar el estado del aislamiento del equipo de soldadura eléctrica, instalar la conexión a tierra y comprobar previamente el funcionamiento del interruptor diferencial.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1190, 'ru-RU', 'Проверить состояние изоляции электросварочного аппарата, установить заземляющий провод и предварительно проверить срабатывание устройства защитного отключения (УЗО).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1191, 'es-ES', 'Verificar que el protector de seguridad de la amoladora esté instalado y asegurar el uso estricto de pantalla facial y EPI ignífugos por parte del trabajador.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1191, 'ru-RU', 'Проверить наличие защитного кожуха на шлифовальной машине и обеспечить строгое применение работником защитного лицевого щитка и огнестойких СИЗ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1192, 'es-ES', 'Inspeccionar periódicamente el estado del aislamiento de los cables antes de su uso y verificar la protección contra sobrecargas de los enrollacables de uso industrial.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1192, 'ru-RU', 'Перед использованием регулярно проверять состояние изоляции кабелей и контролировать защиту от перегрузки промышленных удлинителей на катушках.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1193, 'es-ES', 'Retirar los materiales combustibles en la dirección del corte, instalar pantallas de protección contra proyecciones y verificar el enfriamiento del material cortado después del trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1193, 'ru-RU', 'Удалить горючие материалы по направлению резки, установить защитные экраны от искр и после окончания работ убедиться в охлаждении отрезанного материала.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1194, 'es-ES', 'Verificar la fijación de la máquina de corte, no aplicar una presión excesiva y realizar el trabajo posicionándose a un lado del equipo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1194, 'ru-RU', 'Проверить надёжность крепления отрезной машины, избегать чрезмерного нажима и выполнять работу, находясь сбоку от оборудования.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1275, 'es-ES', 'En trabajos nocturnos o antes de finalizar la jornada, realizar una inspección final alrededor de los equipos de llama abierta y fuentes de calor para verificar que no queden brasas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1275, 'ru-RU', 'При работе в ночное время или перед уходом с рабочего места провести финальную проверку зон вблизи источников огня и тепла на предмет отсутствия тлеющих углей.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1185, 'es-ES', 'Instalar una línea de control de acceso en el nivel inferior, colocar mantas o bandejas ignífugas para la recogida de proyecciones y volver a verificar la ausencia de materiales combustibles debajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1185, 'ru-RU', 'Установить ограждение для ограничения доступа на нижнем уровне, разместить огнезащитный полог для сбора искр и повторно проверить отсутствие горючих материалов внизу.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2001, 'es-ES', 'Limitar estrictamente la altura de la carga a un nivel que no obstruya la visibilidad del conductor.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2001, 'ru-RU', 'Строго ограничивать высоту загружаемого груза, чтобы она не превышала уровень, обеспечивающий достаточный обзор для водителя.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2002, 'es-ES', 'Si la visibilidad frontal es limitada, operar siempre en equipo de dos personas, con un señalista para dirigir el movimiento del vehículo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2002, 'ru-RU', 'При недостаточной передней видимости обязательно работать в паре с сигнальщиком, который должен руководить движением.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2003, 'es-ES', 'Al aproximarse a puntos ciegos o intersecciones, detenerse momentáneamente y usar la bocina para advertir a los peatones.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2003, 'ru-RU', 'При въезде в слепые зоны и на перекрёстки остановиться, подать звуковой сигнал для предупреждения пешеходов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1001, 'es-ES', 'Antes de iniciar la jornada, realizar una charla de seguridad (TBM) para instruir sobre los riesgos clave del día y las reglas básicas de seguridad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1001, 'ru-RU', 'Перед началом смены провести инструктаж (TBM) для ознакомления с ключевыми рисками предстоящих работ и основными правилами безопасности.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1002, 'es-ES', 'Disponer de los Procedimientos Normalizados de Trabajo (PNT/SOP) para cada tarea en el área de trabajo y verificar verbalmente que cada trabajador los comprende.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (1002, 'ru-RU', 'Обеспечить наличие стандартных операционных процедур (СОП) для каждого процесса в рабочей зоне и устно проверить их знание каждым работником.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2021, 'es-ES', 'Asignar rutas de tránsito específicas para los trabajadores y comunicar las zonas de riesgo de cada proceso durante la charla de seguridad (TBM).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2021, 'ru-RU', 'Определить индивидуальные маршруты передвижения для работников и в ходе инструктажа (TBM) информировать о взаимном расположении опасных зон различных процессов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2022, 'es-ES', 'Para trabajos nocturnos o con poca luz, instalar luces estroboscópicas LED y señalización reflectante de alta visibilidad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2022, 'ru-RU', 'При работе в ночное время или в условиях недостаточной освещённости установить светодиодные проблесковые маячки и светоотражающие знаки высокой видимости.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2023, 'es-ES', 'Separar físicamente las vías de circulación de maquinaria pesada de los pasillos peatonales y asignar señalistas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2023, 'ru-RU', 'Обеспечить физическое разделение путей движения тяжёлой техники и пешеходных дорожек и выставить сигнальщиков.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2024, 'es-ES', 'Realizar una inspección completa de la señalización de seguridad normalizada en todas las zonas de riesgo y reemplazar de inmediato las señales deterioradas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2024, 'ru-RU', 'Провести полную инвентаризацию стандартизированных знаков безопасности в опасных зонах и немедленно заменять устаревшие или повреждённые знаки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2025, 'es-ES', 'Aplicar pintura fotoluminiscente en las señales de rutas de evacuación para asegurar su visibilidad y colocar planos del sitio.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2025, 'ru-RU', 'Для обеспечения видимости знаков эвакуационных путей использовать фотолюминесцентную краску и разместить на видном месте схемы эвакуации.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2026, 'es-ES', 'Gestionar la colocación conjunta de etiquetas de peligro (Red Tag) y señales de identificación en equipos de alto riesgo y puntos de aislamiento de energía.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2026, 'ru-RU', 'На высокоопасном оборудовании и в точках отключения энергии применять и контролировать совместное использование запрещающих бирок (Red Tag) и идентификационных знаков.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2027, 'es-ES', 'Inspeccionar regularmente el estado del suelo para eliminar derrames de aceite o agua de inmediato, y disponer de herramientas de limpieza específicas con material absorbente.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2027, 'ru-RU', 'Регулярно проверять состояние полов для немедленного устранения разливов масла или воды, обеспечить наличие специальных чистящих средств и сорбирующих материалов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2028, 'es-ES', 'Instalar alfombrillas antideslizantes en zonas húmedas o con presencia de aceites y proporcionar calzado de seguridad específico a los trabajadores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2028, 'ru-RU', 'В сырых и замасленных зонах уложить специальные противоскользящие коврики и выдать работникам соответствующую защитную обувь.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2029, 'es-ES', 'En caso de lluvia, instalar barreras impermeables para prevenir la entrada de agua y revisar periódicamente el funcionamiento de las bombas de achique.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2029, 'ru-RU', 'Во время дождя устанавливать водонепроницаемые барьеры для предотвращения попадания воды и регулярно проверять работоспособность дренажных насосов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2030, 'es-ES', 'Colocar avisos que prohíban el almacenamiento de materiales en las vías de paso y establecer un procedimiento para su retirada inmediata en caso de incumplimiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2030, 'ru-RU', 'Разместить объявления о запрете складирования материалов на проходах и внедрить процедуру немедленного удаления обнаруженных препятствий.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2031, 'es-ES', 'Establecer áreas de almacenamiento designadas (Yard) para cada tipo de material y delimitar claramente las zonas con marcas en el suelo para mantener el orden.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2031, 'ru-RU', 'Определить специальные зоны хранения (складские площадки) для различных материалов и чётко разграничить их с помощью разметки на полу для поддержания порядка.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2032, 'es-ES', 'Establecer 5 minutos obligatorios para la limpieza del área de trabajo antes de finalizar la jornada, revisando que no queden herramientas en pasillos y escaleras.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2032, 'ru-RU', 'Ввести обязательные 5 минут на уборку рабочего места перед окончанием смены для проверки проходов и лестниц на наличие оставленных инструментов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2033, 'es-ES', 'Antes de trabajos eléctricos, confirmar la desconexión de la alimentación según los planos y medir la tensión residual con un detector de tensión sin contacto.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2033, 'ru-RU', 'Перед электромонтажными работами убедиться в отключении питания согласно схемам и измерить остаточное напряжение с помощью бесконтактного указателя напряжения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2034, 'es-ES', 'Tras la desconexión, descargar completamente la energía residual de la línea utilizando pértigas de puesta a tierra o dispositivos de descarga específicos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2034, 'ru-RU', 'После отключения напряжения полностью разрядить остаточную энергию в линии с помощью специальной заземляющей штанги или разрядного устройства.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2035, 'es-ES', 'Realizar una comprobación final del uso correcto de los EPI obligatorios, como guantes dieléctricos y calzado de seguridad no conductor.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2035, 'ru-RU', 'Провести финальную проверку правильного использования обязательных СИЗ, включая диэлектрические перчатки и непроводящую защитную обувь.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2036, 'es-ES', 'Durante el mantenimiento de equipos rotativos o alternativos, instalar dispositivos de bloqueo mecánico como pasadores de seguridad (lock-pins) o cadenas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2036, 'ru-RU', 'При обслуживании вращающихся и возвратно-поступательных механизмов устанавливать механические фиксаторы, такие как стопорные штифты (Lock-pin) и цепи.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2037, 'es-ES', 'Aplicar dispositivos de bloqueo físico (candados) en válvulas y actuadores para prevenir su accionamiento accidental.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2037, 'ru-RU', 'Применять механические блокирующие устройства (навесные замки) на клапанах и приводах для предотвращения их случайного срабатывания.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2038, 'es-ES', 'Para retirar un dispositivo de consignación de energía, seguir estrictamente el procedimiento de aprobación cruzada entre el supervisor y el trabajador designado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2038, 'ru-RU', 'При снятии блокировки с источника энергии строго соблюдать процедуру перекрёстного согласования между руководителем работ и назначенным работником.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2039, 'es-ES', 'Tras cortar la alimentación, instalar el dispositivo de consignación (LOTO) y colocar una etiqueta de ''No operar'' (Red Tag) en el punto de seccionamiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2039, 'ru-RU', 'После отключения питания установить блокировочное устройство (LOTO) и вывесить на месте отключения запрещающий плакат ''Не включать! Работают люди''.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2040, 'es-ES', 'Antes de restablecer la alimentación, verificar visualmente que todo el personal ha abandonado la zona de trabajo y realizar una inspección de seguridad final.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2040, 'ru-RU', 'Перед восстановлением подачи энергии визуально убедиться, что весь персонал покинул рабочую зону, и провести окончательную проверку безопасности.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2041, 'es-ES', 'En trabajos con múltiples personas, cada una debe usar su propio candado personal y mantener un registro con los números de identificación de los trabajadores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2041, 'ru-RU', 'При выполнении работ несколькими сотрудниками использовать индивидуальные замки и вести журнал учёта с идентификационными номерами работников.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2042, 'es-ES', 'Verificar el uso de los EPI obligatorios para alta tensión, como guantes dieléctricos, pantalla facial y herramientas aislantes no conductoras.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2042, 'ru-RU', 'Проверить применение обязательных СИЗ для работ под высоким напряжением, таких как диэлектрические перчатки, защитный лицевой щиток и изолированный инструмент.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2043, 'es-ES', 'Antes de trabajar, realizar una puesta a tierra y en cortocircuito segura de la línea utilizando equipos de puesta a tierra específicos con pinzas adecuadas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2043, 'ru-RU', 'Перед началом работ выполнить надёжное закорачивание и заземление линии с использованием специального переносного заземления с зажимами.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2044, 'es-ES', 'Instalar señales de advertencia de riesgo eléctrico y colocar cubiertas aislantes para proteger contra el contacto con partes activas expuestas en el área de trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2044, 'ru-RU', 'Установить предупреждающие знаки об опасности поражения электрическим током и установить изолирующие накладки для защиты от прикосновения к открытым токоведущим частям в рабочей зоне.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2045, 'es-ES', 'Durante la charla de seguridad (TBM), compartir claramente la información sobre el tipo de energía, los puntos de aislamiento y los equipos a consignar (LOTO), basándose en los planos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2045, 'ru-RU', 'Во время инструктажа (TBM) чётко довести до сведения персонала информацию о типе источника энергии, точках отключения и оборудовании, подлежащем блокировке (LOTO), на основе схем.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2046, 'es-ES', 'Colocar dispositivos de bloqueo y etiquetas con un número de identificación único en todas las fuentes de energía aisladas (eléctrica, gas, fluidos).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2046, 'ru-RU', 'На все изолированные источники энергии (электричество, газ, жидкости) установить блокировочные устройства и бирки с индивидуальными идентификационными номерами.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2047, 'es-ES', 'Antes de iniciar el trabajo, el supervisor de área y el operario deben verificar y aprobar conjuntamente el estado de la instalación del sistema de consignación y etiquetado (LOTO) directamente en el punto de intervención.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2047, 'ru-RU', 'Перед началом работ руководитель работ и исполнитель совместно проводят перекрестную проверку и утверждают на месте состояние установленной системы блокировки и маркировки (LOTO).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2048, 'es-ES', 'Antes de realizar trabajos en caliente, efectuar una purga completa con gas inerte de los gases residuales en tuberías y recipientes, y posteriormente realizar una medición precisa de la atmósfera para verificar que se encuentra por debajo del límite inferior de inflamabilidad (LII).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2048, 'ru-RU', 'Перед проведением огневых работ выполнить полную продувку трубопроводов и емкостей от остаточных газов, после чего провести точный замер концентрации для контроля воздушной среды.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2049, 'es-ES', 'Si los resultados de la medición superan el límite de exposición profesional (LEP), detener inmediatamente los trabajos y activar la ventilación forzada mediante extractores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2049, 'ru-RU', 'В случае превышения предельно допустимой концентрации (ПДК) по результатам замеров, немедленно прекратить работы и включить принудительную вентиляцию с помощью вытяжных вентиляторов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2050, 'es-ES', 'Cada operario debe portar un detector de gases múltiples portátil personal y monitorizar de forma continua los niveles de concentración en tiempo real.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2050, 'ru-RU', 'Обеспечить каждого работника индивидуальным портативным многокомпонентным газоанализатором и осуществлять постоянный мониторинг показаний концентрации в режиме реального времени.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2066, 'es-ES', 'Antes de los trabajos en caliente, realizar una inspección periódica de la puesta a tierra de la carcasa del equipo de soldadura y del estado del aislamiento de los cables.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2066, 'ru-RU', 'Перед огневыми работами проводить регулярную проверку состояния заземления корпуса сварочного аппарата и целостности изоляционной оболочки кабелей.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2067, 'es-ES', 'Verificar previamente cualquier fuga de gas en las conexiones del soplete y las mangueras utilizando agua jabonosa o un detector específico.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2067, 'ru-RU', 'Предварительно проверять места соединений горелки и шлангов на предмет утечки газа с помощью мыльного раствора или специального детектора.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2068, 'es-ES', 'Confirmar la presencia de la etiqueta de inspección favorable (Etiqueta Verde/Pass Tag) y bloquear el acceso al área de trabajo de equipos no autorizados.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2068, 'ru-RU', 'Проверить наличие бирки о прохождении проверки оборудования (Pass Tag) и запретить ввоз на рабочую площадку оборудования без допуска.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2069, 'es-ES', 'Al interrumpir o finalizar el trabajo, cerrar la válvula principal del soplete y confirmar que el equipo de soldadura está desconectado de la fuente de alimentación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2069, 'ru-RU', 'При перерыве или окончании работы проверить, что главный вентиль горелки перекрыт, а сварочный аппарат отключен от источника питания.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2070, 'es-ES', 'Las botellas de gas que no estén en uso deben ser trasladadas inmediatamente a una zona de almacenamiento designada y segura, con el capuchón de protección de la válvula colocado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2070, 'ru-RU', 'Неиспользуемые газовые баллоны немедленно перемещать в специально отведенное безопасное место хранения, предварительно надев защитные колпаки на вентили.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2071, 'es-ES', 'Mantener el área de trabajos en caliente constantemente ordenada, retirando materiales combustibles innecesarios y residuos de hidrocarburos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2071, 'ru-RU', 'Постоянно поддерживать порядок в зоне огневых работ, убирая ненужные горючие материалы и остатки горюче-смазочных материалов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2072, 'es-ES', 'Al soldar en lugares húmedos, verificar la instalación de alfombras aislantes y el uso de botas de seguridad dieléctricas por parte del operario.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2072, 'ru-RU', 'При выполнении сварочных работ во влажных местах проверить наличие диэлектрических ковриков и использование работниками диэлектрических сапог.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2073, 'es-ES', 'Verificar la sensibilidad nominal y el correcto funcionamiento del interruptor diferencial (ID) en el cuadro eléctrico provisional mediante el botón de prueba antes de comenzar los trabajos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2073, 'ru-RU', 'Перед началом работ проверить номинальную чувствительность и работоспособность устройства защитного отключения (УЗО) во временном распределительном щите с помощью кнопки «Тест».', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2074, 'es-ES', 'Realizar una inspección completa de la estructura de doble aislamiento (Clase II) y de la conexión a tierra de las carcasas de herramientas eléctricas y equipos de soldadura.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2074, 'ru-RU', 'Провести полную проверку наличия двойной изоляции на корпусах электроинструментов и сварочных аппаратов, а также состояние подключения заземляющих проводников.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2075, 'es-ES', 'Instalar un sistema de extracción localizada móvil en el punto de soldadura y colocar la campana de aspiración lo más cerca posible de la fuente de humos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2075, 'ru-RU', 'Установить передвижную местную вытяжную вентиляцию в точке сварки и расположить вытяжной зонт максимально близко к источнику выделения вредных веществ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2076, 'es-ES', 'Al soldar en espacios confinados, proporcionar ventilación forzada con soplantes y medir las concentraciones de oxígeno y gases tóxicos antes y durante el trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2076, 'ru-RU', 'При сварке в замкнутых пространствах обеспечить принудительную вентиляцию с помощью нагнетательных вентиляторов и измерять концентрацию кислорода и вредных газов до и во время работы.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2077, 'es-ES', 'Suministrar a cada operario un equipo de respiración con suministro de aire o una mascarilla con filtros adecuados, y verificar el cumplimiento de los plazos de sustitución de los filtros.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2077, 'ru-RU', 'Выдать каждому работнику индивидуальный шланговый или фильтрующий противогаз и контролировать соблюдение графика замены фильтрующих элементов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2078, 'es-ES', 'Inspeccionar el uso obligatorio por parte de los operarios de trabajos en caliente de ropa de protección ignífuga, delantal de cuero, manguitos de cuero y pantalla facial de soldador.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2078, 'ru-RU', 'Проверить обязательное использование работниками, выполняющими огневые работы, огнестойкой спецодежды, кожаного фартука, кожаных нарукавников и защитного лицевого щитка.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2079, 'es-ES', 'Verificar la robustez y correcta instalación de las mantas ignífugas y pantallas de soldadura para evitar la dispersión de proyecciones incandescentes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2079, 'ru-RU', 'Проверить прочность установки огнезащитных полотен и негорючих экранов для предотвращения разлета сварочных брызг.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2080, 'es-ES', 'Instalar señalización de advertencia sobre riesgo de quemaduras por contacto con material cortado a alta temperatura y controlar el acceso a la zona de trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2080, 'ru-RU', 'Установить предупреждающие знаки об опасности контактных ожогов от горячих отрезанных частей или заготовок и контролировать доступ в рабочую зону.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2081, 'es-ES', 'Inspeccionar el funcionamiento del dispositivo de reducción de tensión en vacío (VRD) integrado en el equipo de soldadura y medir la tensión en circuito abierto.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2081, 'ru-RU', 'Проверить работоспособность встроенного в сварочный аппарат автоматического устройства защиты от поражения током и измерить напряжение холостого хода.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2082, 'es-ES', 'Verificar el estado del aislamiento de los cables portaelectrodos y de masa, así como el apriete de sus conexiones.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2082, 'ru-RU', 'Проверить целостность изоляционной оболочки кабеля электрододержателя и обратного провода, а также надежность затяжки соединений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2083, 'es-ES', 'Al trabajar en lugares húmedos y con alta conductividad, instalar alfombras aislantes y asegurar el uso de equipos de protección individual dieléctricos por parte del operario.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2083, 'ru-RU', 'При работе в особо опасных влажных помещениях с высокой проводимостью установить диэлектрические коврики и обеспечить использование работниками специальных диэлектрических СИЗ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2084, 'es-ES', 'Antes de los trabajos en caliente, retirar y limpiar completamente todos los materiales combustibles (hidrocarburos, gases, residuos, etc.) en un radio de 10 metros.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2084, 'ru-RU', 'Перед началом огневых работ полностью удалить и очистить все горючие материалы (масла, газы, отходы и т.д.) в радиусе 10 метров.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2085, 'es-ES', 'Verificar el estado de la purga y limpieza para la eliminación completa de vapores inflamables del interior de tuberías y recipientes, utilizando gases inertes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2085, 'ru-RU', 'Проверить состояние инертизации и очистки для полного удаления паров горючих веществ из трубопроводов и емкостей с помощью инертных газов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2086, 'es-ES', 'Antes y después del trabajo, utilizar un medidor de gases inflamables para verificar que la concentración se mantiene por debajo del límite inferior de explosividad (LIE).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2086, 'ru-RU', 'До и после работы с помощью газоанализатора проверить, что концентрация горючих газов находится в пределах нижнего концентрационного предела распространения пламени (НКПР).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2087, 'es-ES', 'Inspeccionar fugas en las conexiones de las mangueras de gas y verificar la correcta instalación de los dispositivos antirretroceso de llama en las botellas de oxígeno y acetileno.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2087, 'ru-RU', 'Проверить на герметичность соединения газовых шлангов и убедиться в наличии огнепреградительных клапанов на кислородных и ацетиленовых баллонах.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2088, 'es-ES', 'Utilizar carros portabotellas específicos para evitar su vuelco y protegerlas de la exposición directa a la luz solar.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2088, 'ru-RU', 'Использовать специальные тележки для предотвращения падения газовых баллонов и принимать меры для защиты от прямого воздействия солнечных лучей.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2089, 'es-ES', 'Al interrumpir el trabajo, seguir el procedimiento de cerrar completamente las válvulas de las botellas y purgar el gas residual de las mangueras.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2089, 'ru-RU', 'Соблюдать процедуру полного закрытия вентилей баллонов и выпуска остаточного газа из шлангов при перерывах в работе.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2090, 'es-ES', 'Cubrir herméticamente con lonas ignífugas o mantas ignífugas los equipos y estructuras combustibles que no puedan ser retirados.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2090, 'ru-RU', 'Горючее оборудование и конструкции, которые невозможно переместить, плотно укрыть негорючими полотнами или огнезащитными покрывалами.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2091, 'es-ES', 'Instalar pantallas o barreras cortafuegos provisionales entre la zona de trabajos en caliente y las áreas adyacentes para prevenir la dispersión de proyecciones incandescentes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2091, 'ru-RU', 'Установить защитные экраны или временные противопожарные перегородки между зоной огневых работ и смежными участками для предотвращения разлета искр.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2092, 'es-ES', 'Asegurar la presencia de un vigilante de incendios durante al menos 30 minutos después de finalizar el trabajo para detectar cualquier posible combustión sin llama (brasas).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2092, 'ru-RU', 'Обеспечить присутствие наблюдающего за пожарной безопасностью в течение не менее 30 минут после завершения работ для контроля на предмет возможного тления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2093, 'es-ES', 'Instalar bandejas de recogida de proyecciones debajo del punto de soldadura o corte y llenarlas de agua para un enfriamiento inmediato.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2093, 'ru-RU', 'Установить поддоны для сбора искр под местом сварки и резки и наполнить их водой для немедленного охлаждения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2094, 'es-ES', 'Al trabajar sobre emparrillados metálicos (grating) o aberturas, asignar un vigilante de incendios adicional en el nivel inferior y controlar el acceso a dicha área.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2094, 'ru-RU', 'При работе на решетчатых настилах (Grating) и над проемами выставить дополнительного наблюдающего за пожарной безопасностью на нижнем ярусе и контролировать доступ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2095, 'es-ES', 'Prohibir los trabajos en caliente en exteriores en condiciones de viento fuerte e instalar o reforzar pantallas cortavientos para prevenir la propagación de proyecciones.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2095, 'ru-RU', 'Запретить наружные огневые работы при сильном ветре и установить усиленные ветрозащитные экраны для предотвращения распространения искр.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2096, 'es-ES', 'Instalar bandejas colectoras de proyecciones o mantas ignífugas sin huecos debajo de los emparrillados metálicos (grating) y aberturas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2096, 'ru-RU', 'Установить под решетчатыми настилами (Grating) и проемами сплошные поддоны для сбора искр или огнезащитные полотна без зазоров.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2097, 'es-ES', 'Establecer una zona de exclusión para el personal en el nivel inferior y asignar un vigilante de incendios adicional y dedicado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2097, 'ru-RU', 'Установить ограждение для контроля доступа персонала на нижнем ярусе и назначить дополнительного, специально выделенного наблюдающего за пожарной безопасностью.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2098, 'es-ES', 'Rociar con agua y mantener húmedos los equipos combustibles fijos situados en la zona inferior.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2098, 'ru-RU', 'Производить орошение водой и поддерживать во влажном состоянии стационарное горючее оборудование в нижней зоне.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2099, 'es-ES', 'Ampliar la altura y la anchura de las pantallas de protección contra proyecciones más allá de los requisitos mínimos legales, teniendo en cuenta la dirección y la velocidad del viento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2099, 'ru-RU', 'Увеличить высоту и ширину искрозащитных экранов сверх установленных нормативами размеров с учетом направления и скорости ветра.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2100, 'es-ES', 'Instalar detectores de incendios o espejos convexos en puntos ciegos que queden fuera del campo de visión del vigilante de incendios.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2100, 'ru-RU', 'Установить пожарные извещатели или обзорные зеркала в слепых зонах, находящихся вне поля зрения наблюдающего за пожарной безопасностью.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2101, 'es-ES', 'Antes de iniciar el trabajo, realizar una inspección exhaustiva de posibles materiales combustibles ocultos (p. ej., dentro de paredes) dentro del radio de dispersión previsto.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2101, 'ru-RU', 'Перед началом работ провести тщательную проверку на наличие скрытых горючих материалов (например, внутри стен) в пределах предполагаемого радиуса разлета искр.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2102, 'es-ES', 'Hacer obligatorio el uso de ropa de trabajo ignífuga para todo el personal en la zona de trabajos en caliente y verificar su cumplimiento por parte del supervisor.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2102, 'ru-RU', 'Ввести обязательное ношение спецодежды из огнестойких материалов для всего персонала в зоне огневых работ с проверкой со стороны руководителя.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2103, 'es-ES', 'Controlar estrictamente el acceso a la zona de trabajos en caliente de cualquier persona que vista ropa de trabajo convencional (p. ej., nailon u otros materiales inflamables).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2103, 'ru-RU', 'Строго контролировать доступ в зону огневых работ лиц, носящих обычную рабочую одежду (из нейлона и других горючих материалов).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2104, 'es-ES', 'Verificar que, además de la ropa ignífuga, se utilicen equipos de protección adicionales como delantales y manguitos de cuero.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2104, 'ru-RU', 'Проверить использование дополнительных средств защиты, таких как кожаные фартуки и нарукавники, в сочетании с огнестойкой одеждой.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2105, 'es-ES', 'Realizar una inspección completa de la ropa ignífuga y los guantes de cuero antes del trabajo para detectar cualquier daño físico, como contaminación por aceite o desgarros.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2105, 'ru-RU', 'Перед началом работы провести полную проверку огнестойкой одежды и кожаных перчаток на предмет физических повреждений, таких как загрязнение маслом или разрывы.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2106, 'es-ES', 'Mantener un registro del cumplimiento de los ciclos de lavado y la vida útil recomendados por el fabricante para cada equipo de protección.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2106, 'ru-RU', 'Вести учет соблюдения рекомендованного производителем количества стирок и срока службы для каждого средства защиты.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2107, 'es-ES', 'Si se detecta un EPI con posible pérdida de rendimiento, sustituirlo inmediatamente por uno nuevo y desechar el defectuoso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2107, 'ru-RU', 'При обнаружении средств защиты с подозрением на снижение эффективности, немедленно заменять их новыми, а неисправные утилизировать.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2108, 'es-ES', 'Realizar una comprobación mutua del uso correcto del equipo, como asegurarse de que las cremalleras de la ropa ignífuga y los puños de las mangas estén completamente cerrados.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2108, 'ru-RU', 'Проводить взаимную проверку правильности ношения СИЗ, например, полностью ли застегнуты молнии и манжеты на огнестойкой одежде.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2109, 'es-ES', 'Verificar el uso de guantes de cuero de caña larga para evitar huecos entre el guante y la manga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2109, 'ru-RU', 'Проверить использование кожаных перчаток с длинными крагами для предотвращения зазоров между перчаткой и рукавом.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2110, 'es-ES', 'Durante la charla de seguridad (Toolbox Talk), realizar formaciones prácticas y demostraciones sobre el uso de EPIs para corregir hábitos de uso inadecuados.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2110, 'ru-RU', 'Во время инструктажа перед началом работы проводить практические занятия и демонстрации по использованию СИЗ для исправления неправильных привычек ношения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2111, 'es-ES', 'Antes de iniciar el trabajo, durante la charla de seguridad, verificar exhaustivamente el estado del trabajador, incluyendo pruebas de alcoholemia, toma de tensión arterial y evaluación de su estado físico general.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2111, 'ru-RU', 'Перед началом работ во время инструктажа тщательно проверять состояние работника, включая проверку на употребление алкоголя, измерение артериального давления и оценку общего самочувствия.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2112, 'es-ES', 'Restringir la asignación de trabajos en altura a operarios con patologías previas (vigilancia de la salud) como hipertensión o vértigo, y reasignarlos a tareas a nivel del suelo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2112, 'ru-RU', 'Ограничить допуск к работам на высоте для работников, имеющих фоновые заболевания, такие как гипертония или головокружение, и перевести их на наземные работы.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2113, 'es-ES', 'Establecer pausas periódicas durante la jornada y activar un sistema de supervisión mutua del estado de salud entre compañeros.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2113, 'ru-RU', 'Предоставлять периодические перерывы в работе и внедрить систему взаимного контроля за состоянием здоровья между коллегами.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2114, 'es-ES', 'Interrumpir de inmediato los trabajos en altura y ejecutar los procedimientos de evacuación en caso de condiciones meteorológicas adversas como vientos fuertes (superiores a 10 m/s), lluvia intensa o nevada.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2114, 'ru-RU', 'Немедленно прекращать работы на высоте при ухудшении погодных условий, таких как сильный ветер (более 10 м/с), сильный дождь или снегопад, и выполнять процедуры эвакуации.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2115, 'es-ES', 'Monitorizar en tiempo real el pronóstico meteorológico para reajustar con antelación la secuencia de procesos, priorizando los trabajos a nivel del suelo ante la previsión de mal tiempo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2115, 'ru-RU', 'Отслеживать прогнозы погоды в режиме реального времени и при ожидании неблагоприятных погодных условий заблаговременно корректировать последовательность работ, отдавая приоритет наземным операциям.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2116, 'es-ES', 'Antes de reanudar el trabajo, inspeccionar minuciosamente los andamios y plataformas de trabajo para detectar formación de hielo, superficies resbaladizas o deformaciones estructurales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2116, 'ru-RU', 'Перед возобновлением работ проводить тщательную проверку строительных лесов и рабочих настилов на предмет обледенения, скользких поверхностей и деформации конструкций.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2117, 'es-ES', 'Instalar cintas de balizamiento, conos de seguridad y señalización de prohibido el paso para delimitar la zona bajo el punto de trabajo en altura.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2117, 'ru-RU', 'Устанавливать под зоной проведения работ на высоте оградительную ленту, сигнальные конусы и знаки, запрещающие проход.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2118, 'es-ES', 'Designar un señalista o recurso preventivo en la zona de acceso restringido inferior para impedir estrictamente la entrada de personal no autorizado y mantener comunicación por radio con el equipo en altura.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2118, 'ru-RU', 'Назначить в контролируемой нижней зоне ответственного сигнальщика для строгого пресечения доступа посторонних лиц и поддержания радиосвязи с работниками на высоте.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2119, 'es-ES', 'Realizar una inspección final antes del trabajo del estado de instalación de las redes de seguridad (UNE-EN 1263-1) y las marquesinas de protección, verificando la integridad de la malla.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2119, 'ru-RU', 'Перед началом работ провести окончательную проверку состояния установки защитно-улавливающих сеток и защитных козырьков, а также целостности их ячеек.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2120, 'es-ES', 'Al instalar una escalera de mano, mantener el ángulo de inclinación seguro de 75° (relación 4:1) y comprobar el estado de las zapatas antideslizantes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2120, 'ru-RU', 'При установке приставной лестницы соблюдать безопасный угол наклона в 75 градусов и проверять состояние противоскользящих резиновых опор (башмаков).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2121, 'es-ES', 'Asegurar la base de la escalera con una segunda persona para evitar su vuelco y verificar la correcta fijación en la parte superior.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2121, 'ru-RU', 'Для предотвращения опрокидывания лестницы закрепить у её основания второго работника (работа в паре) и проверить надёжность крепления верхней части.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2122, 'es-ES', 'Prohibir la instalación de escaleras sobre superficies inestables o inclinadas, priorizando la nivelación del terreno previamente.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2122, 'ru-RU', 'Запретить установку лестниц на неустойчивом или наклонном грунте; в первую очередь выполнить работы по выравниванию поверхности.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2123, 'es-ES', 'Prohibir trabajar desde los tres últimos peldaños superiores de la escalera y cumplir siempre el principio de los tres puntos de apoyo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2123, 'ru-RU', 'Запретить работать на двух верхних ступеньках приставной лестницы и строго соблюдать правило трёх точек опоры.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2124, 'es-ES', 'Para tareas que requieran el uso de ambas manos, utilizar plataformas de trabajo móviles (PT) equipadas con estabilizadores en lugar de escaleras de mano.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2124, 'ru-RU', 'При работах, требующих использования обеих рук, вместо лестницы применять передвижные рабочие платформы (подмости), оснащённые аутригерами.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2125, 'es-ES', 'Utilizar cinturones o bolsas portaherramientas para mantener las manos libres y prohibir extender el cuerpo excesivamente fuera de los límites de la escalera.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2125, 'ru-RU', 'Во время работы использовать сумку для инструментов, чтобы освободить руки, и не допускать чрезмерного высовывания за пределы конструкции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2126, 'es-ES', 'Prohibir el uso de escaleras de fabricación improvisada no homologadas y permitir únicamente el acceso de equipos con certificación de seguridad (marcado CE según UNE-EN 131).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2126, 'ru-RU', 'Запретить использование самодельных, несертифицированных лестниц и допускать к эксплуатации только изделия, имеющие сертификат соответствия (ГОСТ Р).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2127, 'es-ES', 'Realizar una inspección semanal exhaustiva de todas las escaleras para detectar corrosión, fisuras, deformaciones y desgaste de las zapatas antideslizantes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2127, 'ru-RU', 'Еженедельно проводить полный технический осмотр лестниц на предмет коррозии, трещин, деформаций и износа нижних опор (башмаков).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2128, 'es-ES', 'Obligar a cumplimentar una lista de verificación diaria antes de su uso y, en caso de detectar anomalías, proceder a su retirada y desecho inmediato.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2128, 'ru-RU', 'Ввести обязательное заполнение ежедневного чек-листа перед использованием; при обнаружении неисправностей немедленно утилизировать и вывести с объекта.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2129, 'es-ES', 'Al montar las plataformas de trabajo, fijarlas firmemente con abrazaderas o sistemas de anclaje específicos para evitar su desplazamiento o desprendimiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2129, 'ru-RU', 'При монтаже рабочих настилов надёжно закреплять их специальной проволокой или зажимами для предотвращения смещения и отрыва.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2130, 'es-ES', 'Verificar, como comprobación final antes del trabajo, la horizontalidad de la estructura de soporte de la plataforma y el correcto apriete de las uniones de los puntales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2130, 'ru-RU', 'Перед началом работы провести окончательную проверку горизонтальности опорной конструкции настила и надёжности крепления соединительных узлов стоек.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2131, 'es-ES', 'Antes de iniciar la tarea, comprobar la estabilidad de la plataforma moviéndola manualmente para detectar holguras y reforzar la estructura de soporte inferior si es necesario.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2131, 'ru-RU', 'Перед работой проверить настил на наличие люфта, покачав его, и при необходимости принять меры по усилению нижней опорной конструкции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2132, 'es-ES', 'Instalar plataformas de trabajo con una anchura reglamentaria (mínimo 60 cm) que permita el movimiento seguro del trabajador.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2132, 'ru-RU', 'Устанавливать рабочий настил достаточной ширины (не менее 0,6 м) для обеспечения безопасного передвижения работника.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2133, 'es-ES', 'Instalar las plataformas ajustadas a la estructura para que el hueco no exceda los 3 cm y rellenar el espacio si fuera necesario.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2133, 'ru-RU', 'Монтировать настил вплотную к конструкции так, чтобы зазор не превышал 5 см, и при необходимости заполнять его.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2134, 'es-ES', 'En áreas de trabajo reducidas, utilizar plataformas auxiliares o consolas extensibles para garantizar un radio de trabajo adecuado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2134, 'ru-RU', 'При работе в стеснённых условиях использовать вспомогательные настилы или выдвижные консоли для обеспечения достаточного рабочего пространства.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2135, 'es-ES', 'Prohibir el acopio directo de herramientas y materiales sobre la plataforma de trabajo; se debe usar contenedores o bolsas portaherramientas específicas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2135, 'ru-RU', 'Запретить складирование инструментов и материалов непосредственно на рабочем настиле; использовать специальные ящики для материалов и сумки для инструментов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2136, 'es-ES', 'Bajar inmediatamente a nivel del suelo los materiales y herramientas una vez utilizados, y verificar constantemente que las vías de paso sobre la plataforma estén despejadas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2136, 'ru-RU', 'Немедленно спускать на землю использованные материалы и инструменты и постоянно контролировать свободное состояние проходов на настиле.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2137, 'es-ES', 'Inspeccionar la instalación de los rodapiés en los bordes de la plataforma para prevenir la caída de objetos y tropiezos de los trabajadores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2137, 'ru-RU', 'Проверять состояние установки бортовых ограждений (отбойных досок) по краям настила для предотвращения падения предметов и спотыкания работников.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2138, 'es-ES', 'Supervisar de forma continua el cumplimiento del principio de doble anclaje (conexión del 100%) del arnés anticaídas de los trabajadores en altura.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2138, 'ru-RU', 'Постоянно контролировать соблюдение работниками на высоте принципа непрерывной страховки (использование двух стропов) при применении страховочной привязи.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2139, 'es-ES', 'El supervisor debe verificar personalmente la resistencia de los puntos de anclaje (líneas de vida, estructuras sólidas) antes del inicio de los trabajos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2139, 'ru-RU', 'Перед началом работ руководитель должен лично проверить прочность точек анкерного крепления (анкерной линии, надёжных элементов конструкции).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2140, 'es-ES', 'Realizar una inspección visual diaria del EPI contra caídas (arnés, elementos de amarre) antes de su uso, comprobando el desgaste de las cintas, deformaciones en partes metálicas y el correcto funcionamiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2140, 'ru-RU', 'Ежедневно перед работой проводить осмотр стропов страховочной системы на предмет износа, деформации металлических частей и нарушения функциональности.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2141, 'es-ES', 'Antes de realizar trabajos en altura, comprobar el estado de desgaste de la suela del calzado de seguridad y la ausencia de sustancias adheridas (barro, aceite).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2141, 'ru-RU', 'Перед началом работ на высоте проверить состояние износа подошвы защитной обуви работника и отсутствие на ней посторонних веществ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2142, 'es-ES', 'Realizar una limpieza frecuente de las plataformas y pasarelas de trabajo para eliminar restos de aceite, agua o polvo que puedan causar resbalones.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2142, 'ru-RU', 'Регулярно очищать рабочие настилы и проходы от масел, влаги и пыли для поддержания порядка на рабочем месте.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2143, 'es-ES', 'Verificar la correcta instalación de cintas o superficies antideslizantes en zonas con alto riesgo de resbalamiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2143, 'ru-RU', 'Проверять состояние установки специальных противоскользящих лент или ковриков на участках с высоким риском поскальзывания.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2144, 'es-ES', 'Confirmar la disponibilidad en el lugar de trabajo de equipos de rescate específicos para accidentes por caída, como cuerdas de rescate, polipastos y camillas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2144, 'ru-RU', 'Убедиться в наличии на объекте специального спасательного оборудования на случай падения с высоты, включая спасательные верёвки, полиспасты и носилки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2145, 'es-ES', 'Mantener actualizado el plan de comunicación de emergencias para una notificación inmediata y verificar que los vigilantes o recursos preventivos porten equipos de radio en funcionamiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2145, 'ru-RU', 'Актуализировать схему экстренной связи для немедленного оповещения в случае аварии и проверить наличие и исправность радиостанций у наблюдающих.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2146, 'es-ES', 'Realizar simulacros periódicos con los trabajadores sobre técnicas de autorrescate y procedimientos de rescate a compañeros en caso de caída.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2146, 'ru-RU', 'Проводить регулярные практические тренировки с работниками по отработке методов самоспасения и процедур спасения коллег при падении.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2147, 'es-ES', 'Antes del desmontaje, confirmar el cierre de la válvula de suministro de gas y realizar una purga completa para evacuar cualquier gas residual de la tubería.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2147, 'ru-RU', 'Перед демонтажом убедиться в перекрытии запорного вентиля подачи газа и выполнить полную продувку линии для удаления остаточного газа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2148, 'es-ES', 'Utilizar detectores de gas portátiles para medir con precisión la concentración de gases tóxicos o inflamables residuales antes y después de abrir la tubería.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2148, 'ru-RU', 'С помощью портативного газоанализатора проводить точные замеры концентрации остаточных токсичных/горючих газов до и после вскрытия трубопровода.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2149, 'es-ES', 'Formar a los trabajadores sobre las Fichas de Datos de Seguridad (FDS) para que conozcan los peligros de las sustancias manipuladas y los procedimientos de emergencia en caso de fuga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2149, 'ru-RU', 'Провести для работников инструктаж по паспортам безопасности химической продукции (MSDS) для ознакомления с опасными свойствами веществ и мерами экстренного реагирования при утечках.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2150, 'es-ES', 'Al desmontar la línea, seguir la secuencia correcta para aflojar los pernos de la brida y verificar el uso de pantallas faciales y otros equipos de protección personal específicos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2150, 'ru-RU', 'При демонтаже линии соблюдать последовательность ослабления болтов фланца и проверять использование защитного лицевого щитка и специальных СИЗ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2151, 'es-ES', 'Instalar cubiertas de protección contra salpicaduras (Splash Guard) y controlar la evacuación de los trabajadores en las inmediaciones.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2151, 'ru-RU', 'Установить защитные кожухи для предотвращения разбрызгивания (Splash Guard) и контролировать эвакуацию работников из прилегающей зоны.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2152, 'es-ES', 'Comprobar previamente el correcto funcionamiento de los manómetros y realizar una verificación cruzada a través de la válvula de drenaje.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2152, 'ru-RU', 'Предварительно проверить исправность манометров и провести перекрёстную проверку через дренажный клапан.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2153, 'es-ES', 'Antes de los trabajos de desmontaje, medir la concentración de gases inflamables y activar la ventilación forzada mediante extractores localizados o ventiladores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2153, 'ru-RU', 'Перед началом демонтажных работ измерить концентрацию горючих газов и обеспечить принудительную вентиляцию с помощью местной вытяжной вентиляции или вентиляторов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2154, 'es-ES', 'Realizar una inspección completa para verificar que toda la iluminación y las herramientas eléctricas utilizadas en la zona de trabajo sean de tipo antideflagrante (ATEX).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2154, 'ru-RU', 'Провести полную проверку использования во взрывоопасной рабочей зоне осветительных приборов и электроинструментов во взрывозащищённом исполнении.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2155, 'es-ES', 'Realizar una purga intensiva y una nueva medición de la concentración en las zonas "muertas" o bolsillos donde es probable la acumulación de gas combustible.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2155, 'ru-RU', 'Провести интенсивную продувку и повторный замер концентрации в застойных зонах (карманах), где высока вероятность скопления горючего газа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2156, 'es-ES', 'Antes de desmontar los componentes, medir la temperatura de la superficie para confirmar que se ha enfriado lo suficiente y usar guantes de protección térmica.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2156, 'ru-RU', 'Перед разборкой компонентов измерить температуру их поверхности, чтобы убедиться в достаточном охлаждении, и использовать термостойкие перчатки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2157, 'es-ES', 'Al drenar fluidos a alta temperatura, verificar la conexión a una línea de drenaje específica y tomar medidas para prevenir salpicaduras.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2157, 'ru-RU', 'При сливе высокотемпературных жидкостей проверять состояние подключения к специальной дренажной линии и принимать меры по предотвращению разбрызгивания.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2158, 'es-ES', 'Conocer de antemano la ubicación de los botiquines de primeros auxilios y las duchas de emergencia para actuar en caso de quemaduras.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2158, 'ru-RU', 'Заранее ознакомиться с местонахождением аптечек первой помощи и аварийных душей на случай ожогов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2159, 'es-ES', 'Al utilizar equipos electromecánicos en atmósferas explosivas (zonas ATEX), verificar la marca de certificación antideflagrante y el estado de la conexión a tierra.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2159, 'ru-RU', 'При использовании электрооборудования во взрывоопасных зонах проверять наличие маркировки взрывозащиты и состояние заземления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2160, 'es-ES', 'Controlar estrictamente la entrada de equipos personales no certificados para atmósferas explosivas, como linternas o radios portátiles convencionales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2160, 'ru-RU', 'Строго контролировать пронос личного оборудования, не имеющего взрывозащищённого исполнения, такого как портативные фонари и радиостанции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2161, 'es-ES', 'Utilizar ropa de trabajo antiestática y conectar las pinzas de puesta a tierra específicas a los equipos de campo para prevenir la acumulación de electricidad estática.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2161, 'ru-RU', 'Для предотвращения накопления статического электричества использовать антистатическую спецодежду и подключать к оборудованию специальные зажимы заземления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2162, 'es-ES', 'Antes de la tarea, seleccionar el equipo de elevación adecuado para el peso de la pieza y comprobar si los accesorios de eslingado están dañados.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2162, 'ru-RU', 'Перед началом работ выбрать грузоподъемное оборудование, соответствующее весу детали, и проверить грузозахватные приспособления (стропы) на предмет повреждений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2163, 'es-ES', 'Restringir el acceso a la zona inferior del punto de separación de la carga pesada y utilizar herramientas manuales específicas para evitar el atrapamiento de manos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2163, 'ru-RU', 'Ограничить доступ в зону под местом разъединения тяжеловесного груза и использовать специальные ручные инструменты для предотвращения защемления рук работников.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2164, 'es-ES', 'Al elevar, cumplir el principio de eslingado de 2 puntos considerando el centro de gravedad y utilizar vientos (cuerdas guía) para evitar el vuelco de la carga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2164, 'ru-RU', 'При подъеме соблюдать принцип двухветвевой строповки с учетом центра тяжести груза и использовать оттяжки (направляющие канаты) для предотвращения его опрокидывания.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2165, 'es-ES', 'Disponer en el lugar de trabajo de la última revisión de los planos del equipo y asegurar que todo el personal conozca el procedimiento de desmontaje por etapas durante la charla de seguridad (Toolbox Meeting).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2165, 'ru-RU', 'Обеспечить наличие на рабочем месте актуальной версии чертежей оборудования и ознакомить весь персонал с пошаговой последовательностью демонтажа во время целевого инструктажа (TBM).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2166, 'es-ES', 'Verificar el estado de los soportes de la estructura a desmontar y comprobar el cumplimiento de la prohibición de desmontaje arbitrario de elementos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2166, 'ru-RU', 'Проверить состояние опор демонтируемой конструкции и убедиться в соблюдении запрета на произвольный демонтаж ее элементов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2167, 'es-ES', 'En cada fase clave del desmontaje, proceder a la siguiente etapa solo tras reconfirmar la estabilidad estructural bajo la supervisión del responsable de los trabajos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2167, 'ru-RU', 'На каждом ключевом этапе демонтажа переходить к следующему шагу только после повторного подтверждения конструктивной безопасности под надзором руководителя работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2168, 'es-ES', 'Proporcionar mascarillas de protección contra polvo adecuadas para cada tarea (tipo FFP3/FFP2) y comprobar regularmente su correcto ajuste facial.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2168, 'ru-RU', 'Обеспечить выдачу противопылевых респираторов, соответствующих классу опасности работ (FFP3/FFP2), и постоянно контролировать плотность их прилегания к лицу.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2169, 'es-ES', 'Instalar sistemas de extracción localizada cerca de la fuente de generación de polvo y aplicar simultáneamente métodos de trabajo en húmedo, como la pulverización de agua.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2169, 'ru-RU', 'Установить местную вытяжную вентиляцию вблизи источника пылеобразования и параллельно применять методы мокрой обработки, такие как периодическое разбрызгивание воды.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2170, 'es-ES', 'Implementar medidas para prevenir la dispersión de polvo, como cubrir el área de trabajo con lonas de plástico y restringir el acceso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2170, 'ru-RU', 'Принять меры по предотвращению распространения пыли путем укрытия рабочей зоны полиэтиленовой пленкой и ограничения доступа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2171, 'es-ES', 'Tras cortar el suministro eléctrico y cerrar las válvulas de gas, instalar dispositivos de bloqueo (Lock-out) y colocar las etiquetas de señalización correspondientes (Tag-out).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2171, 'ru-RU', 'После отключения электропитания и перекрытия газовых вентилей установить блокирующие устройства (Lock-out) и вывесить соответствующие маркировочные бирки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2172, 'es-ES', 'Después del aislamiento, utilizar polímetros y manómetros para verificar la ausencia total de energías residuales (estado de energía cero).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2172, 'ru-RU', 'После блокировки с помощью тестеров и манометров окончательно убедиться в отсутствии остаточной энергии (состояние ''нулевой энергии'').', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2173, 'es-ES', 'Realizar una verificación cruzada en el sitio para confirmar que la información del punto de aislamiento coincide entre el ejecutor del LOTO y el equipo de desmontaje.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2173, 'ru-RU', 'Провести перекрестную проверку на месте для подтверждения соответствия информации о точках блокировки между исполнителем LOTO и бригадой демонтажников.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2174, 'es-ES', 'Establecer la dirección de descarga del gas de venteo hacia una zona segura, lejos de los trabajadores, y restringir el acceso al área circundante.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2174, 'ru-RU', 'Направить сброс стравливаемого газа в безопасную сторону, где отсутствуют работники, и ограничить доступ в окружающую зону.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2175, 'es-ES', 'Ajustar el horario de trabajo monitorizando en tiempo real la dirección y velocidad del viento para evitar la dispersión de gas a procesos adyacentes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2175, 'ru-RU', 'Корректировать время проведения работ, отслеживая в реальном времени направление и скорость ветра, чтобы предотвратить распространение газа на смежные участки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2176, 'es-ES', 'Instalar detectores de gas alrededor del área de venteo y activar un sistema de notificación previa para los trabajadores de zonas cercanas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2176, 'ru-RU', 'Установить газоанализаторы в районе зоны сброса и задействовать систему предварительного оповещения работников на прилегающих участках.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2177, 'es-ES', 'Antes de inyectar nitrógeno en un espacio confinado, medir de forma continua la concentración de oxígeno y gases tóxicos y verificar el funcionamiento del sistema de ventilación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2177, 'ru-RU', 'Перед подачей азота в ограниченное и замкнутое пространство (ОЗП) постоянно измерять концентрацию кислорода и вредных газов, а также проверять работоспособность вентиляционного оборудования.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2178, 'es-ES', 'Calcular la cantidad de nitrógeno a inyectar y comprobar el estado de la válvula de control de flujo y del caudalímetro para evitar una sobreinyección.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2178, 'ru-RU', 'Проверить расчетное количество подаваемого азота и состояние клапана регулирования расхода и расходомера для предотвращения избыточной подачи.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2179, 'es-ES', 'Cumplir con el procedimiento de permiso de trabajo en espacios confinados, asegurar la presencia de un vigilante y verificar el uso de EPIs obligatorios como equipos de respiración con suministro de aire.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2179, 'ru-RU', 'Соблюдать процедуру наряда-допуска на работы в ОЗП, обеспечить присутствие наблюдающего и проверить использование обязательных СИЗ, таких как шланговые противогазы.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2180, 'es-ES', 'Realizar una inspección previa de la tubería de suministro de nitrógeno utilizando agua jabonosa para detectar corrosión, grietas y fugas en las conexiones.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2180, 'ru-RU', 'Провести предварительную проверку трубопровода подачи азота на наличие коррозии, трещин и утечек в соединениях с помощью мыльного раствора.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2181, 'es-ES', 'Realizar pruebas de apertura y cierre de la válvula de suministro para verificar su maniobrabilidad y capacidad de sellado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2181, 'ru-RU', 'Провести тестовое открытие и закрытие подающего вентиля для проверки плавности его хода и герметичности.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2182, 'es-ES', 'Inspeccionar la robustez de los soportes de la tubería e instalar cubiertas protectoras para resguardarla de impactos externos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2182, 'ru-RU', 'Проверить прочность опор трубопровода и установить защитные кожухи для его предохранения от внешних ударов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2183, 'es-ES', 'Instalar una válvula de seguridad de presión (PSV) de capacidad adecuada en la línea de inyección de nitrógeno y verificar periódicamente su funcionamiento a la presión de ajuste.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2183, 'ru-RU', 'Установить на линии подачи азота предохранительный клапан (PSV) соответствующей пропускной способности и регулярно проверять его срабатывание при заданном давлении.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2184, 'es-ES', 'Realizar la calibración del manómetro para mantener su precisión y verificar la configuración de las alarmas de límite superior e inferior.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2184, 'ru-RU', 'Проводить калибровку и поверку манометра для поддержания его точности и проверять настройку аварийных сигналов по верхнему и нижнему пределам.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2185, 'es-ES', 'Capacitar a los trabajadores en el procedimiento de apertura gradual de la válvula para prevenir aumentos bruscos de presión.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2185, 'ru-RU', 'Провести обучение работников процедуре постепенного открытия вентиля для предотвращения резкого повышения давления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2186, 'es-ES', 'Verificar el rendimiento de sellado de la válvula de corte y comprobar periódicamente el correcto funcionamiento de la válvula de retención (Check Valve).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2186, 'ru-RU', 'Проверить герметичность запорного вентиля и регулярно инспектировать исправность обратного клапана (Check Valve).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2187, 'es-ES', 'Aplicar el sistema de doble bloqueo y purga (Double Block and Bleed) para asegurar un aislamiento efectivo del fluido.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2187, 'ru-RU', 'Применять метод двойной блокировки и сброса (Double Block and Bleed) для обеспечения надежной изоляции потока.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2188, 'es-ES', 'Tras el cierre de la línea, drenar el fluido residual a través de la válvula de purga y confirmar visualmente el aislamiento completo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2188, 'ru-RU', 'После перекрытия линии слить остаточную жидкость через дренажный вентиль и визуально убедиться в полной изоляции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2189, 'es-ES', 'Antes de desmontar, eliminar completamente la presión residual de la línea y confirmar el estado cero con un manómetro.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2189, 'ru-RU', 'Перед началом демонтажных работ полностью сбросить остаточное давление в линии и подтвердить нулевое значение по манометру.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2190, 'es-ES', 'Al drenar el fluido residual, utilizar recipientes de recolección y líneas de drenaje dedicadas para prevenir derrames externos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2190, 'ru-RU', 'При сливе остаточной жидкости использовать специальные емкости для сбора и дренажные линии для предотвращения проливов во внешнюю среду.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2191, 'es-ES', 'Durante el desmontaje inicial, seguir el procedimiento de aflojar los pernos gradualmente para verificar la ausencia de presión interna.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2191, 'ru-RU', 'Соблюдать процедуру постепенного ослабления болтов при начальном демонтаже для перепроверки отсутствия внутреннего давления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2192, 'es-ES', 'Inspeccionar periódicamente el estado de corrosión y desgaste de juntas y pernos de conexión de tuberías mediante examen visual y de precisión.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2192, 'ru-RU', 'Регулярно проводить визуальный и инструментальный контроль состояния прокладок и болтов фланцевых соединений на предмет коррозии и износа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2193, 'es-ES', 'Sustituir de forma preventiva las conexiones envejecidas durante los periodos de mantenimiento programado y verificar el uso de componentes con las especificaciones nominales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2193, 'ru-RU', 'Проводить превентивную замену устаревших соединительных элементов во время планового ремонта и проверять использование изделий, соответствующих спецификации.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2194, 'es-ES', 'Llevar un detector de gas portátil y aplicar cinta detectora de fugas en las conexiones para una monitorización constante.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2194, 'ru-RU', 'Использовать портативный газоанализатор и наклеивать газочувствительную ленту на соединения для постоянного мониторинга утечек.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2195, 'es-ES', 'Gestionar la rotulación de cada válvula para identificar el tipo de fluido, la dirección del flujo y el estado de apertura/cierre.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2195, 'ru-RU', 'Обеспечить наличие на каждом вентиле маркировки с указанием типа среды, направления потока и состояния (открыто/закрыто).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2196, 'es-ES', 'Cumplir con el procedimiento de operar válvulas críticas bajo la supervisión del jefe de trabajo y reconfirmar la válvula objetivo antes de su manipulación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2196, 'ru-RU', 'Соблюдать процедуру оперирования ключевыми вентилями под надзором руководителя работ и повторно проверять целевой вентиль перед манипуляцией.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2197, 'es-ES', 'Antes de la operación, realizar una revisión final comparando los planos de las válvulas con la instalación real en campo para asegurar su correspondencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2197, 'ru-RU', 'Перед началом операций провести финальную сверку схем расположения арматуры с фактическим оборудованием на месте для подтверждения соответствия.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2198, 'es-ES', 'Instalar dispositivos de bloqueo y candado dedicados en las válvulas operativas principales y de aislamiento de energía, y gestionar las llaves.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2198, 'ru-RU', 'Установить специальные блокировочные устройства на ключевые рабочие и отсекающие энергию вентили и наладить систему контроля ключей.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2199, 'es-ES', 'Establecer zonas de acceso restringido para personal no autorizado y colocar señales de prohibido operar válvulas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2199, 'ru-RU', 'Установить зоны с ограниченным доступом для посторонних лиц и разместить знаки, запрещающие оперирование вентилями.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2200, 'es-ES', 'Publicar la lista de personal autorizado para operar válvulas y realizar formación sobre la prohibición estricta de manipulación por parte de personal no designado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2200, 'ru-RU', 'Вывесить список лиц, допущенных к управлению арматурой, и провести инструктаж о строгом запрете на манипуляции для неуполномоченного персонала.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2201, 'es-ES', 'Durante el mantenimiento programado, desmontar e inspeccionar las válvulas para verificar con precisión el desgaste del asiento y la presencia de depósitos de suciedad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2201, 'ru-RU', 'Во время планового ремонта проводить разборку и дефектоскопию арматуры для тщательной проверки износа седла и наличия отложений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2202, 'es-ES', 'Revisar periódicamente la existencia de fugas internas midiendo la diferencia de presión antes y después de la válvula.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2202, 'ru-RU', 'Периодически проверять наличие внутренних утечек путем измерения перепада давления до и после клапана.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2203, 'es-ES', 'Realizar regularmente la inyección de grasa y la limpieza de la válvula para mejorar la estanqueidad del asiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2203, 'ru-RU', 'Регулярно проводить набивку смазки и очистку клапана для улучшения герметичности седла.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2204, 'es-ES', 'Antes de conectar la línea de suministro de nitrógeno para la purga, realizar una medición precisa para verificar la ausencia de gases inflamables residuales en el interior de la tubería.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2204, 'ru-RU', 'Перед подключением линии подачи азота для продувки, точно измерить остаточную концентрацию горючих газов внутри трубопровода.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2205, 'es-ES', 'Verificar el cumplimiento de las condiciones esenciales definidas en el procedimiento de trabajo estándar, como el tiempo, caudal y presión de purga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2205, 'ru-RU', 'Проверить соблюдение обязательных условий, определенных в стандартной рабочей процедуре, таких как время, расход и давление продувки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2206, 'es-ES', 'Una vez finalizada la purga, medir la concentración de gas en la salida para verificar que se encuentra por debajo del Límite Inferior de Explosividad (LIE).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2206, 'ru-RU', 'По завершении продувки измерить концентрацию газа на выходе, чтобы подтвердить, что она ниже нижнего концентрационного предела распространения пламени (НКПР).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2222, 'es-ES', 'Realizar estiramientos antes de trabajar en espacios reducidos y utilizar reposapiés auxiliares para mantener una postura ergonómica.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2222, 'ru-RU', 'Перед работой в стесненных условиях выполнять растяжку и использовать вспомогательные подставки для ног для поддержания эргономичной позы.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2223, 'es-ES', 'Asignar periodos de descanso adecuados a cada trabajador y gestionar la fatiga física mediante la rotación de tareas en equipos de dos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2223, 'ru-RU', 'Предоставлять работникам достаточные перерывы для отдыха и управлять физической усталостью путем сменной работы в парах (2 человека).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2224, 'es-ES', 'Disponer de herramientas eléctricas compactas y sillas de altura regulable para evitar posturas encorvadas prolongadas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2224, 'ru-RU', 'Обеспечить наличие специального компактного электроинструмента и стульев с регулируемой высотой для предотвращения длительной работы в согнутом положении.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2225, 'es-ES', 'Antes de desconectar terminales, confirmar la ausencia de tensión basándose en los planos y verificar de nuevo con un detector de tensión sin contacto.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2225, 'ru-RU', 'Перед отсоединением клемм убедиться в отключении питания по схеме и повторно проверить отсутствие напряжения бесконтактным индикатором.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2226, 'es-ES', 'Realizar la comprobación final de la instalación del dispositivo de bloqueo en el interruptor (LOTO) y de la correcta colocación de la etiqueta de prohibición de maniobra.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2226, 'ru-RU', 'Провести финальную проверку установки блокировочного устройства на автоматическом выключателе (LOTO) и наличия запрещающей таблички.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2227, 'es-ES', 'Verificar el uso obligatorio de guantes dieléctricos y herramientas aisladas conforme a la norma UNE-EN 60903. Restringir estrictamente los trabajos eléctricos en ambientes húmedos según las guías del INSST.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2227, 'ru-RU', 'Обеспечить проверку применения специальных диэлектрических перчаток и изолированного инструмента в соответствии с ГОСТ Р. Строго ограничить выполнение работ во влажных условиях согласно требованиям правил по охране труда.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2228, 'es-ES', 'Cumplir el principio de trabajo en pareja (mínimo dos personas) para tareas de desmantelamiento de alto riesgo, activando un sistema de vigilancia mutua y comunicación constante.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2228, 'ru-RU', 'Соблюдать принцип работы в паре (бригадой не менее двух человек) при выполнении особо опасных работ по демонтажу и задействовать систему взаимного контроля.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2229, 'es-ES', 'En caso de ser inevitable el trabajo en solitario, establecer un procedimiento de comunicación periódica por radio y de notificación de la ubicación exacta del trabajador.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2229, 'ru-RU', 'При невозможности избежать работы в одиночку, разработать и утвердить процедуру регулярной связи по радиостанции и обмена информацией о точном местоположении работника.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2230, 'es-ES', 'Inspeccionar el correcto funcionamiento de las alarmas de emergencia y los equipos de comunicación en las inmediaciones del área de trabajo para garantizar una notificación rápida de incidentes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2230, 'ru-RU', 'Проверить исправность кнопок аварийной сигнализации и средств связи, предназначенных для оперативного оповещения, в непосредственной близости от рабочей зоны.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2231, 'es-ES', 'Realizar una inspección completa del par de apriete de los pernos en todas las conexiones y verificar el correcto asentamiento de las juntas antes de la puesta en marcha inicial.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2231, 'ru-RU', 'Перед первичным пуском провести полную проверку момента затяжки болтов на всех соединениях и убедиться в правильной установке уплотнительных прокладок.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2232, 'es-ES', 'Ejecutar pruebas de presión por etapas para una detección precisa de fugas y evacuar al personal a una ubicación remota para la operación de válvulas manuales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2232, 'ru-RU', 'Провести поэтапные испытания под давлением для точного выявления утечек и обеспечить эвакуацию персонала в безопасную зону для дистанционного управления ручными клапанами.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2233, 'es-ES', 'Aplicar líquido detector de fugas en las uniones o utilizar detectores de gas para un monitoreo de fugas en tiempo real.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2233, 'ru-RU', 'Осуществлять мониторинг утечек в реальном времени путем нанесения пенного индикатора на соединения или использования газоанализаторов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2234, 'es-ES', 'Asignar un vigilante dedicado en los puntos de aislamiento de energía e instalar vallado perimetral para impedir el acceso de personal no autorizado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2234, 'ru-RU', 'Выставить наблюдателя у точек изоляции источников энергии и установить ограждения для предотвращения доступа посторонних лиц.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2235, 'es-ES', 'Confirmar el uso de dispositivos de bloqueo y consignación (LOTO) dedicados, con sus correspondientes tarjetas de ''No Operar'' y la identificación del trabajador.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2235, 'ru-RU', 'Проверить применение специализированных блокировочных устройств и идентификационных бирок (система LOTO) с запрещающей надписью и Ф.И.О. работника.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2236, 'es-ES', 'Comunicar previamente a los departamentos adyacentes el horario de prohibición de maniobra y los equipos afectados antes de iniciar los trabajos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2236, 'ru-RU', 'Перед началом работ уведомить смежные подразделения о времени и перечне оборудования, на котором запрещены любые операции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2237, 'es-ES', 'Al inyectar gas de purga, seguir un procedimiento de presurización gradual utilizando válvulas de control de caudal.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2237, 'ru-RU', 'При подаче инертного газа для продувки соблюдать процедуру поэтапного повышения давления с использованием клапанов регулирования расхода.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2238, 'es-ES', 'Realizar una inspección previa del estado de fijación y el deterioro de los soportes de tuberías y abrazaderas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2238, 'ru-RU', 'Предварительно проверить состояние крепления и степень износа опор трубопроводов и хомутов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2239, 'es-ES', 'Monitorizar los manómetros en tiempo real y, en caso de superar la presión de diseño, detener la inyección inmediatamente y realizar una purga (venteo).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2239, 'ru-RU', 'Контролировать показания манометров в режиме реального времени и при превышении расчетного давления немедленно прекратить подачу и выполнить сброс (стравливание).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2240, 'es-ES', 'Verificar que cada trabajador utilice correctamente los EPI asignados: mascarilla de alta eficiencia (FFP3), gafas de seguridad y ropa de protección específica.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2240, 'ru-RU', 'Проверить состояние и правильность применения СИЗ каждым работником: противоаэрозольный респиратор высокого класса защиты, защитные очки и специальная защитная одежда.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2241, 'es-ES', 'Instalar un sistema de extracción localizada de gran capacidad en el punto de corte y colocar material de protección para evitar la dispersión de polvo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2241, 'ru-RU', 'В зоне резки установить мощную местную вытяжную вентиляцию и защитные укрытия для предотвращения распространения пыли.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2242, 'es-ES', 'Realizar trabajos en húmedo mediante pulverizadores para minimizar la emisión de polvo y utilizar herramientas de corte específicas para este fin.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2242, 'ru-RU', 'Применять влажный метод работ с использованием распылителей для минимизации пылеобразования и использовать специализированный режущий инструмент.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2243, 'es-ES', 'Colocar señalización de prohibido el paso cerca de equipos a alta temperatura y medir la temperatura de la superficie antes de retirar el aislamiento térmico.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2243, 'ru-RU', 'Установить знаки, запрещающие доступ к высокотемпературному оборудованию, и измерить температуру поверхности перед снятием теплоизоляции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2244, 'es-ES', 'Hacer obligatorio el uso de guantes y ropa de protección térmica para los trabajadores e inspeccionar el estado de dichos EPI.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2244, 'ru-RU', 'Обеспечить обязательное применение работниками термостойких перчаток и спецодежды, а также проверить их на наличие повреждений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2245, 'es-ES', 'Instalar temporalmente cubiertas de protección física o pantallas aislantes en las zonas con superficies calientes expuestas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2245, 'ru-RU', 'На участках с открытыми горячими поверхностями временно установить физические защитные кожухи или теплоизоляционные экраны.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2246, 'es-ES', 'Instruir sobre la necesidad de pausas regulares y una ingesta adecuada de agua y electrolitos al trabajar en verano o en zonas de alta temperatura.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2246, 'ru-RU', 'Провести инструктаж о необходимости регулярных перерывов, а также достаточного потребления воды и солей при работе в летний период или в зонах с высокой температурой.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2247, 'es-ES', 'Implementar un sistema de ''compañero'' (buddy system) para la supervisión constante de la condición física de los trabajadores y el monitoreo mutuo del estado de salud.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2247, 'ru-RU', 'Внедрить систему ''работы в паре'' для постоянного контроля за самочувствием работников и взаимного наблюдения за состоянием здоровья.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2248, 'es-ES', 'Medir el índice de temperatura de globo y bulbo húmedo (TGBH) en tiempo real en el lugar de trabajo y cumplir con los protocolos de suspensión de actividades según el nivel de riesgo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2248, 'ru-RU', 'Измерять индекс тепловой нагрузки среды (ТНС-индекс) на рабочем месте в реальном времени и соблюдать регламент прекращения работ в зависимости от уровня опасности.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2249, 'es-ES', 'Realizar una inspección completa del estado de fijación de las plataformas y la integridad estructural de las barandillas antes de trabajar en bandejas en altura.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2249, 'ru-RU', 'Перед началом работ на кабельных лотках на высоте провести полную проверку крепления настилов и конструктивной целостности ограждений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2250, 'es-ES', 'Asegurar el uso constante del arnés de seguridad y verificar que el gancho esté anclado a una línea de vida vertical o a una estructura sólida.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2250, 'ru-RU', 'Обеспечить постоянное ношение страховочной привязи и проверить крепление карабина к вертикальной анкерной линии или прочной конструкции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2251, 'es-ES', 'Prohibir la acumulación excesiva de materiales en el área de trabajo y mantener el orden y la limpieza en tiempo real para asegurar las vías de paso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2251, 'ru-RU', 'Запретить чрезмерное складирование материалов в рабочей зоне и в реальном времени поддерживать порядок для обеспечения свободных проходов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2252, 'es-ES', 'Al instalar una escalera, mantener un ángulo de seguridad de 75 grados e inspeccionar el estado de las zapatas antideslizantes de la base.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2252, 'ru-RU', 'При установке лестницы соблюдать безопасный угол наклона в 75 градусов и проверить состояние противоскользящих башмаков на основании.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2253, 'es-ES', 'Para trabajos en la parte superior de una escalera, organizar siempre un equipo de 2 personas, asignando a una de ellas para estabilizar la base y controlar el paso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2253, 'ru-RU', 'При работе на высоте с приставной лестницы обязательно работать в паре, при этом один работник должен находиться внизу для поддержки и контроля.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2254, 'es-ES', 'Utilizar una plataforma de trabajo móvil con estabilizadores en lugar de una escalera para tareas que requieran el uso de ambas manos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2254, 'ru-RU', 'Для работ, требующих использования обеих рук, вместо лестницы применять передвижную рабочую платформу (туру), оснащенную аутригерами.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2255, 'es-ES', 'Delimitar la zona inferior al punto de trabajo en altura con cinta de balizamiento, conos y señales de prohibido el paso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2255, 'ru-RU', 'Под местом проведения работ на высоте установить ограждение с помощью сигнальной ленты, конусов и знаков, запрещающих проход.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2256, 'es-ES', 'Asignar un señalista en la zona de control inferior para bloquear el acceso de personal no autorizado y mantener comunicación por radio con el equipo de arriba.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2256, 'ru-RU', 'В огороженной зоне внизу выставить сигнальщика для предотвращения прохода посторонних и поддержания радиосвязи с работниками наверху.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2257, 'es-ES', 'Realizar una inspección final del estado de instalación de las redes de seguridad y marquesinas de protección, así como de posibles roturas en la malla, antes del trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2257, 'ru-RU', 'Перед началом работ провести финальную проверку состояния установки защитно-улавливающих сеток и защитных козырьков, а также целостности их ячеек.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2258, 'es-ES', 'Antes de izar los materiales de la carcasa, asegurar la carga con un sistema de doble eslinga considerando el centro de gravedad e inspeccionar los aparejos de elevación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2258, 'ru-RU', 'Перед подъемом материалов корпуса выполнить строповку двумя стропами с учетом центра тяжести груза и проверить грузозахватные приспособления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2259, 'es-ES', 'Verificar la instalación de soportes de fijación temporal y calzos para prevenir el vuelco de materiales en el lugar de montaje.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2259, 'ru-RU', 'Убедиться в установке временных крепежных опор и подкладок для предотвращения опрокидывания материалов на месте монтажа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2260, 'es-ES', 'Controlar el área bajo la ruta de movimiento de materiales e instruir sobre el uso de herramientas de mano para guiar la carga y evitar atrapamientos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2260, 'ru-RU', 'Обеспечить контроль зоны под траекторией перемещения материалов и проинструктировать о применении ручных инструментов (оттяжек, багров) для предотвращения защемления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2261, 'es-ES', 'Verificar el uso obligatorio de pantallas faciales de protección completa y gafas de seguridad de alta densidad durante el corte y mecanizado de metales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2261, 'ru-RU', 'Проверить обязательное применение защитных лицевых щитков и очков с высокой степенью защиты при резке и обработке металла.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2262, 'es-ES', 'Instalar pantallas de protección transparentes para contener la proyección de fragmentos y controlar el acceso de otros trabajadores a la zona.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2262, 'ru-RU', 'Установить прозрачные защитные экраны для предотвращения разлета осколков и ограничить доступ других работников в опасную зону.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2263, 'es-ES', 'Comprobar la presencia y correcto estado de la guarda de seguridad en amoladoras y cortadoras, y verificar que se utilicen discos de las especificaciones correctas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2263, 'ru-RU', 'Проверить наличие защитного кожуха на шлифовальных и отрезных машинах и проконтролировать использование дисков соответствующей спецификации.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2264, 'es-ES', 'Antes de cerrar la carcasa, realizar una inspección visual completa para detectar la presencia de fluidos residuales, virutas metálicas, polvo u otros contaminantes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2264, 'ru-RU', 'Перед закрытием корпуса провести полный визуальный осмотр на предмет наличия остаточной жидкости, металлической стружки, пыли и других инородных тел.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2265, 'es-ES', 'Realizar la limpieza interna con aire a alta presión o productos de limpieza específicos y verificar el estado de secado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2265, 'ru-RU', 'Выполнить внутреннюю очистку сжатым воздухом или специальными чистящими средствами и проверить состояние просушки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2266, 'es-ES', 'Tras finalizar el trabajo, tomar fotografías del estado interno y obtener la aprobación final del supervisor a través de una lista de verificación digital.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2266, 'ru-RU', 'После завершения работ сделать фотофиксацию внутреннего состояния и получить окончательное одобрение руководителя через цифровой чек-лист.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2267, 'es-ES', 'Respetar los valores de par de apriete de diseño para cada perno de fijación de la carcasa y verificar la fuerza de apriete con una llave dinamométrica.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2267, 'ru-RU', 'Соблюдать проектные значения момента затяжки для крепежных болтов корпуса и контролировать усилие затяжки с помощью динамометрического ключа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2268, 'es-ES', 'En zonas sujetas a vibración, confirmar el uso de componentes de fijación auxiliares como arandelas de resorte o tuercas autoblocantes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2268, 'ru-RU', 'В зонах, подверженных вибрации, проверить применение вспомогательных крепежных элементов, таких как пружинные шайбы и самоконтрящиеся гайки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2269, 'es-ES', 'Después de apretar, realizar marcas de alineación con un rotulador y comprobar periódicamente si se ha producido aflojamiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2269, 'ru-RU', 'После затяжки нанести контрольные метки маркером и периодически проверять состояние крепления на предмет ослабления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2270, 'es-ES', 'Antes de la instalación de la tubería, marcar la línea central según los planos y realizar mediciones con un nivel láser de precisión.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2270, 'ru-RU', 'Перед монтажом трубопровода нанести осевую линию согласно чертежам и провести измерения с помощью точного лазерного нивелира.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2271, 'es-ES', 'Verificar el correcto asentamiento de la junta y la alineación de los agujeros de los pernos para detectar cualquier desalineación (excentricidad) en la conexión.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2271, 'ru-RU', 'Проверить правильность посадки прокладки и соосность болтовых отверстий для выявления эксцентриситета в соединении.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2272, 'es-ES', 'Realizar una comprobación cruzada final de la distancia entre caras de las bridas y la planitud vertical y horizontal en las conexiones de los equipos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2272, 'ru-RU', 'Провести финальную перекрестную проверку межфланцевого расстояния, а также вертикальности и горизонтальности на стыках с оборудованием.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2273, 'es-ES', 'Antes de realizar trabajos en caliente, retirar todos los materiales combustibles en un radio de 11 metros y cubrir las instalaciones fijas con mantas ignífugas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2273, 'ru-RU', 'Перед началом огневых работ удалить все горючие материалы в радиусе 11 метров, а стационарные объекты плотно укрыть противопожарным полотном.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2274, 'es-ES', 'Realizar una purga con nitrógeno para eliminar vapores inflamables del interior de la tubería y confirmar una concentración final del 0%.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2274, 'ru-RU', 'Для удаления горючих паров из трубопровода выполнить продувку азотом и подтвердить итоговую концентрацию на уровне 0%.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2275, 'es-ES', 'Cada trabajador deberá portar un detector de gases múltiples portátil durante el trabajo y monitorizar constantemente las lecturas de concentración en tiempo real.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2275, 'ru-RU', 'Обеспечить каждого работника носимым многокомпонентным газоанализатором и осуществлять непрерывный мониторинг концентраций в реальном времени.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2276, 'es-ES', 'Realizar inspecciones periódicas antes y durante el trabajo para asegurar que las rutas de evacuación de emergencia estén siempre despejadas y sin obstáculos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2276, 'ru-RU', 'Регулярно проверять до и во время работы, что пути эвакуации постоянно свободны и не загромождены посторонними предметами.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2277, 'es-ES', 'Asignar un vigilante de incendios dedicado y verificar que porte un equipo de comunicación (radio/silbato) para la notificación inmediata en caso de emergencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2277, 'ru-RU', 'Обеспечить постоянное присутствие наблюдающего за огневыми работами и проверить наличие у него средств связи (рация/свисток) для немедленного оповещения при чрезвычайной ситуации.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2278, 'es-ES', 'Verificar la publicación de la lista de contactos de emergencia actualizada y reconfirmar en la charla de seguridad (TBM) que cada persona conoce su rol según los escenarios de accidente.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2278, 'ru-RU', 'Вывесить актуализированный план контактов для экстренной связи и в ходе инструктажа на рабочем месте (TBM) повторно проверить знание каждым сотрудником своих обязанностей согласно сценариям аварий.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2279, 'es-ES', 'Asegurar la retirada de materiales combustibles en un radio de 11 metros alrededor de los trabajos en caliente y la protección de equipos fijos con mantas ignífugas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2279, 'ru-RU', 'Проверить удаление горючих материалов в радиусе 11 м от места проведения огневых работ и укрытие несгораемыми материалами (противопожарным полотном) стационарного оборудования.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2280, 'es-ES', 'Inspeccionar la asignación de un vigilante de incendios y la disponibilidad inmediata de los medios de extinción y la lista de contactos de emergencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2280, 'ru-RU', 'Проверить назначение ответственного наблюдающего за огневыми работами, а также наличие и доступность плана экстренной связи и первичных средств пожаротушения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2281, 'es-ES', 'Realizar una verificación visual del aislamiento y la estanqueidad de las tuberías adyacentes que contengan fluidos inflamables.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2281, 'ru-RU', 'Провести визуальный осмотр состояния изоляции и герметичности смежных трубопроводов, по которым транспортируются горючие жидкости.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2285, 'es-ES', 'Medir la concentración de oxígeno y gases peligrosos antes de entrar en un espacio confinado y mantener en funcionamiento continuo la ventilación forzada durante los trabajos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2285, 'ru-RU', 'Перед входом в замкнутое пространство измерить концентрацию кислорода и вредных газов, а также обеспечить постоянную работу принудительной вентиляции во время работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2286, 'es-ES', 'Asegurar que el trabajo se realice en equipos de dos personas y verificar la comunicación periódica por radio con el vigilante exterior.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2286, 'ru-RU', 'Организовать работу в бригаде из не менее двух человек и проверять поддержание регулярной связи по рации с наблюдающим снаружи.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2287, 'es-ES', 'Realizar una inspección completa de la dotación y el correcto uso de los equipos de protección respiratoria obligatorios, como equipos con suministro de aire o autónomos (ERA).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2287, 'ru-RU', 'Провести полную проверку выдачи и правильности применения обязательных СИЗОД, таких как шланговые или автономные дыхательные аппараты.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2288, 'es-ES', 'Garantizar que el vigilante de incendios permanezca en el lugar de trabajo durante al menos 30 minutos después de finalizar para controlar la posible existencia de brasas residuales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2288, 'ru-RU', 'Обеспечить нахождение наблюдающего на месте проведения работ не менее 30 минут после их завершения для контроля за возможными очагами тления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2289, 'es-ES', 'Inspeccionar visualmente el radio de proyección de partículas incandescentes para detectar combustión sin llama (rescoldos) y asegurar la eliminación completa de materiales combustibles.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2289, 'ru-RU', 'Провести визуальную проверку на предмет возникновения тления в радиусе разлета искр и полностью удалить все горючие материалы из этой зоны.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2290, 'es-ES', 'Cumplimentar la lista de verificación de seguridad final al terminar los trabajos y transferir el historial de trabajos en caliente al siguiente turno.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2290, 'ru-RU', 'Заполнить итоговый чек-лист по безопасности после окончания работ и передать информацию о проведенных огневых работах следующей смене.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2309, 'es-ES', 'Verificar el uso obligatorio de pantalla facial completa y gafas de seguridad, así como el correcto montaje de la carcasa de protección de la amoladora.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2309, 'ru-RU', 'Проверить обязательное применение защитного лицевого щитка и очков, а также наличие и исправность защитного кожуха на углошлифовальной машине.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2310, 'es-ES', 'Inspeccionar el disco abrasivo antes de su uso para detectar fisuras o desgaste y confirmar que sus especificaciones son adecuadas para la velocidad nominal de la máquina.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2310, 'ru-RU', 'Провести предварительный осмотр абразивного круга на наличие трещин и износа, а также проверить его соответствие паспортной скорости инструмента.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2311, 'es-ES', 'Orientar la dirección del trabajo hacia una zona segura sin presencia de otros trabajadores e instalar pantallas de protección contra proyecciones.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2311, 'ru-RU', 'Направлять работу в безопасную сторону, где отсутствуют другие работники, и установить защитные экраны для предотвращения разлета частиц.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2318, 'es-ES', 'Mantener una postura estable con 3 puntos de apoyo durante el corte y verificar la sujeción firme de la pieza de trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2318, 'ru-RU', 'Соблюдать устойчивое положение тела (правило трех опор) при выполнении резки и проверить надежность фиксации обрабатываемой детали.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2319, 'es-ES', 'Comprobar antes de cada uso el correcto funcionamiento de los dispositivos de seguridad mecánicos (p. ej., protector del disco, sistema antirretroceso).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2319, 'ru-RU', 'Перед началом работы проверить исправность механических устройств безопасности (защитного кожуха, механизма защиты от обратного удара).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2320, 'es-ES', 'Verificar el uso de un disco de corte adecuado para el material y comprobar que no presenta daños.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2320, 'ru-RU', 'Проверить, что используется отрезной круг, соответствующий обрабатываемому материалу, и осмотреть его на предмет повреждений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2321, 'es-ES', 'Confirmar visualmente el cierre de la válvula principal de la línea a desmontar e instalar un dispositivo de bloqueo y consignación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2321, 'ru-RU', 'Визуально убедиться в перекрытии главного вентиля на демонтируемой линии и установить на него специальное блокирующее устройство.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2322, 'es-ES', 'Antes del trabajo, medir con precisión la estanqueidad de las conexiones de la tubería utilizando un detector de gas portátil.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2322, 'ru-RU', 'Перед началом работ провести точные замеры герметичности в местах соединений трубопровода с помощью переносного газоанализатора.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2323, 'es-ES', 'Purgar la línea de gas aislada con un gas inerte (p. ej., N2) y verificar la concentración residual.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2323, 'ru-RU', 'Выполнить продувку изолированного газопровода инертным газом (N2) и проконтролировать остаточную концентрацию горючих веществ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2324, 'es-ES', 'Colocar una etiqueta de ''No Operar'' y un dispositivo LOTO personal con el nombre del trabajador en el punto de aislamiento de energía.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2324, 'ru-RU', 'На точке отключения энергии вывесить знак ''Не включать!'' и установить персональное блокирующее устройство системы LOTO с ФИО работника.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2325, 'es-ES', 'Instalar barreras físicas alrededor de la zona de operación de válvulas y restringir estrictamente el acceso a personal no autorizado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2325, 'ru-RU', 'Установить физические ограждения вокруг зоны управления запорной арматурой и строго ограничить доступ посторонних лиц.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2326, 'es-ES', 'En la charla de seguridad (TBM), designar claramente al personal autorizado para operar válvulas e instruir sobre la prohibición de manipulación por personal no designado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2326, 'ru-RU', 'Во время инструктажа (ТВМ) четко назначить лиц, уполномоченных на управление арматурой, и провести обучение о запрете самовольного вмешательства.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2330, 'es-ES', 'Antes de intervenir en un equipo, desconectar la alimentación principal y verificar la ausencia de energía residual con un comprobador de tensión.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2330, 'ru-RU', 'Перед ремонтом оборудования отключить главное питание и с помощью тестера окончательно убедиться в сбросе остаточной энергии.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2331, 'es-ES', 'En equipos con arranque automático, conmutar a modo manual en el panel de control y verificar el estado de los enclavamientos de seguridad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2331, 'ru-RU', 'Для оборудования с автоматическим пуском переключить его в ручной режим на панели управления и проверить состояние систем блокировки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2332, 'es-ES', 'Instalar pasadores de bloqueo mecánicos en las partes móviles del equipo para impedir físicamente cualquier accionamiento accidental.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2332, 'ru-RU', 'Установить механические стопорные штифты вблизи приводных частей оборудования, чтобы заблокировать возможность их механического движения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2336, 'es-ES', 'Antes de desmontar una tubería, comprobar la lectura del manómetro y confirmar la purga completa de residuos a través de la válvula de drenaje.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2336, 'ru-RU', 'Перед демонтажом трубопровода проверить показания манометра (должны быть на нуле) и окончательно убедиться в сливе остатков через дренажный клапан.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2337, 'es-ES', 'Aflojar los pernos de forma gradual y secuencial, nunca todos a la vez, para verificar la liberación controlada de la presión interna.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2337, 'ru-RU', 'При ослаблении болтов откручивать их постепенно и в перекрестном порядке для перепроверки состояния сброса внутреннего давления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2338, 'es-ES', 'Instalar una cubierta de protección específica en el punto de trabajo para evitar la exposición directa del trabajador a posibles rociados de fluido.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2338, 'ru-RU', 'Установить специальный защитный экран в месте проведения работ, чтобы исключить прямое попадание на работника струи жидкости.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2348, 'es-ES', 'Al purgar la presión residual, abrir la válvula gradualmente para prevenir vibraciones bruscas y el golpe de ariete en la tubería.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2348, 'ru-RU', 'При сбросе остаточного давления регулировать открытие клапана постепенно, чтобы предотвратить резкую вибрацию и гидравлический удар в трубопроводе.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2349, 'es-ES', 'Inspeccionar previamente el estado de los soportes y abrazaderas de la tubería e instalar refuerzos temporales si fuera necesario.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2349, 'ru-RU', 'Предварительно проверить состояние креплений опор и хомутов трубопровода и, при необходимости, установить временные усиливающие конструкции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2350, 'es-ES', 'Utilizar protección auditiva como tapones u orejeras para protegerse del ruido generado durante la despresurización a alta presión.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2350, 'ru-RU', 'Использовать средства индивидуальной защиты слуха (беруши) для защиты работников от шума, возникающего при сбросе высокого давления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2351, 'es-ES', 'Realizar una inspección completa de todos los equipos eléctricos en zonas ATEX, verificando el marcado ''Ex'' y que su categoría es adecuada para la zona.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2351, 'ru-RU', 'Провести полную проверку всего электрооборудования, используемого во взрывоопасной зоне, на наличие маркировки взрывозащиты (Ex) и её соответствие классу зоны.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2352, 'es-ES', 'Controlar estrictamente la introducción de equipos personales no certificados para ATEX (linternas, radios, móviles) antes de acceder a zonas clasificadas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2352, 'ru-RU', 'Строго контролировать пронос личных невзрывозащищенных устройств (фонари, рации, смартфоны) перед входом во взрывоопасную зону.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2353, 'es-ES', 'Utilizar luminarias con certificación ATEX para iluminación temporal y verificar la correcta instalación de los prensaestopas ''Ex'' en las conexiones.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2353, 'ru-RU', 'При установке временного освещения использовать взрывозащищенные светильники и проверить правильность монтажа взрывозащищенных кабельных вводов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2354, 'es-ES', 'Asegurar la disponibilidad de las Fichas de Datos de Seguridad (FDS) en cada punto de trabajo y realizar formación periódica sobre precauciones y medidas de emergencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2354, 'ru-RU', 'Обеспечить наличие Паспортов безопасности химической продукции (MSDS) на рабочих местах и проводить регулярное обучение мерам предосторожности и действиям в чрезвычайных ситуациях.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2355, 'es-ES', 'Verificar el uso de EPIs adecuados para el producto manipulado, como traje de protección química, guantes de resistencia química y protección respiratoria.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2355, 'ru-RU', 'Проверить применение обязательных СИЗ, соответствующих свойствам химического вещества: защитная одежда, химостойкие перчатки, средства защиты органов дыхания.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2356, 'es-ES', 'Verificar el correcto funcionamiento de las duchas de emergencia y lavaojos y asegurar que sus rutas de acceso estén libres de obstáculos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2356, 'ru-RU', 'Проверить работоспособность аварийных душей и фонтанчиков для промывки глаз и устранить препятствия на путях доступа к ним.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2357, 'es-ES', 'Delimitar la zona inferior al área de desmontaje y realizar una inspección previa de la integridad estructural de las redes y marquesinas de protección contra caídas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2357, 'ru-RU', 'Установить ограждение под зоной демонтажных работ и предварительно проверить структурную целостность защитно-улавливающих сеток и козырьков.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2358, 'es-ES', 'Utilizar equipos de elevación específicos para el desmontaje de tuberías pesadas y verificar el uso de eslingas de dos ramales considerando el centro de gravedad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2358, 'ru-RU', 'При демонтаже тяжелых трубопроводов использовать специальные грузоподъемные механизмы и проверять двухветвевую строповку с учетом центра тяжести груза.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2359, 'es-ES', 'Utilizar cabos de anclaje para herramientas para prevenir su caída en trabajos en altura y mantener el arnés de seguridad anclado en todo momento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2359, 'ru-RU', 'При демонтаже на высоте использовать специальные стропы для крепления инструмента и постоянно применять страховочную привязь.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2360, 'es-ES', 'En la charla de seguridad (TBM) previa, prestar especial atención al estado de salud de los trabajadores (mareos, tensión, etc.) y su nivel de fatiga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2360, 'ru-RU', 'Перед началом работы во время инструктажа (TBM) уделить особое внимание проверке состояния здоровья работников (головокружение, давление) и уровня усталости.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2361, 'es-ES', 'Suspender inmediatamente los trabajos en altura en caso de viento fuerte (>10 m/s) o lluvia, y monitorizar permanentemente los avisos meteorológicos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2361, 'ru-RU', 'Немедленно прекратить работы на высоте при сильном ветре (более 10 м/с) или дожде и постоянно отслеживать метеорологические сводки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2362, 'es-ES', 'Utilizar calzado de seguridad con suela antideslizante y mantener las superficies de las plataformas de trabajo libres de humedad o aceite.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2362, 'ru-RU', 'Применять специальную нескользящую защитную обувь для работ на высоте и регулярно удалять влагу/масла с поверхности рабочего настила.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2363, 'es-ES', 'Establecer y proteger pasillos exclusivos para peatones en las rutas de circulación de carretillas, utilizando barreras físicas y señalización.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2363, 'ru-RU', 'Обеспечить выделенные пешеходные проходы на маршрутах движения погрузчиков и установить защитные ограждения и барьеры.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2364, 'es-ES', 'Realizar una inspección diaria antes del uso de la carretilla, comprobando frenos, dirección y la señal acústica de marcha atrás.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2364, 'ru-RU', 'Ежедневно перед началом работы проверять исправность тормозов, рулевого управления и звукового сигнала заднего хода вилочного погрузчика.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2365, 'es-ES', 'Reducir la velocidad obligatoriamente en intersecciones y puntos ciegos y utilizar un señalista para dirigir el tráfico.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2365, 'ru-RU', 'Обеспечить обязательное снижение скорости на перекрестках и в зонах с ограниченной видимостью, а также регулирование движения с помощью сигнальщика.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2366, 'es-ES', 'Inspeccionar todos los accesorios de elevación (eslingas, cables) antes de cada uso para detectar daños y utilizar únicamente equipos homologados.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2366, 'ru-RU', 'Перед подъемом груза провести полную проверку грузозахватных приспособлений (строп, канатов) на предмет повреждений и использовать только сертифицированные изделия.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2367, 'es-ES', 'Verificar el correcto funcionamiento de los dispositivos de seguridad de la grúa, como el limitador de fin de carrera y el limitador de sobrecarga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2367, 'ru-RU', 'Проверить исправность ключевых приборов безопасности крана, таких как ограничитель высоты подъема крюка и ограничитель грузоподъемности.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2368, 'es-ES', 'Establecer y señalizar una zona de acceso restringido bajo la carga suspendida y utilizar vientos (cuerdas guía) para controlar su movimiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2368, 'ru-RU', 'Установить зону, запрещенную для нахождения людей под поднятым грузом, и использовать оттяжки для предотвращения его раскачивания и вращения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2369, 'es-ES', 'Seleccionar un blindaje de espesor adecuado a la intensidad de la energía de la radiación y verificar la correcta estanqueidad de las juntas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2369, 'ru-RU', 'Выбрать защитные экраны достаточной толщины в соответствии с интенсивностью радиационного излучения и проверить герметичность их соединений и стыков.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2370, 'es-ES', 'Instalar barreras de protección radiológica alrededor de la zona de inspección y monitorizar continuamente con un dosímetro la posible fuga de radiación fuera del perímetro de seguridad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2370, 'ru-RU', 'Установить защитные ограждения вокруг зоны контроля и постоянно проверять с помощью дозиметра отсутствие утечек излучения за пределами контролируемой зоны.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2371, 'es-ES', 'Verificar el uso correcto de dosímetros personales de lectura directa (DLD) y termoluminiscentes (TLD) por parte de cada trabajador, asegurando su colocación en la posición reglamentaria.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (2371, 'ru-RU', 'Контролировать наличие и правильное ношение индивидуальных дозиметров прямого считывания и термолюминесцентных дозиметров (ТЛД) у каждого работника в установленном месте.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4001, 'es-ES', 'Inspeccionar la totalidad de los arriostramientos horizontales y diagonales del sistema de cimbra y apuntalamiento, conforme a la memoria de cálculo y los planos de montaje.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4001, 'ru-RU', 'Провести полную проверку установки горизонтальных связей и диагональных распорок (раскосов) опалубки в соответствии с проектной документацией (ППР).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4002, 'es-ES', 'Durante el hormigonado, seguir el orden de vertido para evitar cargas excéntricas y vigilar visualmente en tiempo real cualquier deformación del apuntalamiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4002, 'ru-RU', 'Соблюдать последовательность бетонирования для предотвращения эксцентричных нагрузок и вести постоянное визуальное наблюдение за деформацией стоек опалубки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4003, 'es-ES', 'Asegurar la verticalidad de los puntales superiores e inferiores y verificar su unión firme mediante el uso de pasadores de conexión específicos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4003, 'ru-RU', 'Поддерживать строгую вертикальность верхних и нижних стоек опалубки и проверять надежность их соединения с помощью специальных соединительных штифтов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4004, 'es-ES', 'Reforzar con soportes provisionales (vientos de cable) y puntales de arriostramiento para prevenir el vuelco durante el montaje de muros y pilares de armadura.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4004, 'ru-RU', 'При монтаже арматурных каркасов стен и колонн устанавливать временные опоры (подкосы и растяжки) для предотвращения их опрокидывания.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4005, 'es-ES', 'Instalar capuchones de protección en las puntas de las armaduras salientes (esperas) y verificar el uso de EPIs adecuados (guantes de cuero, gafas de seguridad) por parte del trabajador.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4005, 'ru-RU', 'Устанавливать специальные защитные колпачки на концы выступающих арматурных стержней и проверять использование работниками соответствующих СИЗ (кожаные перчатки, защитные очки).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4006, 'es-ES', 'Al izar armaduras, utilizar un sistema de doble eslinga considerando el centro de gravedad y designar a un señalista para dirigir el tráfico bajo la carga suspendida.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4006, 'ru-RU', 'При подъеме арматурных каркасов соблюдать двухветвевую строповку с учетом центра тяжести груза и назначать сигнальщика для контроля зоны под перемещаемым грузом.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4007, 'es-ES', 'Verificar el funcionamiento del limitador de altura y del interruptor de parada de emergencia para prevenir el atrapamiento con obstáculos superiores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4007, 'ru-RU', 'Проверить исправность ограничителя предельного подъема и аварийного выключателя для предотвращения защемления между платформой и верхними препятствиями.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4008, 'es-ES', 'Verificar el uso constante del arnés de seguridad durante la permanencia en la plataforma de trabajo y la correcta conexión del mosquetón al punto de anclaje designado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4008, 'ru-RU', 'При нахождении на рабочей платформе постоянно использовать страховочную привязь, проверяя надежность крепления карабина к специальной анкерной точке.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4009, 'es-ES', 'Elevar la plataforma de trabajo únicamente después de confirmar la nivelación del terreno y verificar la extensión completa de los estabilizadores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4009, 'ru-RU', 'Подъем рабочей платформы производить только после проверки ровности поверхности и полной установки выдвижных опор (аутригеров).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4010, 'es-ES', 'Comprobar el bloqueo de los frenos de las ruedas del andamio y la ampliación de la base de apoyo mediante los estabilizadores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4010, 'ru-RU', 'Проверить фиксацию тормозных устройств (стопоров) колес передвижных подмостей и расширение опорной площади с помощью аутригеров.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4011, 'es-ES', 'Asegurar la instalación de una escalera de acceso interior y verificar la presencia de la barandilla superior y la barandilla intermedia de seguridad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4011, 'ru-RU', 'Соблюдать требование по установке лестницы для подъема внутри лесов и проверить наличие верхнего и промежуточного защитных ограждений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4012, 'es-ES', 'Prohibir el acopio de materiales en el andamio y prohibir estrictamente su desplazamiento con trabajadores sobre la plataforma.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4012, 'ru-RU', 'Запретить складирование материалов на лесах и строго запретить перемещение лесов с находящимися на них работниками.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4013, 'es-ES', 'Al instalar cubiertas para aberturas, fijarlas firmemente para evitar su desplazamiento accidental y colocar señalización de riesgo de caída.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4013, 'ru-RU', 'Устанавливая защитные покрытия на проемы, надежно закрепить их для предотвращения самопроизвольного смещения и вывесить знаки опасности падения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4014, 'es-ES', 'Garantizar la seguridad del trabajador mediante la instalación de barandillas de seguridad provisionales y líneas de vida horizontales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4014, 'ru-RU', 'Обеспечить безопасность работников путем установки временных защитных ограждений и горизонтальных анкерных линий.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4015, 'es-ES', 'Asegurar una iluminación adecuada para identificar aberturas en zonas oscuras e instalar pintura fotoluminiscente o luces de advertencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4015, 'ru-RU', 'Обеспечить достаточный уровень освещенности для идентификации проемов в темных местах и установить светоотражающую разметку или сигнальные огни.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4016, 'es-ES', 'Antes de iniciar los trabajos, inspeccionar el desgaste, rotura de hilos y estado de las uniones de las cuerdas, e instalar una línea de vida vertical independiente.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4016, 'ru-RU', 'Перед началом работ проверить канат на предмет износа, обрыва проволок и состояния креплений, а также установить отдельную вертикальную анкерную линию.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4017, 'es-ES', 'Instalar protectores de cantos específicos en los puntos de contacto entre la cuerda y la estructura, y aislar los bordes afilados.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4017, 'ru-RU', 'Установить специальные протекторы (защиту от перетирания) в местах контакта каната с конструкциями и изолировать острые кромки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4018, 'es-ES', 'Realizar un seguimiento continuo de las condiciones meteorológicas (viento > 10m/s) y cumplir con la directriz de suspender los trabajos en caso de mal tiempo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4018, 'ru-RU', 'Вести постоянный мониторинг погодных условий (скорость ветра > 10 м/с) и соблюдать указание о прекращении работ при неблагоприятных погодных условиях.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4019, 'es-ES', 'Al desplazarse sobre cubiertas, instalar señalización de ''Precaución al pisar'' y disponer pasarelas de trabajo específicas para distribuir la carga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4019, 'ru-RU', 'При перемещении по крыше установить знаки, предупреждающие о хрупких участках, и использовать специальные переходные мостики (трапы) для распределения нагрузки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4020, 'es-ES', 'Instalar previamente las barandillas de seguridad y las redes de protección como parte de los trabajos preliminares y verificar el anclaje de los arneses individuales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4020, 'ru-RU', 'На предварительном этапе работ установить защитные ограждения и улавливающие сетки, а также проверить крепление индивидуальных страховочных систем.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4021, 'es-ES', 'Instalar cintas de advertencia de alta visibilidad en los bordes de los paneles y en las zonas de aberturas, y controlar permanentemente el acceso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4021, 'ru-RU', 'Установить хорошо заметную сигнальную ленту по краям панелей и в зонах проемов и осуществлять постоянный контроль доступа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4022, 'es-ES', 'Instalar mantas ignífugas debajo del punto de soldadura para proteger contra la dispersión de proyecciones y retirar los materiales combustibles cercanos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4022, 'ru-RU', 'Под местом проведения сварочных работ установить огнезащитное полотно для предотвращения разлета искр и убрать близлежащие горючие материалы.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4023, 'es-ES', 'Utilizar accesorios de elevación específicos para la chapa colaborante y establecer una zona de exclusión controlada debajo de la carga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4023, 'ru-RU', 'При подъеме профилированного настила использовать специальные грузозахватные приспособления и установить контролируемую зону под перемещаемым грузом.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4024, 'es-ES', 'Antes de iniciar los trabajos, confirmar la estabilidad del apoyo de la chapa colaborante e inspeccionar el apriete de los tornillos de fijación provisional.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4024, 'ru-RU', 'Перед началом работ проверить надежность опирания профилированного настила и проверить затяжку временных крепежных болтов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4028, 'es-ES', 'Asegurar un canal de radio exclusivo entre la punta de la pluma de la grúa y el operador, y unificar el código de señales manuales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4028, 'ru-RU', 'Обеспечить выделенный канал радиосвязи между стропальщиком и машинистом крана и унифицировать систему знаковой сигнализации.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4029, 'es-ES', 'Respetar el ángulo de las eslingas considerando el centro de gravedad de la carga e inspeccionar los accesorios de eslingado en busca de daños antes de su uso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4029, 'ru-RU', 'Соблюдать угол строповки с учетом центра тяжести груза и проверять исправность грузозахватных приспособлений перед началом работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4030, 'es-ES', 'En caso de solapamiento de los radios de acción de grúas adyacentes, verificar el correcto funcionamiento del sistema inteligente anticolisión.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4030, 'ru-RU', 'При пересечении рабочих зон смежных кранов проверить исправность интеллектуальной системы предотвращения столкновений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4031, 'es-ES', 'Verificar la instalación de barandillas de seguridad robustas y cubiertas de protección contra caídas en los accesos al hueco del ascensor y en el foso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4031, 'ru-RU', 'Проверить установку надежных защитных ограждений и покрытий для предотвращения падения в шахту лифта и в приямок.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4032, 'es-ES', 'Al trabajar sobre la cabina, usar siempre el arnés de seguridad y enganchar el mosquetón a la línea de vida vertical o a un punto de anclaje fijo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4032, 'ru-RU', 'При работе на крыше кабины лифта постоянно использовать страховочную привязь и крепить карабин к вертикальной анкерной линии или стационарной точке крепления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4033, 'es-ES', 'Durante las pruebas de funcionamiento del ascensor, asegurar la comunicación en tiempo real entre los trabajadores de los pisos superior e inferior y controlar el área de trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4033, 'ru-RU', 'При тестировании движения лифта обеспечить связь в реальном времени между работниками на верхнем и нижнем этажах и контролировать рабочую зону.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4034, 'es-ES', 'Medir las concentraciones de oxígeno y de los 4 gases principales (H2S, CO, LEL, O2) en la parte superior, media e inferior del espacio confinado antes de la entrada.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4034, 'ru-RU', 'Перед входом в ограниченное и замкнутое пространство (ОЗП) провести замеры концентрации кислорода и 4-х основных газов (H2S, CO, НПВ, O2) на трех уровнях: верхнем, среднем и нижнем.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4035, 'es-ES', 'Comprobar la fecha de validez de la calibración del detector de gases y verificar su funcionamiento mediante el botón de prueba antes de iniciar los trabajos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4035, 'ru-RU', 'Проверить срок действия калибровки газоанализатора и перед началом работ убедиться в его исправности с помощью тестовой кнопки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4036, 'es-ES', 'Asegurar la aprobación del permiso de trabajo en espacios confinados (PTW), publicar los resultados de la medición de gases en la entrada y asignar un vigilante.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4036, 'ru-RU', 'Получить утвержденный наряд-допуск на работы в ОЗП, вывесить результаты замеров газовой среды у входа и назначить наблюдающего.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4037, 'es-ES', 'Realizar ventilación forzada antes y durante los trabajos con un ventilador-extractor y colocar la boca de aspiración cerca de la fuente de emisión.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4037, 'ru-RU', 'Осуществлять принудительную вентиляцию до и во время работ с помощью вентилятора, располагая воздухозаборник вблизи источника выделения вредных веществ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4038, 'es-ES', 'Verificar con un anemómetro el caudal de impulsión y extracción del ventilador para asegurar un número suficiente de renovaciones de aire por hora en relación con el volumen del espacio.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4038, 'ru-RU', 'Проверить анемометром производительность приточной и вытяжной вентиляции для обеспечения достаточной кратности воздухообмена в зависимости от объема помещения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4039, 'es-ES', 'Inspeccionar el cableado de alimentación del ventilador para detectar cortocircuitos o enredos y prevenir paradas inesperadas del equipo de ventilación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4039, 'ru-RU', 'Проверить силовой кабель вентилятора на предмет короткого замыкания и перекручивания, чтобы предотвратить внезапную остановку вентиляционной установки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4040, 'es-ES', 'Antes de realizar trabajos en caliente, confirmar que la concentración de vapores y gases inflamables en el espacio confinado es inferior al 10% del Límite Inferior de Explosividad (LIE).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4040, 'ru-RU', 'Перед началом огневых работ убедиться, что концентрация паров и горючих газов в ОЗП составляет менее 10% от нижнего концентрационного предела распространения пламени (НКПР).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4041, 'es-ES', 'Realizar una inspección completa para verificar el uso de iluminación antideflagrante, herramientas eléctricas antideflagrantes y herramientas manuales antichispa en el área de trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4041, 'ru-RU', 'Провести полную проверку использования в рабочей зоне взрывозащищенного освещения, взрывозащищенных электроинструментов и искробезопасного ручного инструмента.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4042, 'es-ES', 'Instalar pantallas y mantas ignífugas para contener las proyecciones y asignar un vigilante de incendios para supervisar constantemente las brasas residuales y los signos de ignición.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4042, 'ru-RU', 'Установить защитные экраны и огнеупорные полотна, а также назначить наблюдателя за пожарной безопасностью для постоянного контроля за остаточными искрами и признаками возгорания.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4043, 'es-ES', 'Asignar un vigilante en la entrada y establecer comunicación regular con los trabajadores del interior cada 15 minutos mediante radio.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4043, 'ru-RU', 'Назначить наблюдающего у входа и поддерживать с ним регулярную связь по рации с интервалом в 15 минут.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4044, 'es-ES', 'Verificar la disponibilidad de un trípode de rescate, un arnés de seguridad y una cuerda de rescate específica para la evacuación inmediata en caso de emergencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4044, 'ru-RU', 'Проверить наличие спасательного трипода, страховочной привязи и специального спасательного каната для немедленной эвакуации в случае аварии.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4045, 'es-ES', 'Mantener actualizada la lista de contactos de emergencia para un reporte rápido de incidentes y conocer la ubicación del kit de respuesta a emergencias más cercano.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4045, 'ru-RU', 'Актуализировать план экстренной связи для оперативного оповещения об аварии и знать местоположение ближайшего комплекта для ликвидации аварийных ситуаций.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4046, 'es-ES', 'Realizar formación sobre la Ficha de Datos de Seguridad (FDS) antes de manipular productos químicos y comprobar la adecuación de los guantes resistentes a productos químicos, gafas de seguridad y filtros de la mascarilla.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4046, 'ru-RU', 'Перед работой с химическими веществами провести инструктаж по паспорту безопасности (MSDS) и проверить соответствие химически стойких перчаток, защитных очков и фильтров респиратора.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4047, 'es-ES', 'Considerar la sustitución por agentes de limpieza de baja toxicidad y no inflamables para las tareas de limpieza, y seguir los procedimientos para minimizar su uso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4047, 'ru-RU', 'Рассмотреть возможность замены на малотоксичные и негорючие чистящие средства и соблюдать процедуры по минимизации их использования.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4048, 'es-ES', 'Asegurar rutas de acceso despejadas a las duchas de emergencia y a las estaciones lavaojos para un lavado inmediato en caso de exposición a productos químicos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4048, 'ru-RU', 'Обеспечить свободный доступ к аварийным душам и фонтанчикам для промывки глаз для немедленного смыва химических веществ в случае контакта.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4049, 'es-ES', 'Antes de la limpieza, drenar completamente los residuos del interior del recipiente y medir la concentración después de purgar con gas inerte.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4049, 'ru-RU', 'Перед очисткой полностью слить остатки из емкости и провести замер концентрации после продувки инертным газом.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4050, 'es-ES', 'Verificar que el filtro del equipo de respiración con suministro de aire o de la mascarilla sea el adecuado para la sustancia manipulada.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4050, 'ru-RU', 'Проверить, что фильтр используемого шлангового противогаза или респиратора соответствует обрабатываемому веществу.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4051, 'es-ES', 'Mantener la válvula de purga abierta durante las operaciones de limpieza y disponer de un equipo de izado para evacuación de emergencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4051, 'ru-RU', 'Поддерживать дренажный клапан в открытом положении во время очистных работ и обеспечить наличие подъемного механизма для аварийной эвакуации.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4052, 'es-ES', 'Verificar los valores calculados de temperatura y presión de reacción esperadas antes de añadir el agente neutralizante, e inyectarlo en pequeñas cantidades y por etapas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4052, 'ru-RU', 'Перед добавлением нейтрализующего агента проверить расчетные значения ожидаемой температуры и давления реакции и осуществлять поэтапное введение малыми дозами.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4053, 'es-ES', 'Prevenir un aumento brusco de la temperatura verificando el correcto funcionamiento del sistema de suministro de agua de refrigeración y del equipo de agitación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4053, 'ru-RU', 'Предотвращать резкое повышение температуры путем проверки исправности системы подачи охлаждающей воды и перемешивающего устройства.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4054, 'es-ES', 'Inspeccionar la válvula de corte de emergencia y el interruptor de parada de emergencia del sistema de dosificación automática de agente neutralizante cerca del reactor.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4054, 'ru-RU', 'Проверить аварийный отсечной клапан и кнопку аварийной остановки автоматической системы подачи нейтрализатора, расположенные вблизи реактора.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4055, 'es-ES', 'Antes de entrar en un foso subterráneo, realizar una medición precisa de la posible acumulación de gases en la parte inferior y efectuar una ventilación forzada simultánea en las zonas superior e inferior.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4055, 'ru-RU', 'Перед входом в подземный приямок провести точное измерение на предмет скопления газов в нижней части и обеспечить одновременную принудительную вентиляцию верхней и нижней зон.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4056, 'es-ES', 'Durante trabajos en caliente, monitorizar continuamente la concentración de gases dentro del foso y verificar el uso de equipos antideflagrantes (certificación ATEX).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4056, 'ru-RU', 'При проведении огневых работ постоянно контролировать концентрацию газов внутри приямка и проверять использование взрывозащищенного оборудования.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4057, 'es-ES', 'Prohibir estrictamente cualquier actividad que pueda generar fuentes de ignición cerca de la entrada al foso y colocar señales de advertencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4057, 'ru-RU', 'Строго запретить действия, создающие источники зажигания, вблизи входа в приямок и установить предупреждающие знаки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4058, 'es-ES', 'Antes de desmontar, confirmar el cierre de la válvula de suministro de vapor y eliminar completamente la presión residual interna de la tubería mediante la purga de condensado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4058, 'ru-RU', 'Перед демонтажем убедиться в перекрытии клапана подачи пара и полностью стравить остаточное давление в трубопроводе через дренаж конденсата.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4059, 'es-ES', 'Medir la temperatura de la superficie de la tubería y, tras confirmar un enfriamiento suficiente, usar los Equipos de Protección Individual (EPI) específicos (guantes resistentes al calor, pantalla facial).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4059, 'ru-RU', 'Измерить температуру поверхности трубопровода и после подтверждения достаточного охлаждения использовать специальные СИЗ (термостойкие перчатки, лицевой щиток).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4060, 'es-ES', 'Al aflojar inicialmente los pernos, seguir un procedimiento de desapriete gradual para realizar una doble comprobación de posibles fugas de vapor residual.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4060, 'ru-RU', 'При первоначальном ослаблении болтов соблюдать процедуру постепенного откручивания для перекрестной проверки на предмет утечек остаточного пара.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4061, 'es-ES', 'Realizar una inspección final de la instalación de dispositivos de consignación y etiquetado (LOTO) en los puntos de aislamiento de energía y de la correcta colocación de las etiquetas de ''No operar''.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4061, 'ru-RU', 'Выполнить финальную проверку установки блокировочных устройств и маркировочных бирок (система ЛОТО) на точках изоляции энергии и правильности их размещения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4062, 'es-ES', 'Aplicar el método de doble bloqueo y purga (Double Block and Bleed) para un aislamiento seguro y verificar la estanqueidad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4062, 'ru-RU', 'Применять метод двойной блокировки и спуска (Double Block and Bleed) для надежной изоляции и проверить герметичность.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4063, 'es-ES', 'Antes y después del trabajo, verificar el estado de apertura/cierre de las válvulas comparándolo con los planos y controlar su manipulación por un supervisor designado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4063, 'ru-RU', 'До и после работы сверять состояние открытия/закрытия клапанов со схемами и контролировать их управление через специально назначенного наблюдателя.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4064, 'es-ES', 'Controlar el acceso a la sala eléctrica y, antes de trabajar, abrir el interruptor y volver a confirmar la ausencia de tensión con un detector sin contacto.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4064, 'ru-RU', 'Контролировать доступ в электрощитовую, перед началом работ отключить автомат и повторно проверить отсутствие напряжения бесконтактным указателем.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4065, 'es-ES', 'Revisar el estado de los guantes dieléctricos para alta tensión, el calzado aislante, las alfombras aislantes y las planchas de goma de descarga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4065, 'ru-RU', 'Проверить состояние специальных диэлектрических перчаток для высокого напряжения, изолирующей обуви, диэлектрических ковриков и резиновых разрядных матов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4066, 'es-ES', 'Tras la desconexión, asegurar una conexión firme de la pica de puesta a tierra para descargar la carga eléctrica residual.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4066, 'ru-RU', 'После отключения напряжения убедиться в надежном присоединении заземляющего стержня для снятия остаточного заряда.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4067, 'es-ES', 'Antes de la prueba de funcionamiento, comprobar el par de apriete de las bornas de conexión y eliminar por completo cualquier residuo (virutas metálicas, restos de cable).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4067, 'ru-RU', 'Перед пробным пуском проверить момент затяжки клеммных соединений и полностью удалить посторонние предметы (металлическую стружку, обрезки проводов).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4068, 'es-ES', 'Realizar una comprobación final del uso de la ropa de protección y la pantalla facial adecuadas para el nivel de protección contra arco eléctrico (Arc Flash).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4068, 'ru-RU', 'Окончательно проверить наличие и использование специального защитного костюма и лицевого щитка, соответствующих классу защиты от электрической дуги.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4069, 'es-ES', 'Instalar una valla para prohibir el acceso de personal no autorizado al área de pruebas y conocer la ubicación de los interruptores de parada de emergencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4069, 'ru-RU', 'Установить ограждение для запрета доступа посторонних лиц в зону испытаний и ознакомиться с расположением кнопок аварийной остановки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4070, 'es-ES', 'Revisar la eliminación de humedad en el área del horno de fusión y verificar la instalación de pantallas ignífugas para proteger contra salpicaduras a alta temperatura.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4070, 'ru-RU', 'Проверить отсутствие влаги в зоне плавильной печи и убедиться в установке огнеупорных экранов для защиты от высокотемпературных брызг.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4071, 'es-ES', 'Supervisar constantemente el uso por parte de los trabajadores de los EPI específicos como ropa ignífuga, trajes de protección aluminizados y protectores faciales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4071, 'ru-RU', 'Постоянно контролировать ношение работниками специальной огнестойкой одежды, алюминизированных защитных костюмов и средств защиты лица.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4072, 'es-ES', 'Eliminar obstáculos en la ruta de transporte de metal fundido y restringir el acceso de peatones mediante un señalista exclusivo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4072, 'ru-RU', 'Очистить от препятствий маршрут транспортировки расплавленного металла и обеспечить блокировку доступа пешеходов с помощью выделенного сигнальщика.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4073, 'es-ES', 'Inspeccionar previamente la integridad y el estado de la soldadura de los cáncamos de izado (Pad eyes) según el centro de gravedad del bloque de gran tamaño.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4073, 'ru-RU', 'Предварительно проверить исправность и состояние сварных швов подъемных проушин (рым-болтов) с учетом центра тяжести сверхгабаритного блока.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4074, 'es-ES', 'Verificar los datos del anemómetro, cumplir con la directriz de suspender el izado con vientos fuertes y activar un sistema de señales unificado entre grúas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4074, 'ru-RU', 'Проверить данные анемометра, соблюдать инструкцию по прекращению подъема при сильном ветре и задействовать единую систему сигналов между кранами.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4075, 'es-ES', 'Establecer una zona de exclusión bajo la trayectoria de izado y verificar la instalación de vallas de prohibición de acceso y la asignación de supervisores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4075, 'ru-RU', 'Установить контролируемую зону под траекторией подъема груза и проверить наличие ограждений, запрещающих вход, и расстановку наблюдателей.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4076, 'es-ES', 'Antes de pintar, medir la concentración de disolventes orgánicos y oxígeno en el espacio confinado y realizar mediciones periódicas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4076, 'ru-RU', 'Перед окрасочными работами измерить концентрацию органических растворителей и кислорода в замкнутом пространстве и проводить периодические повторные замеры.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4077, 'es-ES', 'Verificar la extracción forzada de vapores nocivos y la circulación de aire mediante ventiladores antideflagrantes de gran capacidad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4077, 'ru-RU', 'Обеспечить принудительное удаление вредных паров и циркуляцию воздуха с помощью мощных взрывозащищенных вентиляторов и проверить их работу.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4078, 'es-ES', 'Inspeccionar de forma exhaustiva el uso de equipos de respiración con suministro de aire individuales y de equipos específicos como iluminación y radios antideflagrantes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4078, 'ru-RU', 'Провести полную проверку использования индивидуальных шланговых противогазов и специального оборудования, такого как взрывозащищенное освещение и радиостанции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4079, 'es-ES', 'Antes de entrar en el horno, asegurar un tiempo de enfriamiento suficiente, medir la concentración de gases internos y mantener el ventilador en funcionamiento continuo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4079, 'ru-RU', 'Перед входом в печь обеспечить достаточное время для охлаждения, измерить концентрацию газов внутри и поддерживать постоянную работу вентилятора.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4080, 'es-ES', 'Revisar el uso de los equipos de protección obligatorios, como trajes de protección aluminizados para trabajos a alta temperatura y equipos de respiración con suministro de aire.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4080, 'ru-RU', 'Проверить наличие обязательных средств защиты, таких как алюминизированный костюм для работ при высоких температурах и шланговый противогаз.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4081, 'es-ES', 'Gestionar la fatiga del trabajador concediendo pausas de descanso regulares y fomentando la monitorización mutua del estado de salud entre compañeros.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4081, 'ru-RU', 'Организовать управление утомляемостью работников путем предоставления регулярных перерывов для отдыха и взаимного контроля за состоянием здоровья между коллегами.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4082, 'es-ES', 'Durante el mantenimiento de los rodillos de laminación, desconectar la alimentación principal, instalar un dispositivo de consignación (LOTO) y verificar la parada total de la rotación residual.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4082, 'ru-RU', 'При обслуживании прокатных валков отключить основное питание, установить блокировочное устройство (ЛОТО) и убедиться в полной остановке остаточного вращения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4083, 'es-ES', 'Al trabajar cerca de partes giratorias, usar ropa de trabajo con mangas ajustadas y cumplir la norma de no utilizar guantes de algodón.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4083, 'ru-RU', 'При работе вблизи вращающихся частей носить спецодежду с застегнутыми манжетами и соблюдать запрет на использование хлопчатобумажных перчаток.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4084, 'es-ES', 'Inspeccionar periódicamente el estado de funcionamiento de las barandillas de seguridad y los interruptores de parada de emergencia por cable (Pull-cord) alrededor de las partes móviles del equipo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4084, 'ru-RU', 'Регулярно проверять исправность защитных ограждений и тросовых выключателей аварийной остановки (Pull-cord) вокруг движущихся частей оборудования.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4085, 'es-ES', 'Antes de realizar trabajos en altura, llevar a cabo una inspección completa del anclaje de las plataformas del andamio y de la integridad estructural de las barandillas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4085, 'ru-RU', 'Перед началом работ на высоте провести полную проверку крепления настилов лесов и конструктивной целостности ограждений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4086, 'es-ES', 'Llevar siempre puesto el arnés de seguridad y verificar la doble conexión del gancho de seguridad a una línea de vida vertical o a una estructura sólida.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4086, 'ru-RU', 'Постоянно использовать предохранительный пояс и проверять двойное крепление карабина к вертикальной анкерной линии или прочной конструкции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4087, 'es-ES', 'Eliminar frecuentemente agua/aceite del suelo del dique para evitar resbalones y suspender inmediatamente los trabajos en altura en caso de vientos fuertes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4087, 'ru-RU', 'Для предотвращения скольжения регулярно удалять воду/масло с пола дока и немедленно прекращать работы на высоте при сильном ветре.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4088, 'es-ES', 'Revisar la estanqueidad de las conexiones de la línea de suministro de combustible e inspeccionar detalladamente la corrosión/fisuras en las tuberías de alta presión.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4088, 'ru-RU', 'Проверить герметичность соединений топливопровода и тщательно осмотреть трубопроводы высокого давления на предмет коррозии/трещин.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4089, 'es-ES', 'Asignar un vigilante de incendios en la zona de puesta en marcha y asegurar la accesibilidad a los equipos de extinción y a los botones de parada de emergencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4089, 'ru-RU', 'Разместить в зоне пусконаладочных работ наблюдателя за пожарной безопасностью и обеспечить доступ к средствам пожаротушения и кнопкам аварийной остановки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4090, 'es-ES', 'Antes del trabajo, asegurar las rutas de evacuación de emergencia y verificar el conocimiento de las funciones individuales para cada escenario de accidente.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4090, 'ru-RU', 'Перед началом работ обеспечить наличие аварийных выходов и проверить знание персоналом своих ролей в соответствии с различными сценариями аварий.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4091, 'es-ES', 'Instalar protectores específicos en los bordes afilados de las estructuras a lo largo de la ruta de tendido de cables y revisar si el revestimiento del cable está dañado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4091, 'ru-RU', 'Установить специальные защитные накладки на острые кромки конструкций по маршруту прокладки кабеля и проверить целостность его изоляции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4092, 'es-ES', 'Trabajar en equipos de dos para evitar atrapamientos y utilizar equipos de elevación específicos para mover tambores de cable pesados.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4092, 'ru-RU', 'Для предотвращения защемления работать в паре (2 человека) и использовать специальные подъемные приспособления при перемещении тяжелых кабельных барабанов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4093, 'es-ES', 'Al trabajar en áreas oscuras a bordo, instalar iluminación temporal antideflagrante para garantizar una iluminancia suficiente.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4093, 'ru-RU', 'При работе в темных зонах на борту судна установить временное взрывозащищенное освещение для обеспечения достаточной освещенности.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4100, 'es-ES', 'Antes de entrar en el tanque, medir la concentración de oxígeno y gases tóxicos en los niveles superior, medio e inferior, y aplicar ventilación forzada durante el trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4100, 'ru-RU', 'Перед входом в танк провести замеры концентрации кислорода и вредных газов на верхнем, среднем и нижнем уровнях, и обеспечить принудительную вентиляцию во время работы.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4101, 'es-ES', 'Trabajar en equipos de dos, asignar un vigilante en la entrada del tanque y mantener un sistema de comunicación regular por radio.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4101, 'ru-RU', 'Работать в паре (2 человека), выставить наблюдателя у входа в танк и поддерживать систему регулярной связи по рации.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4102, 'es-ES', 'Asegurarse de que cada trabajador lleve un detector de oxígeno personal y verificar el correcto funcionamiento del equipo de rescate, como los equipos de respiración con suministro de aire de emergencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4102, 'ru-RU', 'Обеспечить каждого работника индивидуальным газоанализатором кислорода и проверить исправность спасательного оборудования, включая аварийные шланговые противогазы.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4106, 'es-ES', 'Al apilar grandes bloques/componentes, verificar la nivelación del terreno y revisar la distribución de la carga en los soportes específicos (Stool).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4106, 'ru-RU', 'При складировании крупных блоков/секций проверить ровность основания и проконтролировать распределение нагрузки на специальные опоры (тумбы).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4107, 'es-ES', 'Asignar un señalista para identificar puntos ciegos durante el movimiento de componentes y controlar estrictamente el acceso de personal no involucrado en el radio de acción.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4107, 'ru-RU', 'Назначить сигнальщика для контроля слепых зон при перемещении секций и строго ограничить доступ посторонних в радиусе проведения работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4108, 'es-ES', 'En condiciones de vientos fuertes al aire libre, reforzar las medidas de trincaje (Lashing) y antivuelco para evitar el movimiento de los componentes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4108, 'ru-RU', 'При сильном ветре на открытой площадке усилить меры по предотвращению смещения секций с помощью дополнительных крепежных тросов (найтовов) и противооткатных упоров.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4109, 'es-ES', 'Antes del mantenimiento, desconectar la alimentación principal e instalar un candado personal y una etiqueta roja (Red Tag) por cada trabajador.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4109, 'ru-RU', 'Перед началом технического обслуживания отключить основное питание и установить индивидуальные блокировочные замки (Padlock) и красные запрещающие бирки (Red Tag) для каждого работника.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4110, 'es-ES', 'Verificar con un comprobador de tensión y manómetro el estado de descarga de energía residual (eléctrica, presión) en condensadores y tuberías.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4110, 'ru-RU', 'Проверить с помощью тестера и манометра состояние сброса остаточной энергии (электрического заряда, давления) в конденсаторах и трубопроводах.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4111, 'es-ES', 'Insertar el pasador de bloqueo mecánico (bulón de seguridad) para prevenir el descenso por gravedad de los cilindros hidráulicos/neumáticos de los actuadores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4111, 'ru-RU', 'Установить механический фиксатор (стопорный штифт) для предотвращения самопроизвольного опускания гидравлических/пневматических цилиндров привода.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4112, 'es-ES', 'Respetar la prohibición de limpiar o inspeccionar la cinta transportadora en funcionamiento y verificar el estado operativo del dispositivo de parada de emergencia por cable.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4112, 'ru-RU', 'Соблюдать запрет на очистку и осмотр работающего конвейера и проверять исправность устройства аварийной остановки (тросового выключателя).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4113, 'es-ES', 'Verificar la correcta instalación de resguardos fijos y protecciones perimetrales en las zonas con partes giratorias expuestas y prohibir el uso de ropa de trabajo holgada.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4113, 'ru-RU', 'Проверить состояние установки защитных кожухов и ограждений на участках с открытыми вращающимися частями и проинструктировать о запрете ношения свободной рабочей одежды.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4114, 'es-ES', 'Durante el mantenimiento, asegurar la desconexión de la alimentación principal del transportador y verificar la colocación de la señal de ''No operar'' y el dispositivo de bloqueo (LOTO).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4114, 'ru-RU', 'Перед техобслуживанием убедиться в отключении основного питания конвейера и проверить установку запрещающего знака и блокировочного устройства (система LOTO).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4124, 'es-ES', 'Antes de intervenir en el sistema hidráulico, parar la bomba y comprobar la despresurización de la presión residual del acumulador.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4124, 'ru-RU', 'Перед обслуживанием гидравлической системы остановить гидравлический насос и проверить сброс остаточного давления в гидроаккумуляторе.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4125, 'es-ES', 'Realizar una inspección previa de desgaste y fugas en mangueras de alta presión y racores, y utilizar pantalla facial y guantes resistentes a aceites.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4125, 'ru-RU', 'Предварительно проверить шланги высокого давления и фитинги на предмет износа и утечек; использовать защитный лицевой щиток и маслостойкие перчатки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4126, 'es-ES', 'Instalar calzos de seguridad para evitar la caída de la corredera y verificar el funcionamiento de los enclavamientos mecánicos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4126, 'ru-RU', 'Установить предохранительный блок для предотвращения падения ползуна и проверить срабатывание механической блокировки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4127, 'es-ES', 'Antes de la prueba de equilibrado de rotores, inspeccionar el apriete de los pernos de fijación y el estado de lubricación de los rodamientos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4127, 'ru-RU', 'Перед пробным пуском для балансировки вращающихся частей тщательно проверить затяжку крепёжных болтов и состояние смазки подшипников.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4128, 'es-ES', 'Instalar una barrera de protección robusta alrededor de la zona de pruebas y delimitar el área para prohibir el acceso a personal no autorizado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4128, 'ru-RU', 'Установить прочное защитное ограждение вокруг зоны испытаний и разместить барьеры для запрета доступа посторонних лиц.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4129, 'es-ES', 'Durante el arranque inicial, aumentar la velocidad de rotación gradualmente desde una velocidad baja, verificando la ausencia de vibraciones o ruidos anómalos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4129, 'ru-RU', 'При первом пуске постепенно увеличивать скорость вращения, начиная с низкой, и контролировать появление аномальных вибраций и шума.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4130, 'es-ES', 'Antes de acceder al almacén automatizado, confirmar la parada del sistema en el panel de control y activar el pulsador de parada de emergencia para mantenimiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4130, 'ru-RU', 'Перед входом в автоматизированный склад проверить на панели управления, что система остановлена, и активировать аварийную кнопку для технического обслуживания.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4131, 'es-ES', 'Para trabajos en altura, usar constantemente el arnés de seguridad, utilizar equipos de elevación específicos y delimitar una zona de exclusión inferior.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4131, 'ru-RU', 'При обслуживании на высоте постоянно использовать страховочную привязь, применять специализированные подъемные механизмы и устанавливать ограждение внизу.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4132, 'es-ES', 'Realizar los trabajos tras instalar topes de bloqueo mecánico en las horquillas y el dispositivo de elevación del transelevador.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4132, 'ru-RU', 'Приступать к работе только после установки механических стопоров на вилах и подъемном устройстве крана-штабелера.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4133, 'es-ES', 'Revisar el estado de los resguardos y protecciones de las partes giratorias y prohibir estrictamente el uso de ropa holgada y joyas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4133, 'ru-RU', 'Проверять состояние защитных кожухов и ограждений вращающихся частей и строго запрещать ношение свободной одежды и украшений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4134, 'es-ES', 'Asegurar la visibilidad de los interruptores de parada de emergencia y verificar que estén ubicados en una posición de fácil acceso durante el trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4134, 'ru-RU', 'Обеспечить хорошую видимость выключателей аварийной остановки и проверить, что они расположены в легкодоступных местах во время работы.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4135, 'es-ES', 'Cumplir con el procedimiento de consignación de energías (LOTO) antes del mantenimiento y reforzar las medidas para evitar el arranque accidental por parte de otros trabajadores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4135, 'ru-RU', 'Соблюдать процедуру блокировки источников энергии (LOTO) перед ремонтом и усилить меры по предотвращению случайного запуска оборудования другими работниками.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4136, 'es-ES', 'Verificar la instalación de material fonoabsorbente cerca de las fuentes de ruido y el estado de los soportes/silentblocks antivibratorios de la maquinaria ruidosa.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4136, 'ru-RU', 'Проверить наличие звукопоглощающих материалов вокруг источников шума и состояние виброизолирующих опор/прокладок у шумного оборудования.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4137, 'es-ES', 'Suministrar protectores auditivos individuales (tapones u orejeras), formar en su correcta colocación y verificar el uso de guantes antivibración con herramientas vibratorias.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4137, 'ru-RU', 'Обеспечить выдачу индивидуальных средств защиты слуха (берушей или наушников), обучить правилам их использования и контролировать ношение антивибрационных перчаток.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4138, 'es-ES', 'Medir los niveles de ruido/vibración y asignar rotación de puestos y pausas a los trabajadores en procesos que excedan los límites de exposición.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4138, 'ru-RU', 'Проводить замеры уровней шума/вибрации и устанавливать для работников, занятых на процессах с превышением ПДУ, сменный график и перерывы.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4139, 'es-ES', 'Medir el índice de estrés térmico (WBGT) en el lugar de trabajo y verificar el cumplimiento de los periodos de descanso/parada según el nivel de riesgo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4139, 'ru-RU', 'Проводить замеры индекса тепловой нагрузки среды (ТНС-индекс) на рабочем месте и контролировать соблюдение режимов труда и отдыха в зависимости от уровня риска.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4140, 'es-ES', 'Inspeccionar la instalación de ventiladores y aires acondicionados portátiles, y la disponibilidad de agua potable y soluciones de rehidratación oral (sales).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4140, 'ru-RU', 'Проверить установку промышленных вентиляторов, мобильных кондиционеров и наличие достаточного количества питьевой воды и солевых растворов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4141, 'es-ES', 'Evaluar el estado físico del trabajador antes de tareas en ambiente caluroso y aplicar un sistema de vigilancia mutua (buddy system) entre compañeros.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4141, 'ru-RU', 'Проверять состояние здоровья работников перед работой в условиях высоких температур и применять систему взаимного контроля (работа в парах).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4142, 'es-ES', 'Asegurar el funcionamiento de los sistemas de extracción localizada en procesos con generación de polvo y revisar constantemente la succión de la campana y el estado del filtro.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4142, 'ru-RU', 'Обеспечить работу местной вытяжной вентиляции на процессах с выделением пыли и постоянно проверять силу всасывания и состояние фильтров.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4143, 'es-ES', 'Proporcionar mascarillas de protección respiratoria adecuadas para cada tarea (FFP2/FFP3) y verificar periódicamente su ajuste facial (Fit-test).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4143, 'ru-RU', 'Выдавать соответствующие респираторы (класса FFP2/FFP3) для каждого вида работ и регулярно проверять плотность их прилегания к лицу (фит-тест).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4144, 'es-ES', 'Aplicar métodos húmedos (riego con agua) para evitar la dispersión de polvo y verificar el correcto cubrimiento y protección de las áreas de trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4144, 'ru-RU', 'Применять мокрый способ обработки (орошение водой) для предотвращения распространения пыли и проверять состояние укрытий в рабочей зоне.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4145, 'es-ES', 'Antes de la irradiación, inspeccionar la delimitación de la zona controlada y la instalación de barreras de acceso y señalización luminosa de advertencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4145, 'ru-RU', 'Перед началом облучения полностью проверить установку ограждений контролируемой зоны, барьеров доступа и световых предупреждающих сигналов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4146, 'es-ES', 'Comprobar el uso del dosímetro personal por parte de cada trabajador y medir frecuentemente la tasa de dosis en el área con un monitor de radiación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4146, 'ru-RU', 'Проверять наличие и правильное ношение индивидуальных дозиметров у работников и постоянно измерять мощность дозы в окружающей среде с помощью радиометра.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4147, 'es-ES', 'Antes de exponer la fuente radiactiva, confirmar la evacuación del personal cercano y verificar el uso del colimador de blindaje adecuado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4147, 'ru-RU', 'Перед извлечением источника ионизирующего излучения убедиться в эвакуации персонала и проверить соблюдение правил использования защитного коллиматора.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4148, 'es-ES', 'Realizar formación sobre la Ficha de Datos de Seguridad (FDS) antes de manipular productos químicos y comprobar el uso de los EPI específicos para cada sustancia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4148, 'ru-RU', 'Провести инструктаж по паспорту безопасности химической продукции (MSDS) перед работой и проверить использование СИЗ, предназначенных для данных веществ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4149, 'es-ES', 'Verificar la instalación de detectores de gas en tiempo real y el funcionamiento del sistema de ventilación para evitar la acumulación de vapores nocivos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4149, 'ru-RU', 'Проверить наличие стационарных газоанализаторов и работу вентиляторов для предотвращения скопления вредных паров в рабочей зоне.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4150, 'es-ES', 'Comprobar el correcto funcionamiento de los equipos de emergencia (duchas y lavaojos) y despejar los obstáculos de sus rutas de acceso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4150, 'ru-RU', 'Проверить работоспособность аварийных установок (душей, фонтанчиков для промывки глаз) и устранить препятствия на путях доступа к ним.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4151, 'es-ES', 'Verificar la sujeción de las botellas de gas con cadenas o soportes específicos y el etiquetado con el nombre y las propiedades del gas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4151, 'ru-RU', 'Проверить фиксацию газовых баллонов специальными цепями/хомутами и наличие маркировки с названием и свойствами газа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4152, 'es-ES', 'Inspeccionar periódicamente la estanqueidad de las conexiones de las tuberías y confirmar el correcto funcionamiento de la alarma de detección de fugas de gas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4152, 'ru-RU', 'Регулярно проверять герметичность соединений трубопроводов и убедиться в исправности сигнализатора утечки газа.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4153, 'es-ES', 'Conocer la ubicación de la válvula de corte de emergencia del suministro de gas y asegurar la accesibilidad a las duchas de emergencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4153, 'ru-RU', 'Знать расположение главного клапана аварийного отключения подачи газа и обеспечить доступ к аварийным душевым установкам.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4154, 'es-ES', 'Antes de entrar a un tanque de aguas residuales, medir la concentración de oxígeno y ácido sulfhídrico y mantener la ventilación forzada en funcionamiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4154, 'ru-RU', 'Перед входом в резервуар для сточных вод измерить концентрацию кислорода и сероводорода и обеспечить постоянную работу принудительной вентиляции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4155, 'es-ES', 'Cumplir el principio de trabajo en parejas, con un vigilante en el exterior, y verificar la comunicación regular por radio.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4155, 'ru-RU', 'Соблюдать принцип работы в паре (минимум 2 человека) с наблюдающим снаружи и проверять регулярность радиосвязи.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4156, 'es-ES', 'Verificar que cada trabajador lleve un detector de gas portátil y revisar la disponibilidad de equipos de respiración autónoma y de rescate vertical.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4156, 'ru-RU', 'Проверить наличие у каждого работника портативного газоанализатора и исправность аварийных дыхательных аппаратов на сжатом воздухе и спасательного оборудования.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4157, 'es-ES', 'Antes de usar la Cabina de Seguridad Biológica (CSB), verificar con un anemómetro que la velocidad del aire frontal y el flujo descendente (downflow) estén en el rango normal.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4157, 'ru-RU', 'Перед началом работы в боксе биологической безопасности (БББ) проверить анемометром скорость входящего и нисходящего потоков воздуха.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4158, 'es-ES', 'Comprobar la lectura del manómetro diferencial del filtro HEPA y revisar periódicamente el funcionamiento de la lámpara de esterilización UV.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4158, 'ru-RU', 'Проверить показания дифференциального манометра HEPA-фильтра и регулярно контролировать исправность УФ-лампы для стерилизации.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4159, 'es-ES', 'Realizar la descontaminación interna al finalizar el experimento y cumplir con el uso de EPI para riesgo biológico (mascarilla, guantes).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4159, 'ru-RU', 'После завершения эксперимента провести внутреннюю стерилизацию и соблюдать использование СИЗ для биологической безопасности (маска, перчатки).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4160, 'es-ES', 'Mantener la guillotina frontal de la vitrina de gases a la altura de trabajo recomendada y revisar constantemente el funcionamiento del extractor.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4160, 'ru-RU', 'Поддерживать переднюю заслонку вытяжного шкафа на надлежащей высоте и постоянно проверять работу вытяжного вентилятора.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4161, 'es-ES', 'Prohibido almacenar reactivos dentro de la vitrina; verificar que el conducto de extracción no esté obstruido y usar tubos de humo para comprobar el flujo de aire.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4161, 'ru-RU', 'Не хранить реактивы внутри шкафа, проверять отсутствие засоров в вытяжке и использовать дымовые трубки для визуализации потока воздуха.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4162, 'es-ES', 'Confirmar el funcionamiento de la vitrina antes de manipular productos químicos y disponer de filtros para máscara respiratoria específicos para la sustancia a manejar.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4162, 'ru-RU', 'Перед работой с химикатами убедиться в исправности вытяжного шкафа и иметь в наличии фильтры для противогаза, соответствующие используемому веществу.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4163, 'es-ES', 'Al manipular nitrógeno líquido, es obligatorio el uso de guantes criogénicos, gafas de seguridad y protector facial. Verificar su uso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4163, 'ru-RU', 'При работе с жидким азотом проверить обязательное использование специальных криогенных перчаток, защитных очков и лицевого щитка.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4164, 'es-ES', 'Inspeccionar el estado de vacío del recipiente de almacenamiento (Dewar) y la posible congelación de la válvula. Prohibido manipular en espacios pequeños y confinados.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4164, 'ru-RU', 'Проверять вакуумное состояние сосуда Дьюара и отсутствие обледенения на клапане; запрещается работать в замкнутых и тесных помещениях.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4165, 'es-ES', 'Durante las operaciones de trasvase, portar un medidor de oxígeno y realizar el trabajo en una zona con buena ventilación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4165, 'ru-RU', 'Во время заправки иметь при себе измеритель концентрации кислорода и проводить работы в хорошо проветриваемой зоне.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4166, 'es-ES', 'Realizar una inspección diaria exhaustiva del estado de funcionamiento de los seguros de esquina (twist-locks) del spreader del contenedor.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4166, 'ru-RU', 'Ежедневно проводить полную проверку рабочего состояния поворотных замков (твистлоков) контейнерного спредера.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4167, 'es-ES', 'Establecer una zona de exclusión bajo la trayectoria de elevación y cumplir las directrices para mantener la distancia de seguridad con grúas adyacentes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4167, 'ru-RU', 'Установить зону отчуждения под траекторией подъема груза и соблюдать инструкции по поддержанию безопасного расстояния от соседних кранов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4168, 'es-ES', 'Respetar los criterios de interrupción de la operativa basados en el anemómetro y, en caso de viento fuerte, asegurar la fijación de las pinzas de raíl de la grúa.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4168, 'ru-RU', 'Соблюдать критерии прекращения работы, связанные с показаниями анемометра, и при сильном ветре проверять фиксацию рельсовых захватов крана.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4169, 'es-ES', 'Prohibición estricta del acceso de peatones a las rutas de circulación exclusivas para AGV, e instalación de señalización de advertencia y vallado de seguridad perimetral.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4169, 'ru-RU', 'Строгий запрет доступа пешеходов на выделенные маршруты движения АУТС, установка предупреждающих знаков и защитных ограждений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4170, 'es-ES', 'Verificar el correcto funcionamiento de los sensores de detección de obstáculos delanteros/traseros y del parachoques de seguridad (Safety Bumper).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4170, 'ru-RU', 'Проверка исправности передних и задних датчиков обнаружения препятствий и предохранительного бампера (Safety Bumper).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4171, 'es-ES', 'Durante el mantenimiento de AGV, aislar la zona de trabajo y verificar el cumplimiento del procedimiento para el cambio a modo de operación manual.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4171, 'ru-RU', 'При техническом обслуживании АУТС обеспечить изоляцию ремонтной зоны и проверить соблюдение процедуры переключения в ручной режим управления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4172, 'es-ES', 'Inspección periódica de las estructuras de las estanterías para detectar deformaciones, corrosión y verificar el apriete de los pernos, así como el cumplimiento de la señalización de carga máxima permitida.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4172, 'ru-RU', 'Регулярный осмотр несущих конструкций стеллажей на предмет деформации, коррозии и состояния болтовых соединений, а также соблюдение требований табличек с указанием допустимой нагрузки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4173, 'es-ES', 'Comprobar la instalación de redes de seguridad posteriores (back-nets) y protectores de extremos para prevenir la caída de cargas almacenadas en altura.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4173, 'ru-RU', 'Проверка установки специальных защитных сеток (задних сеток) и торцевых ограждений для предотвращения падения грузов с верхних ярусов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4174, 'es-ES', 'Instalar protectores de puntal en las estanterías para prevenir colisiones con carretillas elevadoras y garantizar en todo momento la anchura adecuada de los pasillos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4174, 'ru-RU', 'Установка защитных отбойников для стоек стеллажей для предотвращения столкновений с вилочными погрузчиками и постоянное обеспечение достаточной ширины проходов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4175, 'es-ES', 'Al acoplar un camión en el muelle de carga, verificar la colocación de calzos en las ruedas, la parada del motor del vehículo y la presencia de un señalista.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4175, 'ru-RU', 'При постановке грузовика к погрузочной платформе проверить установку колёсных упоров, выключение двигателя автомобиля и наличие сигнальщика.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4176, 'es-ES', 'Asegurar una iluminación suficiente en la zona de carga y descarga y verificar la instalación de las protecciones de los rodillos de cola de los transportadores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4176, 'ru-RU', 'Обеспечение достаточной освещённости в зоне погрузочно-разгрузочных работ и проверка установки защитных кожухов на хвостовых барабанах конвейера.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4177, 'es-ES', 'Comprobar el uso de chalecos reflectantes de alta visibilidad y calzado de seguridad por parte de los trabajadores, y utilizar luces estroboscópicas durante las operaciones de carga/descarga nocturnas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4177, 'ru-RU', 'Проверка ношения работниками сигнальных жилетов со световозвращающими элементами и спецобуви, а также использование проблесковых маячков при ночных погрузочно-разгрузочных работах.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4178, 'es-ES', 'Antes de la elevación, inspeccionar el estado de los elementos de amarre (cables, eslingas) y verificar el centro de gravedad de la carga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4178, 'ru-RU', 'Перед началом грузоподъёмных работ проверить грузозахватные приспособления (стальные канаты, стропы) на наличие повреждений и определить центр тяжести груза.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4179, 'es-ES', 'Delimitar una zona de exclusión bajo la carga suspendida y establecer un canal de comunicación por radio exclusivo entre el señalista y el operador de la grúa.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4179, 'ru-RU', 'Обозначить контролируемую зону под поднимаемым грузом и обеспечить использование выделенного радиоканала для связи между сигнальщиком и крановщиком.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4180, 'es-ES', 'Verificar el respeto de la carga máxima de trabajo y comprobar el uso de cuerdas guía (tag lines) para controlar el balanceo de la carga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4180, 'ru-RU', 'Проверка соблюдения номинальной грузоподъёмности и контроль использования оттяжек (tag lines) для предотвращения раскачивания груза.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4181, 'es-ES', 'Antes de entrar en cámaras frigoríficas, medir la concentración de oxígeno en su interior y mantener un registro de control de acceso del personal.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4181, 'ru-RU', 'Перед входом в холодильную камеру измерить концентрацию кислорода внутри и вести учётный журнал входа/выхода персонала.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4182, 'es-ES', 'Realizar una comprobación diaria del correcto funcionamiento del dispositivo de apertura de emergencia desde el interior y de la alarma de hombre encerrado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4182, 'ru-RU', 'Ежедневная проверка исправности устройства аварийного открытия двери изнутри (ручки безопасности) и кнопки аварийной сигнализации.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4183, 'es-ES', 'Proporcionar equipos de protección contra el frío, prohibir el trabajo en solitario y verificar periódicamente el sistema de comunicación por radio.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4183, 'ru-RU', 'Обеспечение работников средствами индивидуальной защиты от холода, запрет на работу в одиночку и проверка работоспособности системы регулярной радиосвязи.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4184, 'es-ES', 'Durante el mantenimiento del clasificador, aplicar el procedimiento de consignación (LOTO) cortando la alimentación principal y verificar la disipación completa de la energía rotacional residual.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4184, 'ru-RU', 'При обслуживании сортировщика отключить основное питание, применить систему блокировки и маркировки (LOTO) и убедиться в полной остановке вращения по инерции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4185, 'es-ES', 'Verificar el estado de las guardas y resguardos de protección en las partes móviles expuestas y prohibir el uso de ropa de trabajo holgada.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4185, 'ru-RU', 'Проверка состояния защитных кожухов и ограждений на открытых вращающихся частях оборудования и запрет на ношение свободной спецодежды.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4186, 'es-ES', 'Asegurar la accesibilidad a los dispositivos de parada de emergencia por cable (pull-cord) y realizar comprobaciones periódicas de su funcionamiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4186, 'ru-RU', 'Обеспечение свободного доступа к аварийным тросовым выключателям (pull-cord) и проведение регулярных проверок их работоспособности.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4193, 'es-ES', 'Verificar el funcionamiento del sistema de ventilación para prevenir la acumulación de hidrógeno gaseoso en la estación de carga y comprobar los detectores de gas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4193, 'ru-RU', 'Проверка работы вентиляционной системы для предотвращения скопления газообразного водорода на зарядной станции и контроль исправности газоанализаторов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4194, 'es-ES', 'Retirar los materiales inflamables de las proximidades del cargador, disponer de extintores adecuados y revisar el estado del aislamiento del cableado eléctrico.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4194, 'ru-RU', 'Удаление легковоспламеняющихся материалов из зоны вблизи зарядного устройства, размещение специальных огнетушителей и проверка состояния изоляции электропроводки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4195, 'es-ES', 'Comprobar la correcta conexión del conector de carga y vigilar continuamente la aparición de signos de sobrecalentamiento (olor a quemado, decoloración) durante la carga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4195, 'ru-RU', 'Проверка надёжности соединения зарядного коннектора и постоянный мониторинг признаков перегрева во время зарядки (запах гари, изменение цвета).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4205, 'es-ES', 'Inspeccionar periódicamente las salas de máquinas frigoríficas y las uniones de las tuberías para detectar fugas de refrigerante mediante prueba de burbujas y revisar los equipos de detección.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4205, 'ru-RU', 'Регулярная проверка на утечку хладагента в машинном отделении и на соединениях трубопроводов с помощью пенного теста и периодический осмотр измерительных приборов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4206, 'es-ES', 'Verificar la interconexión entre los detectores de fugas de refrigerante y los extractores de emergencia, y comprobar la disponibilidad de máscaras de gas de protección individual.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4206, 'ru-RU', 'Проверка сопряжённой работы датчиков утечки хладагента и аварийных вентиляторов, а также контроль наличия индивидуальных противогазов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4207, 'es-ES', 'Disponer de las Fichas de Datos de Seguridad (FDS) para los refrigerantes utilizados y formar al personal en los procedimientos de evacuación y de accionamiento de las válvulas de cierre de emergencia en caso de fuga.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4207, 'ru-RU', 'Обеспечение наличия паспортов безопасности (MSDS) на используемые хладагенты и обучение персонала процедурам эвакуации и перекрытия аварийных запорных клапанов при утечке.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4208, 'es-ES', 'Garantizar la visibilidad y accesibilidad de los equipos de lucha contra incendios (extintores, bocas de incendio equipadas) y realizar sus inspecciones periódicas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4208, 'ru-RU', 'Обеспечение видимости и доступности средств пожаротушения на рабочем месте (огнетушители, внутренние пожарные краны) и проведение их регулярных проверок.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4209, 'es-ES', 'Respetar la prohibición de fumar fuera de las zonas designadas y controlar estrictamente los trabajos en caliente cerca de materiales combustibles.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4209, 'ru-RU', 'Соблюдение запрета на курение вне специально отведённых мест и строгий контроль за проведением огневых работ вблизи горючих материалов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4210, 'es-ES', 'Prohibir la obstaculización de las salidas de emergencia y vías de evacuación, y verificar permanentemente el correcto funcionamiento del alumbrado de emergencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4210, 'ru-RU', 'Запрет на загромождение аварийных выходов и эвакуационных путей и постоянный контроль исправности световых указателей эвакуации.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4211, 'es-ES', 'Comprobar la conexión a tierra de los equipos eléctricos y verificar que no haya partes activas expuestas debido a daños en las carcasas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4211, 'ru-RU', 'Проверка состояния заземления электрооборудования и отсутствия оголённых токоведущих частей из-за повреждения корпуса.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4212, 'es-ES', 'Realizar pruebas periódicas del correcto funcionamiento de los interruptores diferenciales (ID) y restringir el uso de equipos eléctricos en lugares húmedos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4212, 'ru-RU', 'Регулярная проверка работоспособности устройств защитного отключения (УЗО) и ограничение использования электрооборудования во влажных помещениях.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4213, 'es-ES', 'Al realizar el mantenimiento de instalaciones eléctricas, aplicar el procedimiento de consignación (LOTO) tras desconectar la alimentación y verificar la señalización.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4213, 'ru-RU', 'При ремонте электроустановок после отключения питания проверить применение системы блокировки и маркировки (LOTO) и установку запрещающих плакатов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4214, 'es-ES', 'Eliminar derrames de agua o aceite de las zonas de paso peatonal y comprobar el estado de las cintas antideslizantes.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4214, 'ru-RU', 'Удаление влаги и масляных пятен с пешеходных дорожек и проверка состояния противоскользящих лент (Anti-slip).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4215, 'es-ES', 'Instalar señalización de advertencia de alta visibilidad en salientes y bordes de escalones, y asegurar un nivel de iluminación adecuado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4215, 'ru-RU', 'Установка хорошо заметной предупреждающей маркировки на выступающих частях и кромках ступеней и обеспечение достаточной освещённости.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4216, 'es-ES', 'Delimitar zonas de no almacenamiento no autorizado y aplicar los principios de orden y limpieza (5S) para mantener despejados los pasillos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4216, 'ru-RU', 'Определение зон, запрещённых для несанкционированного складирования материалов, и внедрение системы 5S для поддержания порядка и обеспечения ширины проходов.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4217, 'es-ES', 'Realizar estiramientos antes de la manipulación manual de cargas pesadas, trabajar en parejas y verificar el uso de ayudas mecánicas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4217, 'ru-RU', 'Выполнение растяжки перед работой с тяжестями, работа в паре (2 человека) и проверка использования механических вспомогательных средств.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4218, 'es-ES', 'Prevenir las posturas forzadas mediante el ajuste de la altura de los bancos de trabajo y la dotación de sillas ergonómicas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4218, 'ru-RU', 'Предотвращение неудобных рабочих поз путём регулировки высоты рабочих столов и предоставления эргономичных стульев.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4219, 'es-ES', 'Realizar evaluaciones periódicas de riesgos ergonómicos e implementar la rotación de puestos según la carga física de cada trabajador.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4219, 'ru-RU', 'Проведение регулярной оценки профессиональных рисков и внедрение ротации рабочих мест в соответствии с уровнем физической нагрузки на работника.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4220, 'es-ES', 'Al usar escaleras de mano, trabajar siempre en parejas (una persona sujetando la base), y revisar los dispositivos antideslizantes y estabilizadores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4220, 'ru-RU', 'При использовании лестниц соблюдать принцип работы в паре, а также проверять противоскользящие опоры и наличие стабилизаторов (аутригеров).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4221, 'es-ES', 'Utilizar en todo momento casco y arnés de seguridad, y verificar que el equipo de amarre esté anclado a una línea de vida vertical o a un punto de anclaje resistente.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4221, 'ru-RU', 'Постоянное ношение защитной каски и предохранительного пояса, проверка крепления карабина к вертикальной анкерной линии или надёжной опоре.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4222, 'es-ES', 'Comprobar visualmente la correcta instalación de las barandillas en las plataformas de trabajo y la ausencia de huecos entre los tablones.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4222, 'ru-RU', 'Визуальный контроль состояния установки верхних поручней ограждения на рабочих площадках и отсутствия зазоров между элементами настила.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4223, 'es-ES', 'Instalar carcasas insonorizantes en los equipos que generan altos niveles de ruido y proporcionar guantes antivibración para el uso de herramientas vibratorias.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4223, 'ru-RU', 'Установка звукоизолирующих кожухов на оборудовании с высоким уровнем шума и выдача антивибрационных перчаток при работе с виброинструментом.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4224, 'es-ES', 'Verificar el uso correcto de protectores auditivos individuales (tapones o orejeras) y realizar mediciones periódicas de los niveles de ruido.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4224, 'ru-RU', 'Контроль за использованием индивидуальных средств защиты слуха (беруши или наушники) и регулярное измерение уровня шума.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4225, 'es-ES', 'En caso de superar los valores límite de exposición a ruido/vibraciones, reducir el tiempo de trabajo e implementar la rotación de puestos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4225, 'ru-RU', 'При превышении предельно допустимых уровней воздействия шума/вибрации сокращать рабочее время и вводить ротацию работников.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4226, 'es-ES', 'Medir el índice WBGT según las variaciones de temperatura y establecer pausas de descanso obligatorias en función del nivel de riesgo por estrés térmico.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4226, 'ru-RU', 'Измерение индекса WBGT в соответствии с изменениями температуры и введение обязательных перерывов в зависимости от уровня тепловой нагрузки.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4227, 'es-ES', 'Disponer de zonas de descanso climatizadas, asegurar el acceso a agua potable y formar a los trabajadores sobre la importancia de la rehidratación y el consumo de sales.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4227, 'ru-RU', 'Оборудование на объекте мест для обогрева/охлаждения, обеспечение достаточным количеством питьевой воды и проведение инструктажа о необходимости восполнения солей.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4228, 'es-ES', 'Suministrar equipos de protección funcionales según la estación (chalecos refrigerantes, ropa de abrigo) y revisar su estado de conservación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4228, 'ru-RU', 'Выдача сезонных функциональных СИЗ, таких как охлаждающие жилеты или утеплённая спецодежда, и проверка их на наличие повреждений.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4229, 'es-ES', 'Asegurar el funcionamiento del sistema de extracción localizada en los procesos que generan polvo y comprobar regularmente la capacidad de aspiración de las campanas y el estado de los filtros.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4229, 'ru-RU', 'Обеспечение работы местной вытяжной вентиляции на пылеобразующих процессах и постоянный контроль эффективности всасывания вытяжных зонтов и состояния фильтров.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4230, 'es-ES', 'Proporcionar la mascarilla de protección respiratoria adecuada para cada tarea y realizar pruebas de ajuste (fit-test) periódicas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4230, 'ru-RU', 'Выдача соответствующих типу работ противопылевых респираторов и регулярное проведение проверки их прилегания к лицу (фит-тест).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4231, 'es-ES', 'Utilizar métodos de trabajo húmedos para evitar la dispersión de polvo y verificar la correcta protección de las zonas adyacentes al área de trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4231, 'ru-RU', 'Применение влажных методов работы для предотвращения распространения пыли и проверка защитного укрытия прилегающих к рабочей зоне участков.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4238, 'es-ES', 'Realizar estiramientos antes de manipular cargas pesadas, trabajar en parejas y confirmar el uso de equipos mecánicos de ayuda a la elevación.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4238, 'ru-RU', 'Выполнение разминки перед работой с тяжёлыми грузами, работа в паре (2 человека) и проверка использования механических грузоподъёмных вспомогательных устройств.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4239, 'es-ES', 'Prevenir posturas de trabajo forzadas ajustando la altura de las superficies de trabajo y proporcionando herramientas ergonómicas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4239, 'ru-RU', 'Предотвращение неестественных рабочих поз путём регулировки высоты рабочих поверхностей и обеспечения эргономичными инструментами.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4240, 'es-ES', 'Realizar evaluaciones periódicas de riesgos por trastornos musculoesqueléticos (TME) e impartir formación a los trabajadores sobre técnicas correctas de manipulación manual de cargas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4240, 'ru-RU', 'Проводить регулярную оценку профессиональных рисков, связанных с нарушениями опорно-двигательного аппарата, и организовывать обучение работников правильным методам и приемам перемещения грузов вручную.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4250, 'es-ES', 'Actualizar y publicar el listado de contactos de emergencia para cada centro de trabajo y verificar que cada persona conoce sus funciones asignadas según los diferentes escenarios de emergencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4250, 'ru-RU', 'Регулярно обновлять и размещать на видном месте списки контактов для экстренной связи на каждом объекте и проверять знание персоналом своих обязанностей согласно планам мероприятий по ликвидации аварий.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4251, 'es-ES', 'Garantizar la inspección periódica de los equipos de emergencia (botiquines, desfibriladores, camillas, etc.) y mantener despejadas las vías de acceso a los mismos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4251, 'ru-RU', 'Обеспечить регулярную проверку аварийно-спасательного оборудования (аптечек первой помощи, дефибрилляторов, носилок и т.д.) и свободный доступ к нему.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4252, 'es-ES', 'Realizar simulacros de evacuación periódicos y verificar que todo el personal ha completado la formación en primeros auxilios y uso de medios de extinción de incendios.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4252, 'ru-RU', 'Проводить периодические противоаварийные тренировки и осуществлять полную проверку прохождения персоналом обучения по оказанию первой помощи и применению первичных средств пожаротушения.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4253, 'es-ES', 'Realizar evaluaciones periódicas de riesgos psicosociales (estrés laboral) y ofrecer apoyo psicológico especializado a los trabajadores identificados en el grupo de alto riesgo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4253, 'ru-RU', 'Проводить регулярную оценку уровня профессионального стресса и предоставлять специализированную психологическую поддержку работникам из группы высокого риска.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4254, 'es-ES', 'Cumplir con las directrices para la protección de trabajadores con carga emocional y aplicar medidas de protección frente a quejas maliciosas o presión laboral indebida.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4254, 'ru-RU', 'Соблюдать руководящие принципы по защите работников, подверженных эмоциональным нагрузкам, и принимать меры по их ограждению от необоснованных жалоб и чрезмерного рабочего давления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4255, 'es-ES', 'Habilitar espacios de descanso o relajación durante el horario laboral y organizar programas corporativos de bienestar para la gestión del estrés.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4255, 'ru-RU', 'Предоставлять помещения для психологической разгрузки в рабочее время и внедрять общекорпоративные оздоровительные программы для снятия стресса.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4256, 'es-ES', 'Realizar reconocimientos médicos específicos para los trabajadores a turnos y proporcionar formación sobre la gestión de los trastornos del sueño.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4256, 'ru-RU', 'Проводить обязательные периодические медицинские осмотры для работников, занятых в сменном режиме, и предоставлять обучение по профилактике нарушений сна.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4257, 'es-ES', 'Asegurar niveles de iluminación adecuados durante el trabajo nocturno (según UNE-EN 12464-1) y reforzar las rondas de vigilancia y las comunicaciones para prevenir la somnolencia.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4257, 'ru-RU', 'Обеспечить нормативный уровень освещенности во время ночных работ (согласно ГОСТ Р 55710-2013) и усилить контрольные обходы и радиосвязь для предотвращения сонливости.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4258, 'es-ES', 'Garantizar periodos de descanso adecuados antes y después del turno de noche y ofrecer menús equilibrados para el personal nocturno.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4258, 'ru-RU', 'Гарантировать достаточные периоды отдыха до и после ночных смен и составлять сбалансированное меню для питания в ночное время.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4259, 'es-ES', 'Aumentar los niveles de iluminación en los procesos asignados a trabajadores de edad avanzada e instalar señales de advertencia de alto contraste y visibilidad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4259, 'ru-RU', 'Повысить уровень освещенности на рабочих местах, где заняты возрастные работники, и установить предупреждающие знаки с высокой контрастностью и видимостью.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4260, 'es-ES', 'Ajustar el ritmo de trabajo teniendo en cuenta la posible disminución de la fuerza y el equilibrio, y priorizar la asignación a tareas sencillas y repetitivas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4260, 'ru-RU', 'Регулировать темп работы с учетом снижения мышечной силы и чувства равновесия и в первую очередь назначать на простые, монотонные производственные операции.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4261, 'es-ES', 'Restringir la asignación a tareas de riesgo a aquellos con condiciones médicas detectadas mediante la vigilancia periódica de la salud y consultas médicas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4261, 'ru-RU', 'Ограничить допуск к работе на объекте лиц с выявленными медицинскими противопоказаниями по результатам регулярных медосмотров и консультаций.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4265, 'es-ES', 'Realizar la desinfección periódica de las zonas comunes (comedores, salas de descanso) y asegurar el cumplimiento de las normas de higiene personal (lavado de manos, uso de mascarilla).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4265, 'ru-RU', 'Проводить периодическую дезинфекцию мест общего пользования (столовых, комнат отдыха) и обеспечить соблюдение правил личной гигиены (мытье рук, ношение масок).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4266, 'es-ES', 'Apartar inmediatamente del puesto de trabajo a los trabajadores con fiebre o síntomas respiratorios y habilitar un espacio de aislamiento.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4266, 'ru-RU', 'Немедленно отстранять от работы сотрудников с повышенной температурой или респираторными симптомами и обеспечивать для них изолированное помещение.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4267, 'es-ES', 'Monitorizar constantemente la calidad del aire interior y revisar el estado de mantenimiento de los filtros de los equipos de ventilación y climatización (HVAC).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4267, 'ru-RU', 'Постоянно контролировать параметры микроклимата и качество воздуха в рабочей зоне и проверять состояние фильтров вентиляционного оборудования (очистителей воздуха, систем ОВК).', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4268, 'es-ES', 'Señalizar la ubicación de los desfibriladores externos automáticos (DEA) y los botiquines de primeros auxilios, y realizar una inspección periódica mensual de su contenido y estado.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4268, 'ru-RU', 'Обозначить знаком места размещения автоматических наружных дефибрилляторов (АНД) и аптечек первой помощи и проводить их ежемесячную проверку.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4269, 'es-ES', 'Impartir formación práctica periódica a todo el personal sobre reanimación cardiopulmonar (RCP) y uso del DEA.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4269, 'ru-RU', 'Проводить для всех сотрудников регулярное практическое обучение по сердечно-легочной реанимации (СЛР) и использованию АНД.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4270, 'es-ES', 'Verificar y actualizar constantemente la disponibilidad de los servicios de urgencias cercanos y las rutas de evacuación para ambulancias.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4270, 'ru-RU', 'Постоянно проверять и обновлять информацию о ближайших пунктах неотложной медицинской помощи и обеспечивать беспрепятственные пути для проезда машин скорой помощи.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4271, 'es-ES', 'Ajustar la altura y distancia del monitor (borde superior a la altura de los ojos) y proporcionar teclados y ratones ergonómicos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4271, 'ru-RU', 'Отрегулировать высоту и расстояние до монитора (на уровне глаз) и обеспечить работников эргономичными клавиатурами и мышами.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4272, 'es-ES', 'Respetar las pausas de 10 minutos por cada hora de trabajo con pantallas y ofrecer formación sobre estiramientos para aliviar la fatiga visual.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4272, 'ru-RU', 'Соблюдать регламентированные перерывы (10 минут каждый час) и проводить обучение упражнениям для снятия зрительного утомления.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4273, 'es-ES', 'Garantizar un nivel de iluminación adecuado en la oficina (mínimo 500 lux para tareas de oficina) y colocar filtros antirreflejos en los monitores.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4273, 'ru-RU', 'Обеспечить в офисе нормативный уровень освещенности (не менее 500 лк) и установить на мониторы антибликовые защитные экраны.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4274, 'es-ES', 'Aplicar repelente de insectos antes de realizar trabajos al aire libre y verificar el uso de equipos de protección individual (EPI) como ropa de manga larga, pantalones largos y polainas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4274, 'ru-RU', 'Перед началом работ на открытом воздухе применять репелленты и проверять использование средств индивидуальной защиты (СИЗ): спецодежды с длинными рукавами, брюк и защитных гетр.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4275, 'es-ES', 'Al trabajar en zonas de maleza, utilizar herramientas largas para inspeccionar el terreno previamente y señalizar o restringir el acceso a hábitats de serpientes o plagas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4275, 'ru-RU', 'При работе в зарослях травы и кустарника использовать шест для предварительной проверки на наличие угроз и изолировать участки, являющиеся местами обитания ядовитых змей и опасных насекомых.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4276, 'es-ES', 'Disponer de un botiquín de emergencia (con extractor de veneno, antihistamínicos) y asegurarse de que se conoce el plan de actuación y traslado urgente en caso de accidente.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4276, 'ru-RU', 'Обеспечить наличие аптечки для экстренных случаев (с аспиратором яда, антигистаминными препаратами) и ознакомить персонал с системой экстренной транспортировки пострадавших.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4277, 'es-ES', 'Verificar el uso de ropa de alta visibilidad (UNE-EN ISO 20471) y balizas luminosas LED, e instalar iluminación provisional suficiente alrededor de la zona de trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4277, 'ru-RU', 'Проверять ношение сигнальной одежды повышенной видимости (ГОСТ 12.4.281) и светодиодных сигнальных фонарей, а также устанавливать достаточное временное освещение вокруг рабочей зоны.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4278, 'es-ES', 'En condiciones de niebla o lluvia, asegurar que los vehículos y maquinaria circulen a velocidad reducida y comprobar el correcto funcionamiento de los sistemas de alumbrado y señalización.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4278, 'ru-RU', 'Соблюдать ограничение скорости для транспортных средств и оборудования при тумане или дожде и проверять исправность фар головного света и противотуманных фар.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4279, 'es-ES', 'Verificar la correcta delimitación y señalización para segregar las vías peatonales de las rutas de circulación de maquinaria mediante conos y barreras físicas.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4279, 'ru-RU', 'Проверять состояние расстановки дорожных конусов и визуальных ограждений для разделения пешеходных проходов и маршрутов движения техники.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4280, 'es-ES', 'Impartir formación periódica en seguridad y asegurar que todo el personal conozca los riesgos específicos del día a través de la charla de seguridad (Toolbox Meeting) previa al inicio de los trabajos.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4280, 'ru-RU', 'Проводить регулярный инструктаж по охране труда и обеспечивать ознакомление всего персонала с текущими опасными факторами посредством целевого инструктажа перед началом работ.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4281, 'es-ES', 'Fomentar un sistema de notificación de incidentes y cuasi-accidentes (near miss) y ofrecer incentivos a los trabajadores que demuestren un cumplimiento ejemplar de las normas de seguridad.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4281, 'ru-RU', 'Активизировать систему учета и расследования микротравм (происшествий) и поощрять работников за отличное соблюдение правил безопасности.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4282, 'es-ES', 'Fomentar una cultura de seguridad proactiva mediante la colocación de señales y carteles informativos en el lugar de trabajo y realizar campañas de sensibilización.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4282, 'ru-RU', 'Постоянно повышать уровень культуры безопасности путем размещения знаков безопасности и агитационных плакатов на объекте, а также проводить информационные кампании.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4283, 'es-ES', 'Aplicar los principios de orden y limpieza (metodología 5S) al final de cada jornada y que el supervisor verifique la eliminación de obstáculos en las vías de paso.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4283, 'ru-RU', 'Применять систему 5S (организация рабочего места) по окончании рабочей смены и осуществлять проверку со стороны руководителя работ на предмет отсутствия препятствий на проходах.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4284, 'es-ES', 'Designar y delimitar zonas de apilamiento específicas para cada tipo de material, respetando las líneas de demarcación y gestionando las alturas de apilamiento seguras.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4284, 'ru-RU', 'Выделять специальные зоны для складирования каждого вида материалов, соблюдать нанесенную разметку и контролировать допустимую высоту штабелирования.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4285, 'es-ES', 'Habilitar un punto limpio para la segregación de residuos y organizar jornadas periódicas de limpieza general en el centro de trabajo.', '2026-03-23 04:03:54.851483+00');
INSERT INTO "Current_Measures_Translations" (measure_id, locale, measure_text, created_at) VALUES (4285, 'ru-RU', 'Организовать площадки для раздельного сбора отходов и поддерживать порядок на территории путем проведения регулярных генеральных уборок (субботников).', '2026-03-23 04:03:54.851483+00');
